"""CVCI auxiliary perception, scenario recognition, and safety supervision.

Runtime code in this module must only use legal agent observations: model outputs,
raw sensors already exposed through the leaderboard interface, route planner
commands, and ego kinematics. Offline CVCI XML/catalog data is intentionally not
read here unless CVCI_ALLOW_ROUTE_PRIOR is explicitly enabled for debugging.
"""
from __future__ import absolute_import

from dataclasses import dataclass, field
import json
import os
import time
from typing import Any, Dict, List, Optional

import numpy as np

try:
    import cv2
except Exception:  # pragma: no cover - CARLA runtime already ships OpenCV.
    cv2 = None

try:
    import carla
except Exception:  # pragma: no cover - unit tests can run without CARLA.
    carla = None

try:
    # Reuse CARLA's own lateral controller implementation.  The auxiliary
    # system supplies only sensor-derived transforms/targets; it never asks
    # the controller for a world, map, waypoint lookup, or ego actor.
    from agents.navigation.controller import PIDLateralController as CarlaPIDLateralController
except Exception:  # pragma: no cover - unit tests may not ship PythonAPI agents.
    CarlaPIDLateralController = None


class _SensorTransformVehicleAdapter:
    """Expose only the transform expected by CARLA's lateral PID public API."""

    def __init__(self, transform: Any):
        self._transform = transform

    def set_transform(self, transform: Any) -> None:
        self._transform = transform

    def get_transform(self) -> Any:
        return self._transform

