def _env_flag(name: str, default: str = "0") -> bool:
    return os.environ.get(name, default).lower() in ("1", "true", "yes", "on")


def _clip(value: float, lo: float, hi: float) -> float:
    return float(np.clip(float(value), lo, hi))


