def _tracked_forward_lateral(track: Dict[str, Any]):
    """Return a track in the shared (forward, lateral) convention.

    OpenPCDet boxes use x-forward/y-lateral. DriveTransformer's legacy
    camera/model boxes use x-lateral/y-forward, and ObjectTracker preserves
    each source's native coordinates.
    """
    x_value = float(track.get("x", 999.0))
    y_value = float(track.get("y", 999.0))
    if str(track.get("source", "") or "").lower() == "openpcdet":
        return x_value, y_value
    return y_value, x_value


def _detector_forward_lateral(obj: Dict[str, Any]):
    """Return a detector box in the shared (forward, lateral) convention.

    OpenPCDet emits x-forward/y-lateral boxes.  The legacy camera/model head
    emits x-lateral/y-forward boxes.  CrazyMotor previously compared both as
    x-forward, so it ignored the real side-origin motorcycle while it was
    8--17 m ahead and occasionally reacted only after a lateral background
    proposal crossed the old axis window.
    """
    box = obj.get("box_lidar") or {}
    x_value = float(box.get("x", 999.0))
    y_value = float(box.get("y", 999.0))
    if str(obj.get("source", "") or "").lower() == "openpcdet":
        return x_value, y_value
    return y_value, x_value


def _tracked_forward_velocity(track: Dict[str, Any]) -> float:
    """Return source-normalized longitudinal velocity."""
    if str(track.get("source", "") or "").lower() == "openpcdet":
        return float(track.get("vx", 0.0) or 0.0)
    return float(track.get("vy", 0.0) or 0.0)


class AuxiliaryPerception:
    """Legal runtime perception adapter.

    It fuses DriveTransformer detections with the required OpenPCDet semantic
    3D detector and exposes a single observation dictionary for feature
    building. Raw point-cloud geometry is kept separate and cannot select a
    scene or shared rule in formal safety-only mode.
    """

    def __init__(self, config: AuxiliaryConfig):
        self.config = config
        self.lidar_detector = None
        self.lidar_geometry = None
        self.tracker = ObjectTracker() if ObjectTracker is not None else None
        self.topology = RoadTopologyExtractor()
        self.traffic_lights = TrafficLightStateAdapter()
        if config.enabled and config.perception_enabled and config.lidar_enabled and PointCloudGeometryFallback is not None:
            self.lidar_geometry = PointCloudGeometryFallback()
        if config.enabled and config.perception_enabled and config.lidar_enabled and LidarDetector is not None:
            self.lidar_detector = LidarDetector()
            if config.lidar_detector_required:
                self.lidar_detector.warmup()
        elif config.enabled and config.perception_enabled and config.lidar_enabled and config.lidar_detector_required:
            raise RuntimeError("CVCI_REQUIRED_LIDAR detector could not be imported")

    def update(self, model_detection: Dict[str, Any], tick_data: Dict[str, Any], timestamp: float) -> Dict[str, Any]:
        result = dict(model_detection or {})
        if self.lidar_detector is not None:
            try:
                detector = self.lidar_detector.latest_or_submit(tick_data.get("lidar_points"), timestamp=timestamp)
            except Exception as exc:
                if self.config.lidar_detector_required:
                    raise RuntimeError("CVCI_REQUIRED_LIDAR runtime failed: %s" % repr(exc))
                detector = {"enabled": True, "available": False, "stale": True, "status": "exception", "objects": [], "error": repr(exc)}
            result["lidar_detector"] = detector
            detector_objects = list(detector.get("objects", []) or []) if detector.get("available") and not detector.get("stale", True) else []
            if detector_objects:
                detector_timestamp = float(detector.get("timestamp", timestamp))
                timestamped_detector_objects = []
                for detector_object in detector_objects:
                    semantic_object = dict(detector_object)
                    semantic_object["measurement_timestamp"] = detector_timestamp
                    semantic_object["source"] = "openpcdet"
                    timestamped_detector_objects.append(semantic_object)
                result["objects"] = (
                    list(result.get("objects", []) or [])
                    + timestamped_detector_objects
                )
        else:
            result.setdefault("lidar_detector", None)
        if self.lidar_geometry is not None:
            try:
                result["lidar_geometry"] = self.lidar_geometry.update(tick_data.get("lidar_points"), timestamp=timestamp)
            except Exception as exc:
                result["lidar_geometry"] = {"available": False, "stale": True, "error": repr(exc)}
        else:
            result.setdefault("lidar_geometry", None)
        if self.tracker is not None:
            result["tracked_objects"] = self.tracker.update(result.get("objects", []), timestamp)
        else:
            result["tracked_objects"] = []
        result["road_topology"] = self.topology.extract(result.get("map_objects", []), tick_data)
        result["traffic_light_state"] = self.traffic_lights.estimate(
            result.get("objects", []),
            result.get("map_objects", []),
            tick_data,
        )
        return result


class RoadTopologyExtractor:
    def extract(self, map_objects: List[Dict[str, Any]], tick_data: Dict[str, Any]) -> Dict[str, Any]:
        lane_scores = []
        lateral_span = 0.0
        for obj in map_objects or []:
            cls = str(obj.get("class_name", "")).lower()
            if cls in ("broken", "solid", "solidsolid", "center"):
                lane_scores.append(float(obj.get("score", 0.0)))
                pts = np.asarray(obj.get("pts", obj.get("box", [])), dtype=np.float32).reshape(-1)
                if pts.size >= 4:
                    lateral_span = max(lateral_span, float(np.nanmax(np.abs(pts[1::2]))))
        command = str(tick_data.get("command_near", ""))
        # CARLA command ids are project-specific here, so this is only a weak
        # observable topology hint and never a scenario label.
        junction_like = command not in ("0", "1", "2", "RoadOption.LANEFOLLOW", "LANEFOLLOW", "")
        return {
            "lane_confidence": float(np.mean(lane_scores)) if lane_scores else 0.0,
            "lateral_span": lateral_span,
            "junction_like": bool(junction_like),
        }


class TrafficLightStateAdapter:
    """Estimate the state of the relevant signal from the legal front RGB.

    DriveTransformer's object/map heads label traffic-light *infrastructure*
    but do not encode its current colour.  Treating that class as synonymous
    with red caused permanent stops at green signals.  The camera colour vote
    below only decides state when a model/map light candidate is also present.
    It deliberately focuses on the central driving corridor so cross-street
    red lamps do not outvote the ego-lane overhead signal.
    """

    def __init__(self):
        self._effective_color = "unknown"
        self._green_frames = 0
        self._stop_frames = 0
        self._unknown_frames = 0
        self._green_pass_progress_m = 0.0
        self._green_pass_latched = False
        self._candidate_absent_frames = 0

    @staticmethod
    def _largest_component_area(mask: np.ndarray) -> int:
        if cv2 is None or mask.size == 0:
            return 0
        count, _, stats, _ = cv2.connectedComponentsWithStats(
            mask.astype(np.uint8), connectivity=8
        )
        if count <= 1:
            return 0
        return int(np.max(stats[1:, cv2.CC_STAT_AREA]))

    def _camera_color(self, tick_data: Dict[str, Any]) -> Dict[str, Any]:
        image = tick_data.get("rule_front_rgb")
        if image is None:
            images = tick_data.get("imgs") or {}
            image = images.get("CAM_FRONT")
        if image is None or cv2 is None:
            return {
                "observed": "unknown", "confidence": 0.0,
                "red_area": 0, "green_area": 0, "yellow_area": 0,
            }
        try:
            rgb = np.asarray(image)
            if rgb.ndim != 3 or rgb.shape[2] < 3:
                raise ValueError("invalid front RGB shape")
            # Standardise component thresholds across the 1600x900 sensor and
            # any lower-resolution diagnostic stream.  tick_data['imgs'] is
            # stored in RGB numeric channel order by the agent.
            rgb = cv2.resize(rgb[:, :, :3], (640, 360), interpolation=cv2.INTER_AREA)
            rgb = rgb.astype(np.float32)
            red, green, blue = rgb[:, :, 0], rgb[:, :, 1], rgb[:, :, 2]
            corridor = np.zeros((360, 640), dtype=bool)
            # Signal heads sit above the road horizon.  Keeping the lower
            # boundary at y=155 excludes motorcycle/car tail lamps (the
            # CrazyBike adversary appears around y=167--172) while retaining
            # the governing overhead lamps observed around y=29--131.
            corridor[18:155, 141:384] = True

            red_mask = (
                corridor
                & (red > 95.0)
                & (red > 1.35 * green)
                & (red > 1.15 * blue)
                & ((red - green) > 28.0)
            )
            green_mask = (
                corridor
                & (green > 80.0)
                & (green > 1.22 * red)
                & (green > 1.08 * blue)
                & ((green - red) > 20.0)
            )
            yellow_mask = (
                corridor
                & (red > 90.0)
                & (green > 75.0)
                & (blue < 0.72 * np.minimum(red, green))
                & (np.abs(red - green) < 65.0)
            )
            red_area = self._largest_component_area(red_mask)
            green_area = self._largest_component_area(green_mask)
            yellow_area = self._largest_component_area(yellow_mask)

            observed = "unknown"
            winning_area = 0
            runner_up = 0
            # The minimum component sizes were measured on the legal 640x360
            # RGB stream.  A relevant overhead lamp is 17--32 pixels in the
            # hardest night/rain route; distant cross-street reflections stay
            # below 12 pixels in the same central corridor.
            if green_area >= 12 and green_area >= int(1.25 * max(red_area, yellow_area, 1)):
                observed = "green"
                winning_area = green_area
                runner_up = max(red_area, yellow_area)
            elif red_area >= 12 and red_area >= int(1.20 * max(green_area, yellow_area, 1)):
                observed = "red"
                winning_area = red_area
                runner_up = max(green_area, yellow_area)
            elif yellow_area >= 8 and yellow_area >= int(1.15 * max(red_area, green_area, 1)):
                observed = "yellow"
                winning_area = yellow_area
                runner_up = max(red_area, green_area)
            confidence = (
                0.0
                if winning_area <= 0
                else float(np.clip((winning_area - runner_up) / max(winning_area, 1), 0.0, 1.0))
            )
            return {
                "observed": observed,
                "confidence": confidence,
                "red_area": red_area,
                "green_area": green_area,
                "yellow_area": yellow_area,
            }
        except Exception:
            return {
                "observed": "unknown", "confidence": 0.0,
                "red_area": 0, "green_area": 0, "yellow_area": 0,
            }

    def estimate(
        self,
        objects: List[Dict[str, Any]],
        map_objects: List[Dict[str, Any]],
        tick_data: Dict[str, Any],
    ) -> Dict[str, Any]:
        min_dist = None
        confidence = 0.0
        for obj in objects or []:
            if str(obj.get("class_name", "")).lower() != "traffic_light":
                continue
            box = obj.get("box_lidar") or {}
            x = float(box.get("x", 999.0))
            y = float(box.get("y", 999.0))
            if 0.0 <= x <= 18.0 and abs(y) <= 4.0:
                min_dist = x if min_dist is None else min(min_dist, x)
                confidence = max(confidence, float(obj.get("score", 0.0)))
        for obj in map_objects or []:
            cls = str(obj.get("class_name", "")).lower()
            if cls not in ("trafficlight", "stopsign"):
                continue
            arr = np.asarray(obj.get("box", []), dtype=np.float32).reshape(-1)
            if arr.size >= 2 and arr[0] >= -2.0 and abs(arr[1]) <= 5.0:
                dist = float(np.hypot(arr[0], arr[1]))
                if dist <= 16.0:
                    min_dist = dist if min_dist is None else min(min_dist, dist)
                    confidence = max(confidence, float(obj.get("score", 0.0)))
        color_vote = self._camera_color(tick_data)
        observed = str(color_vote.get("observed", "unknown"))
        if min_dist is None:
            self._candidate_absent_frames += 1
            self._effective_color = "unknown"
            self._green_frames = 0
            self._stop_frames = 0
            self._unknown_frames = 0
            if not self._green_pass_latched:
                self._green_pass_progress_m = 0.0
        elif observed == "green":
            self._candidate_absent_frames = 0
            self._green_frames += 1
            self._stop_frames = 0
            self._unknown_frames = 0
            if self._green_frames >= 2:
                self._effective_color = "green"
        elif observed in ("red", "yellow"):
            self._candidate_absent_frames = 0
            self._stop_frames += 1
            self._green_frames = 0
            self._unknown_frames = 0
            if self._stop_frames >= 2:
                self._effective_color = observed
        else:
            self._candidate_absent_frames = 0
            self._unknown_frames += 1
            self._green_frames = 0
            self._stop_frames = 0
            # Brief compression/rain dropouts preserve the last camera vote.
            # After 0.6 s without a colour, return to unknown; infrastructure
            # presence alone must never be promoted back into a red state.
            if self._unknown_frames > 12:
                self._effective_color = "unknown"

        # Once the vehicle has actually advanced a full-car clearance while a
        # green ego-corridor signal is confirmed, it has entered/crossed that
        # stop line legally.  A subsequent yellow/red transition must not stop
        # it in the middle of the same junction.  Re-arm only after at least
        # 20 m of intersection clearance *and* a stable 0.8 s infrastructure
        # gap, so short detector gaps inside a wide junction cannot reset it.
        try:
            green_distance_step = min(
                abs(float(tick_data.get("speed", 0.0))) * 0.10,
                1.5,
            )
        except Exception:
            green_distance_step = 0.0
        if self._green_pass_latched:
            self._green_pass_progress_m += green_distance_step
        elif min_dist is not None and self._effective_color == "green":
            self._green_pass_progress_m += green_distance_step
        if min_dist is not None and self._effective_color == "green":
            if self._green_pass_progress_m >= 5.0:
                self._green_pass_latched = True
        if (
            self._green_pass_latched
            and self._candidate_absent_frames >= 8
            and self._green_pass_progress_m >= 20.0
        ):
            self._green_pass_latched = False
            self._green_pass_progress_m = 0.0
            self._effective_color = "unknown"

        active = bool(
            min_dist is not None
            and self._effective_color in ("red", "yellow")
            and not self._green_pass_latched
        )
        return {
            "active": active,
            "distance": min_dist if active else None,
            "candidate_distance": min_dist,
            "confidence": confidence,
            "color": self._effective_color,
            "observed_color": observed,
            "color_confidence": float(color_vote.get("confidence", 0.0) or 0.0),
            "red_blob_area": int(color_vote.get("red_area", 0) or 0),
            "green_blob_area": int(color_vote.get("green_area", 0) or 0),
            "yellow_blob_area": int(color_vote.get("yellow_area", 0) or 0),
            "unknown_frames": self._unknown_frames,
            "green_pass_progress_m": self._green_pass_progress_m,
            "green_pass_latched": self._green_pass_latched,
            "candidate_absent_frames": self._candidate_absent_frames,
        }


class SceneFeatureBuilder:
    def __init__(self, config: Optional[AuxiliaryConfig] = None):
        self.config = config or AuxiliaryConfig()

    @staticmethod
    def debug_nearest_objects(observation: Dict[str, Any], limit: int = 5) -> Dict[str, Any]:
        vehicle_classes = ("car", "van", "truck", "bus", "motorcycle", "bicycle", "cyclist")
        detector_items = []
        for obj in observation.get("objects", []) or []:
            cls = str(obj.get("class_name", "")).lower()
            if cls not in vehicle_classes:
                continue
            box = obj.get("box_lidar") or {}
            try:
                x = float(box.get("x", 999.0))
                y = float(box.get("y", 999.0))
            except Exception:
                continue
            if x < -2.0:
                continue
            detector_items.append({
                "class_name": cls,
                "x": round(x, 3),
                "y": round(y, 3),
                "score": round(float(obj.get("score", obj.get("confidence", 0.0)) or 0.0), 3),
                "source": str(obj.get("source", "")),
            })
        detector_items.sort(key=lambda item: (abs(float(item["y"])), float(item["x"])))

        track_items = []
        for track in observation.get("tracked_objects", []) or []:
            cls = str(track.get("class_name", "")).lower()
            if cls not in vehicle_classes:
                continue
            x = float(track.get("x", 999.0))
            y = float(track.get("y", 999.0))
            if x < -2.0:
                continue
            track_items.append({
                "class_name": cls,
                "x": round(x, 3),
                "y": round(y, 3),
                "vx": round(float(track.get("vx", 0.0) or 0.0), 3),
                "closing_speed": round(float(track.get("closing_speed", 0.0) or 0.0), 3),
                "observed_frames": int(track.get("observed_frames", 0) or 0),
                "ttc": None if track.get("ttc") is None else round(float(track.get("ttc")), 3),
                "source": str(track.get("source", "")),
            })
        track_items.sort(key=lambda item: (abs(float(item["y"])), float(item["x"])))
        return {
            "nearest_detector_vehicles": detector_items[:limit],
            "nearest_tracked_vehicles": track_items[:limit],
        }

    def build(self, observation: Dict[str, Any], tick_data: Dict[str, Any]) -> AuxFeatures:
        feat = AuxFeatures(
            timestamp=float(observation.get("timestamp", 0.0)),
            frame=int(observation.get("frame", 0)),
            ego_speed=float(tick_data.get("speed", 0.0)),
            route_command=str(tick_data.get("command_near", "")),
            route_command_far=str(tick_data.get("command_far", "")),
            confidence=0.2,
        )
        feat.detection_object_count = len(observation.get("objects", []) or [])
        feat.detector_objects = observation.get("objects", []) or []
        feat.tracked_objects = observation.get("tracked_objects", []) or []
        advanced_state = observation.get("lidar_detector") or {}
        feat.advanced_lidar_available = bool(
            advanced_state.get("available", False)
            and advanced_state.get("status") == "ok"
        )
        feat.advanced_lidar_stale = bool(advanced_state.get("stale", True))
        try:
            feat.advanced_lidar_measurement_timestamp = float(
                advanced_state.get("timestamp")
            )
        except (TypeError, ValueError):
            feat.advanced_lidar_measurement_timestamp = None
        advanced_objects = list(advanced_state.get("objects", []) or [])
        feat.advanced_lidar_object_count = len(advanced_objects)
        nearest_semantic_key = None
        nearest_transverse_vehicle_key = None
        for advanced_obj in advanced_objects:
            cls = str(advanced_obj.get("class_name", "")).lower()
            box = advanced_obj.get("box_lidar") or {}
            try:
                forward = float(box.get("x", 999.0))
                lateral = float(box.get("y", 999.0))
                dx = abs(float(box.get("dx", 0.0) or 0.0))
                dy = abs(float(box.get("dy", 0.0) or 0.0))
                yaw = float(box.get("yaw", 0.0) or 0.0)
                score = float(
                    advanced_obj.get(
                        "score", advanced_obj.get("confidence", 0.0)
                    )
                    or 0.0
                )
            except Exception:
                continue
            cos_yaw = abs(float(np.cos(yaw)))
            sin_yaw = abs(float(np.sin(yaw)))
            longitudinal_extent = 0.5 * (cos_yaw * dx + sin_yaw * dy)
            lateral_extent = 0.5 * (sin_yaw * dx + cos_yaw * dy)
            nearest_face = max(0.0, forward - longitudinal_extent)
            transverse_vehicle = bool(
                cls in ("car", "van", "truck", "bus", "vehicle")
                and score >= 0.25
                and 5.0 <= nearest_face <= 40.0
                and lateral_extent >= max(1.60, 1.35 * longitudinal_extent)
                and abs(lateral) - lateral_extent <= 7.0
            )
            if transverse_vehicle:
                transverse_key = (
                    max(0.0, abs(lateral) - lateral_extent),
                    nearest_face,
                    -score,
                )
                if (
                    nearest_transverse_vehicle_key is None
                    or transverse_key < nearest_transverse_vehicle_key
                ):
                    nearest_transverse_vehicle_key = transverse_key
                    feat.advanced_lidar_transverse_vehicle_distance = nearest_face
                    feat.advanced_lidar_transverse_vehicle_lateral = lateral
                    feat.advanced_lidar_transverse_vehicle_lateral_extent = lateral_extent
                    feat.advanced_lidar_transverse_vehicle_longitudinal_extent = longitudinal_extent
                    feat.advanced_lidar_transverse_vehicle_yaw = yaw
                    feat.advanced_lidar_transverse_vehicle_score = score
                    feat.advanced_lidar_transverse_vehicle_open_side = (
                        "right" if lateral <= 0.0 else "left"
                    )
            overlaps_route_corridor = bool(
                forward + longitudinal_extent >= 0.0
                and nearest_face <= 30.0
                and abs(lateral) - lateral_extent <= 3.2
            )
            if overlaps_route_corridor:
                semantic_key = (nearest_face, abs(lateral), -score)
                if nearest_semantic_key is None or semantic_key < nearest_semantic_key:
                    nearest_semantic_key = semantic_key
                    feat.advanced_lidar_nearest_corridor_class = cls
                    feat.advanced_lidar_nearest_corridor_distance = nearest_face
                    feat.advanced_lidar_nearest_corridor_lateral = lateral
                    feat.advanced_lidar_nearest_corridor_lateral_extent = lateral_extent
                    feat.advanced_lidar_nearest_corridor_longitudinal_extent = longitudinal_extent
                    feat.advanced_lidar_nearest_corridor_yaw = yaw
                    feat.advanced_lidar_nearest_corridor_score = score
                    # Agent coordinates use negative y on the left.  Pass on
                    # the opposite side of the semantic box centre; an exactly
                    # centred box uses a deterministic right-side corridor.
                    feat.advanced_lidar_semantic_open_side = (
                        "right" if lateral <= 0.0 else "left"
                    )
            if cls in (
                "person", "pedestrian", "walker", "bicycle", "bike",
                "cyclist", "motorcycle", "motorbike",
            ):
                feat.advanced_lidar_vru_count += 1
                if 0.0 <= forward <= 35.0 and abs(lateral) <= 3.0:
                    current = feat.advanced_lidar_front_vru_distance
                    feat.advanced_lidar_front_vru_distance = (
                        forward if current is None else min(current, forward)
                    )
            elif cls in ("car", "van", "truck", "bus", "vehicle"):
                feat.advanced_lidar_vehicle_count += 1
                if 0.0 <= forward <= 45.0 and abs(lateral) <= 3.0:
                    current = feat.advanced_lidar_front_vehicle_distance
                    feat.advanced_lidar_front_vehicle_distance = (
                        forward if current is None else min(current, forward)
                    )
        for track in feat.tracked_objects:
            cls = str(track.get("class_name", "")).lower()
            if cls not in ("car", "van", "truck", "bus", "motorcycle", "bicycle"):
                continue
            x = float(track.get("x", 999.0))
            y = float(track.get("y", 999.0))
            closing = float(track.get("closing_speed", 0.0) or 0.0)
            observed = int(track.get("observed_frames", 0) or 0)
            if (
                cls in ("car", "van", "truck", "bus")
                and 2.0 <= x <= 4.8
                and -4.5 <= y <= 5.8
                and closing <= 0.35
                and observed >= 1
            ):
                feat.disabled_static_vehicle_evidence = True
            if cls in ("car", "van", "truck", "bus") and -3.0 <= x <= 45.0 and 5.0 <= abs(y) <= 30.0:
                feat.lateral_vehicle_context_count += 1
            if not (0.0 <= x <= 24.0 and abs(y) <= 2.6):
                continue
            feat.front_vehicle_distance = x if feat.front_vehicle_distance is None else min(feat.front_vehicle_distance, x)
            feat.front_vehicle_closing_speed = max(feat.front_vehicle_closing_speed, closing)
            ttc = track.get("ttc")
            if ttc is not None:
                ttc = float(ttc)
                feat.front_vehicle_ttc = ttc if feat.front_vehicle_ttc is None else min(feat.front_vehicle_ttc, ttc)
            if bool(track.get("is_reversing_candidate", False)) and int(track.get("observed_frames", 0)) >= 2:
                feat.reversing_vehicle_evidence = True
                feat.front_clear = False
        topology = observation.get("road_topology") or {}
        feat.lane_confidence = float(topology.get("lane_confidence", 0.0) or 0.0)
        feat.route_curvature = float(topology.get("lateral_span", 0.0) or 0.0)
        feat.junction_like = bool(topology.get("junction_like", False))
        tl_state = observation.get("traffic_light_state") or {}
        feat.red_light_active = bool(tl_state.get("active", False))
        feat.traffic_light_color = str(tl_state.get("color", "unknown"))
        feat.traffic_light_color_confidence = float(tl_state.get("color_confidence", 0.0) or 0.0)
        feat.traffic_light_red_blob_area = int(tl_state.get("red_blob_area", 0) or 0)
        feat.traffic_light_green_blob_area = int(tl_state.get("green_blob_area", 0) or 0)
        feat.traffic_light_yellow_blob_area = int(tl_state.get("yellow_blob_area", 0) or 0)
        feat.traffic_light_green_pass_progress_m = float(tl_state.get("green_pass_progress_m", 0.0) or 0.0)
        feat.traffic_light_green_pass_latched = bool(tl_state.get("green_pass_latched", False))
        if tl_state.get("distance") is not None:
            feat.red_stop_distance = float(tl_state["distance"])
        nearest = None
        for obj in observation.get("objects", []) or []:
            score = float(obj.get("score", 0.0))
            cls = str(obj.get("class_name", "")).lower()
            box = obj.get("box_lidar") or {}
            x = float(box.get("x", 999.0))
            y = float(box.get("y", 999.0))
            if (
                cls in ("car", "van", "truck", "bus", "vehicle")
                and score >= 0.005
                and 2.0 <= x <= 4.8
                and -4.5 <= y <= 5.8
            ):
                feat.disabled_static_vehicle_evidence = True
            if (
                cls in ("car", "van", "truck", "bus")
                and score >= 0.06
                and -3.0 <= x <= 45.0
                and 5.0 <= abs(y) <= 30.0
            ):
                feat.lateral_vehicle_context_count += 1
            if score < 0.32:
                continue
            if cls in ("traffic_cone", "truck", "construction", "barrier"):
                feat.construction_object_count += 1
            if 0.0 <= x <= 18.0 and abs(y) <= 4.2 and score >= 0.38:
                if y < -2.2:
                    feat.left_clear = False
                if y > 2.2:
                    feat.right_clear = False
            if 0.0 <= x <= 8.0 and 1.6 < abs(y) <= 3.4 and score >= 0.42:
                feat.side_risk = True
            if cls in ("car", "van", "truck", "bicycle", "pedestrian", "traffic_cone", "others"):
                y_limit = 2.6 if cls in ("pedestrian", "bicycle") else 2.2
                x_limit = 20.0 if cls in ("pedestrian", "bicycle") else 15.0
                near_low_conf_vehicle = (
                    cls in ("car", "van", "truck", "bicycle", "traffic_cone", "others")
                    and 0.0 <= x <= 4.5
                    and abs(y) <= 1.2
                    and score >= 0.02
                )
                if near_low_conf_vehicle:
                    feat.front_clear = False
                    nearest = x if nearest is None else min(nearest, x)
                    feat.front_obstacle_distance = x if feat.front_obstacle_distance is None else min(feat.front_obstacle_distance, x)
                elif 0.0 <= x <= x_limit and abs(y) <= y_limit:
                    feat.front_clear = False
                    nearest = x if nearest is None else min(nearest, x)
                    if cls in ("car", "van", "truck"):
                        feat.front_vehicle_distance = x if feat.front_vehicle_distance is None else min(feat.front_vehicle_distance, x)
                    elif cls in ("pedestrian", "bicycle"):
                        feat.front_pedestrian_distance = x if feat.front_pedestrian_distance is None else min(feat.front_pedestrian_distance, x)
                    else:
                        feat.front_obstacle_distance = x if feat.front_obstacle_distance is None else min(feat.front_obstacle_distance, x)
            if cls == "traffic_light" and 0.0 <= x <= 18.0 and abs(y) <= 4.0 and score >= 0.45:
                feat.red_stop_distance = x if feat.red_stop_distance is None else min(feat.red_stop_distance, x)

        for map_obj in observation.get("map_objects", []) or []:
            if float(map_obj.get("score", 0.0)) < 0.35:
                continue
            cls = str(map_obj.get("class_name", "")).lower()
            if cls not in ("trafficlight", "stopsign"):
                continue
            arr = np.asarray(map_obj.get("box", []), dtype=np.float32).reshape(-1)
            if arr.size >= 2:
                dist = float(np.hypot(arr[0], arr[1]))
                if arr[0] >= -2.0 and abs(arr[1]) <= 5.0 and dist <= 16.0:
                    feat.red_stop_distance = dist if feat.red_stop_distance is None else min(feat.red_stop_distance, dist)

        # Raw point-cloud geometry is deliberately excluded from scenario
        # recognition and rule selection when safety-only mode is enabled.
        # The agent retains a separate geometry emergency-brake path, while
        # semantic objects from the required 3D detector above continue into
        # object tracking and every higher-level feature/rule.
        lidar = {} if self.config.geometry_lidar_safety_only else (observation.get("lidar_geometry") or {})
        if lidar:
            feat.lidar_available = bool(lidar.get("available", False))
            feat.lidar_stale = bool(lidar.get("stale", True))
            feat.lidar_front_distance = lidar.get("front_distance")
            feat.lidar_blockage_ratio = float(lidar.get("corridor_blockage_ratio", 0.0) or 0.0)
            feat.lidar_left_blockage_ratio = float(lidar.get("left_blockage_ratio", 0.0) or 0.0)
            feat.lidar_right_blockage_ratio = float(lidar.get("right_blockage_ratio", 0.0) or 0.0)
            feat.lidar_center_blockage_ratio = float(lidar.get("center_blockage_ratio", 0.0) or 0.0)
            feat.lidar_left_density = int(lidar.get("left_density", 0) or 0)
            feat.lidar_right_density = int(lidar.get("right_density", 0) or 0)
            feat.lidar_center_density = int(lidar.get("center_density", 0) or 0)
            feat.lidar_open_side = str(lidar.get("open_side", "unknown") or "unknown")
            feat.lidar_lateral_centroid = float(lidar.get("lateral_centroid", 0.0) or 0.0)
            if feat.lidar_available and not feat.lidar_stale and feat.lidar_front_distance is not None:
                corridor_blocked = bool(
                    lidar.get("front_blocked")
                    or lidar.get("near_blocked")
                    or (
                        feat.lidar_center_blockage_ratio >= 0.45
                        and float(feat.lidar_front_distance) <= 18.0
                        and feat.lidar_open_side in ("right", "balanced", "left")
                    )
                )
                if corridor_blocked:
                    feat.front_clear = False
                    d = float(feat.lidar_front_distance)
                    feat.front_obstacle_distance = d if feat.front_obstacle_distance is None else min(feat.front_obstacle_distance, d)

        if feat.front_pedestrian_distance is not None and feat.front_pedestrian_distance < 9.0:
            feat.risk_level = max(feat.risk_level, 3)
        if feat.front_vehicle_distance is not None and feat.front_vehicle_distance < 6.0:
            feat.risk_level = max(feat.risk_level, 3)
        if feat.reversing_vehicle_evidence and feat.front_vehicle_ttc is not None and feat.front_vehicle_ttc < 5.0:
            feat.risk_level = max(feat.risk_level, 3)
        if feat.front_obstacle_distance is not None and feat.front_obstacle_distance < 2.4:
            feat.risk_level = max(feat.risk_level, 3)
        elif feat.front_obstacle_distance is not None and feat.front_obstacle_distance < 5.0:
            feat.risk_level = max(feat.risk_level, 2)
        elif (
            feat.front_obstacle_distance is not None
            and feat.front_obstacle_distance < 18.0
            and feat.lidar_center_blockage_ratio >= 0.45
            and feat.ego_speed < 1.0
        ):
            feat.risk_level = max(feat.risk_level, 1)
        if not feat.front_clear:
            feat.risk_level = max(feat.risk_level, 1)
        if feat.red_stop_distance is not None and feat.red_stop_distance < 9.0:
            feat.risk_level = max(feat.risk_level, 2)
        feat.immediate_hazard = bool(
            (feat.front_pedestrian_distance is not None and feat.front_pedestrian_distance < 6.0)
            or (feat.front_vehicle_distance is not None and feat.front_vehicle_distance < 4.0)
            or (feat.reversing_vehicle_evidence and feat.front_vehicle_ttc is not None and feat.front_vehicle_ttc < 3.5)
        )
        feat.confidence = min(1.0, 0.25 + 0.2 * feat.risk_level + (0.15 if feat.lidar_available and not feat.lidar_stale else 0.0))
        return feat


class ScenarioRecognizer:
    def __init__(self, config: AuxiliaryConfig):
        self.config = config
        self.entry_ego_speed = None
        self.roundabout_entry_memory_frames = 0
        self.roundabout_route_memory_frames = 0
        self.highspeed_entry_memory_frames = 0
        self.very_highspeed_entry_memory_frames = 0
        self.static_barrier_route_owner = False
        self.lane_closure_truck_memory_frames = 0
        self.construction_entry_memory_frames = 0
        self.highspeed_static_construction_memory_frames = 0
        self.disabled_scene_memory_frames = 0
        self.disabled_vehicle_route_owner = False
        # MissingCar is identified by a temporal event, not by a single
        # object alias: a close/closing lead is observed and then leaves the
        # corridor.  Keep this ownership in the recognizer that actually
        # drives ScenarioRulePlanner (the audit classifier has its own state).
        self.missing_car_close_lead_memory_frames = 0
        self.missing_car_event_memory_frames = 0
        self.missing_car_owner_reason = ""
        self.crazy_motor_memory_frames = 0
        self.crazy_motor_route_owner = False
        self.crazy_motor_owner_reason = ""
        self.slanted_motor_children_memory_frames = 0
        self.slanted_motor_children_route_owner = False
        self.slanted_motor_children_owner_reason = ""
        self.four_students_memory_frames = 0
        self.four_students_approach_memory_frames = 0
        self.four_students_vru_memory_frames = 0
        self.four_students_advanced_vru_memory_frames = 0
        self.four_students_entry_family_memory_frames = 0
        self.four_students_route_owner = False
        self.reckless_lane_cutting_memory_frames = 0
        self.reckless_lane_cutting_route_owner = False
        self.highway_accident_memory_frames = 0
        self.reverse_vehicle_center_blockage_memory_frames = 0
        self.reverse_vehicle_route_owner = False
        self.reverse_vehicle_owner_reason = ""
        self.reverse_vehicle_last_transverse_measurement_timestamp = None
        self.reverse_vehicle_transverse_owner_rejected = False
        self.reverse_vehicle_transverse_owner_confirmation_count = 0
        self.blind_spot_memory_frames = 0
        self.blind_spot_route_owner = False

    @staticmethod
    def _construction_corridor_signature(features: AuxFeatures) -> bool:
        front_static = (
            features.front_obstacle_distance is not None
            and 1.0 <= float(features.front_obstacle_distance) <= 24.0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
        )
        lidar_side_closure = (
            features.lidar_available
            and not features.lidar_stale
            and features.lidar_open_side in ("right", "left", "balanced")
            and features.lidar_blockage_ratio >= 0.08
            and (
                max(features.lidar_left_blockage_ratio, features.lidar_right_blockage_ratio) >= 0.20
                or features.lidar_center_blockage_ratio >= 0.20
            )
        )
        detector_context = (
            features.detection_object_count >= 60
            or features.construction_object_count > 0
            or features.lateral_vehicle_context_count > 0
        )
        return bool(front_static and lidar_side_closure and detector_context)

    @staticmethod
    def _highspeed_asymmetric_lane_closure_entry_signature(
        features: AuxFeatures,
    ) -> bool:
        """Recognise the 70/80/90-km/h lane-closure entry before aliases.

        In the faster weather variants the detector does not always emit the
        explicit construction-object alias.  Their live entry still has a
        narrow, repeatable sensor signature: a high-speed straight approach, a modest left-only
        LiDAR occlusion, no forward conflict and no adjacent-vehicle context.
        The latter two guards separate this from the fastest reckless cut-in,
        which begins in an empty LiDAR corridor with several lateral vehicles.
        All values are ego-relative online observations.
        """
        far_command = str(features.route_command_far).upper()
        straight_route = bool(
            "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
        )
        return bool(
            straight_route
            and abs(float(features.ego_speed)) >= 18.8
            and not features.junction_like
            and features.lidar_available
            and not features.lidar_stale
            and features.front_clear
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is None
            and not features.reversing_vehicle_evidence
            and not features.immediate_hazard
            and features.construction_object_count == 0
            and features.lateral_vehicle_context_count <= 1
            and 0.25 <= features.lane_confidence <= 0.55
            and features.route_curvature >= 20.0
            and 0.07 <= features.lidar_blockage_ratio <= 0.20
            and 0.16 <= features.lidar_left_blockage_ratio <= 0.32
            and features.lidar_right_blockage_ratio <= 0.04
            and features.lidar_center_blockage_ratio <= 0.08
            and features.lidar_left_blockage_ratio
            >= features.lidar_center_blockage_ratio + 0.12
        )

    @staticmethod
    def _observable_roundabout_entry_signature(features: AuxFeatures) -> bool:
        """Recognise the live side-convoy/static-island roundabout entry.

        The same LiDAR return was previously consumed first by the generic
        construction corridor latch.  Require the distinctive one-sided entry
        geometry and live vehicle context before either construction memory is
        allowed to arm.  This uses only online perception/navigation features.
        """
        return bool(
            features.construction_object_count == 0
            and features.lateral_vehicle_context_count >= 1
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is not None
            and 6.0 <= float(features.front_obstacle_distance) <= 12.5
            and features.red_stop_distance is None
            and not features.red_light_active
            and not features.reversing_vehicle_evidence
            and features.lidar_blockage_ratio >= 0.85
            and features.lidar_left_blockage_ratio >= 0.75
            and features.lidar_right_blockage_ratio <= 0.25
            and features.lidar_center_blockage_ratio <= 0.35
            and features.lidar_open_side == "right"
            and features.ego_speed >= 5.0
        )

    @staticmethod
    def _roundabout_navigation_entry_signature(
        features: AuxFeatures,
        entry_ego_speed: float,
    ) -> bool:
        """Recognise the shared roundabout family without geometry LiDAR.

        Formal operation reserves raw point-cloud geometry for emergency
        braking, so the older island/blockage signature cannot own a macro.
        The roundabout family instead exposes a moderate-speed navigation
        entry with a dense semantic side convoy and no VRU, construction, or
        signal conflict.  An explicit change-left cue remains sufficient; the
        formal Town03 variants use LANEFOLLOW and therefore require the
        stronger dense-side-context guard below.
        """
        far_command = str(features.route_command_far).upper()
        # The formal Town03 roundabout routes expose LANEFOLLOW throughout
        # their entry rather than the previously assumed CHANGELANELEFT cue.
        # Their earliest stable online discriminator is the side convoy: all
        # twelve current variants expose at least two lateral vehicle contexts
        # on frame zero, while the closest moderate-speed construction
        # lookalike exposes none.  Keep the older explicit lane-change cue,
        # but admit the observed LANEFOLLOW form only behind that semantic
        # side-context guard.
        navigation_entry = bool(
            "CHANGELANELEFT" in far_command
            or (
                "LANEFOLLOW" in far_command
                and features.lateral_vehicle_context_count >= 2
                # The FourStudents family enters the same straight Town03
                # corridor at about 9.51 m/s with only two or three lateral
                # vehicle contexts.  Do not permanently assign that live
                # observation to Roundabout before its multi-VRU evidence has
                # had time to appear.  Formal Roundabout entries occupy the
                # separately observed 8.18, 10.86, and 13.53 m/s families, so
                # this narrow sensor-only defer window preserves all of them.
                and not (
                    (
                        8.8 <= abs(float(entry_ego_speed)) <= 10.2
                        and features.lateral_vehicle_context_count <= 3
                    )
                    or (
                        # Medium FourStudents is 10.850849 m/s across clean
                        # restarts.  The adjacent Roundabout family is
                        # 10.861028 m/s and may expose three semantic vehicles;
                        # the old 11.2 upper bound wrongly suppressed it.
                        10.5 <= abs(float(entry_ego_speed)) <= 10.856
                        and features.advanced_lidar_vehicle_count >= 3
                        and features.lateral_vehicle_context_count <= 5
                    )
                    or (
                        11.7 <= abs(float(entry_ego_speed)) <= 12.7
                        and features.advanced_lidar_vehicle_count >= 2
                        and features.lateral_vehicle_context_count <= 3
                    )
                )
            )
        )
        return bool(
            navigation_entry
            and 7.5 <= abs(float(entry_ego_speed)) <= 14.2
            and features.route_curvature >= 20.0
            and features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vehicle_count >= 1
            and features.advanced_lidar_vru_count == 0
            and features.lateral_vehicle_context_count >= 1
            and features.construction_object_count == 0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and not features.reversing_vehicle_evidence
        )

    @staticmethod
    def _crazy_motor_detector_signature(features: AuxFeatures) -> bool:
        bike_in_path = False
        close_bikes = []
        close_vehicles = []
        for obj in features.detector_objects or []:
            cls = str(obj.get("class_name", "")).lower()
            try:
                forward, lateral = _detector_forward_lateral(obj)
            except Exception:
                continue
            if cls in (
                "bicycle", "bike", "cyclist", "motorcycle", "motorbike",
            ):
                if 2.5 <= forward <= 4.8 and abs(lateral) <= 3.2:
                    close_bikes.append((forward, lateral))
            elif cls in ("car", "van", "truck", "bus", "vehicle"):
                if 2.5 <= forward <= 4.8 and abs(lateral) <= 3.2:
                    close_vehicles.append((forward, lateral))
            else:
                continue
            if (
                cls in (
                    "bicycle", "bike", "cyclist", "motorcycle", "motorbike",
                )
                and 3.0 <= forward <= 35.0
                and abs(lateral) <= 1.20
            ):
                bike_in_path = True
        close_motor_overlap = any(
            abs(bx - vx) <= 0.45 and abs(by - vy) <= 0.65
            for bx, by in close_bikes
            for vx, vy in close_vehicles
        )
        # At night the same close Vespa proposal alternates between a centred
        # bicycle box and spatially identical weak bicycle/car classes.  The
        # overlap is stable from the first frame even when the centred class
        # appears late.  Require the live far-route left cue for this wider
        # fallback so a straight disabled-car route with a duplicate class is
        # not promoted to CrazyMotor.
        far_command = str(features.route_command_far).upper()
        close_overlap_entry = bool(
            close_motor_overlap and "LEFT" in far_command
        )
        if not bike_in_path and not close_overlap_entry:
            return False
        return bool(
            features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vru_count >= 1
            and features.construction_object_count == 0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is None
            and not features.reversing_vehicle_evidence
            and not features.immediate_hazard
            and features.lateral_vehicle_context_count <= 1
            and abs(float(features.ego_speed)) <= 8.0
            and features.lane_confidence >= 0.16
            and features.route_curvature >= 20.0
        )

    @staticmethod
    def _slanted_motor_children_detector_signature(features: AuxFeatures) -> bool:
        """Recognise a side-origin VRU/motor crossing from live detections.

        The detector commonly assigns both a weak vehicle class and a VRU
        class to the same two-wheeler.  In this interaction that overlap is
        well outside the ego lane before crossing, whereas CrazyMotor's
        distinctive overlap begins close to the lane centre.  Use only that
        relative sensor geometry plus the low-confidence curved route view.
        """
        far_command = str(features.route_command_far).upper()
        straight_route = (
            "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
        )
        center_vru = False
        side_vrus = []
        side_vehicles = []
        for obj in features.detector_objects or []:
            cls = str(obj.get("class_name", "")).lower()
            box = obj.get("box_lidar") or {}
            try:
                forward = float(box.get("x", 999.0))
                lateral = float(box.get("y", 999.0))
            except Exception:
                continue
            if cls in (
                "person", "pedestrian", "walker", "bicycle", "bike",
                "cyclist", "motorcycle", "motorbike",
            ):
                if 2.5 <= forward <= 4.8 and abs(lateral) <= 1.5:
                    center_vru = True
                if -2.0 <= forward <= 8.0 and 4.0 <= abs(lateral) <= 18.0:
                    side_vrus.append((forward, lateral))
            elif (
                cls in ("car", "van", "truck", "bus", "vehicle")
                and -2.0 <= forward <= 8.0
                and 4.0 <= abs(lateral) <= 18.0
            ):
                side_vehicles.append((forward, lateral))
        side_overlap = any(
            abs(vx - cx) <= 1.2 and abs(vy - cy) <= 1.6
            for vx, vy in side_vrus
            for cx, cy in side_vehicles
        )
        straight_low_lane_seed = bool(
            straight_route
            and center_vru
            and side_vehicles
            and 0.30 <= features.lane_confidence <= 0.46
        )
        return bool(
            features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vru_count >= 1
            and ((side_overlap and center_vru) or straight_low_lane_seed)
            and features.construction_object_count == 0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and not features.reversing_vehicle_evidence
            and not features.immediate_hazard
            and abs(float(features.ego_speed)) <= 8.0
            and features.lane_confidence <= 0.46
            and features.route_curvature >= 20.0
        )

    @staticmethod
    def _slanted_low_entry_camera_vru_signature(features: AuxFeatures) -> bool:
        """Own the low-entry slanted family despite a PointPillar class alias.

        On this severity tier PointPillar is healthy and consistently sees the
        live road users, but labels them as vehicles while the camera head
        exposes several bicycle proposals from the centre to one road side.
        Requiring both modalities, the narrow online speedometer family, a
        straight route cue, and the relative camera layout keeps raw LiDAR
        geometry and benchmark identity out of the decision.
        """
        far_command = str(features.route_command_far).upper()
        straight_route = bool(
            "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
        )
        center_vru = False
        side_vru = False
        for obj in features.detector_objects or []:
            cls = str(obj.get("class_name", "")).lower()
            if cls not in (
                "person", "pedestrian", "walker", "bicycle", "bike",
                "cyclist", "motorcycle", "motorbike",
            ):
                continue
            box = obj.get("box_lidar") or {}
            try:
                forward = float(box.get("x", 999.0))
                lateral = float(box.get("y", 999.0))
            except Exception:
                continue
            if 1.8 <= forward <= 5.2 and abs(lateral) <= 2.0:
                center_vru = True
            if -1.0 <= forward <= 7.0 and 4.0 <= abs(lateral) <= 12.5:
                side_vru = True
        return bool(
            5.30 <= abs(float(features.ego_speed)) <= 5.40
            and straight_route
            and center_vru
            and side_vru
            and features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vehicle_count >= 1
            and features.construction_object_count == 0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is None
            and not features.reversing_vehicle_evidence
            and not features.immediate_hazard
            and not features.junction_like
            and features.lane_confidence <= 0.46
            and features.route_curvature >= 20.0
        )

    @staticmethod
    def _four_students_detector_signature(features: AuxFeatures) -> bool:
        """Recognize a straight-ahead multi-VRU crossing from live observations.

        The single-bike and four-student scenes both produce noisy bicycle-class
        boxes.  Require several spatially distinct VRU returns together with a
        straight/lanefollow far navigation command and the already-observed fast
        approach.  This keeps route metadata and scenario ground truth out of the
        runtime policy while preventing a single bike from stealing the macro.
        """
        far_command = str(features.route_command_far).upper()
        straight_route = (
            "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
        )
        vru_positions = []
        for obj in features.detector_objects or []:
            cls = str(obj.get("class_name", "")).lower()
            if cls not in (
                "person", "pedestrian", "walker", "bicycle", "bike",
                "cyclist", "motorcycle", "motorbike",
            ):
                continue
            box = obj.get("box_lidar") or {}
            try:
                # The online detector always supplies a score.  Unit-level
                # synthetic objects historically omitted it, so keep their
                # neutral default at the weakest accepted live confidence.
                score = float(obj.get("score", 0.01) or 0.0)
                forward = float(box.get("x", 999.0))
                lateral = float(box.get("y", 999.0))
            except Exception:
                continue
            if score >= 0.008 and 3.0 <= forward <= 28.0 and abs(lateral) <= 18.5:
                if all(
                    abs(forward - old_forward) > 0.55
                    or abs(lateral - old_lateral) > 0.55
                    for old_forward, old_lateral in vru_positions
                ):
                    vru_positions.append((forward, lateral))
        lateral_span = (
            max(pos[1] for pos in vru_positions) - min(pos[1] for pos in vru_positions)
            if len(vru_positions) >= 2 else 0.0
        )
        bilateral_cluster = bool(
            any(pos[1] >= 0.4 for pos in vru_positions)
            and any(pos[1] <= -0.4 for pos in vru_positions)
        )
        return bool(
            straight_route
            and len(vru_positions) >= 3
            and bilateral_cluster
            and lateral_span >= 4.0
            and features.construction_object_count == 0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is None
            and not features.reversing_vehicle_evidence
            and features.lane_confidence >= 0.15
        )

    @staticmethod
    def _reckless_lane_cutting_detector_signature(features: AuxFeatures) -> bool:
        # A lane-cutting car can also produce a weak overlapping bicycle class
        # from the detector.  Use the simultaneous, spatially coherent vehicle
        # detection in the adjacent-lane cut-in band to disambiguate it from a
        # genuine in-lane motor/bicycle interaction.
        for obj in features.detector_objects or []:
            cls = str(obj.get("class_name", "")).lower()
            if cls not in ("car", "van", "truck", "bus", "vehicle"):
                continue
            try:
                score = float(obj.get("score", 0.0) or 0.0)
                box = obj.get("box_lidar") or {}
                ox = float(box.get("x", 999.0))
                oy = float(box.get("y", 999.0))
            except Exception:
                continue
            if score >= 0.01 and 3.0 <= ox <= 18.0 and 2.0 <= abs(oy) <= 5.2:
                return True
        return False

    @staticmethod
    def _reverse_vehicle_center_blockage_signature(features: AuxFeatures) -> bool:
        """Detect the reverse-scene centre vehicle from a semantic 3D box.

        The neural detector runs more slowly than the controller and republishes
        its latest measurement between inferences.  Scene ownership therefore
        comes directly from the source-level box instead of treating repeated
        publications as multiple tracker observations.
        """
        semantic_class = str(
            features.advanced_lidar_nearest_corridor_class or ""
        ).lower()
        semantic_distance = features.advanced_lidar_nearest_corridor_distance
        semantic_vehicle = bool(
            semantic_class in ("car", "van", "truck", "bus", "vehicle")
            and semantic_distance is not None
            and 5.0 <= float(semantic_distance) <= 30.0
            and features.advanced_lidar_nearest_corridor_lateral is not None
            and abs(float(features.advanced_lidar_nearest_corridor_lateral)) <= 3.2
        )
        transverse_vehicle_approach = bool(
            # A new reverse-scene owner must be observed while ego is still
            # approaching.  A single far transverse PointPillar proposal that
            # first appears after another interaction has already stopped ego
            # is phase evidence, not route ownership.  Existing semantic
            # ownership remains latched as speed falls during the response.
            abs(float(features.ego_speed)) >= 4.5
            and
            features.advanced_lidar_transverse_vehicle_distance is not None
            and 5.0
            <= float(features.advanced_lidar_transverse_vehicle_distance)
            <= 40.0
            and features.advanced_lidar_transverse_vehicle_lateral is not None
            and (
                abs(float(features.advanced_lidar_transverse_vehicle_lateral))
                - float(features.advanced_lidar_transverse_vehicle_lateral_extent)
                <= 7.0
            )
            and float(features.advanced_lidar_transverse_vehicle_score) >= 0.25
        )
        return bool(
            features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and (semantic_vehicle or transverse_vehicle_approach)
            and features.construction_object_count == 0
            and features.front_pedestrian_distance is None
            and not features.red_light_active
            and features.advanced_lidar_vru_count == 0
        )

    @staticmethod
    def _highway_accident_close_side_vehicle_signature(
        features: AuxFeatures,
    ) -> bool:
        """Detect the persistent camera track of a roadside accident car.

        ObjectTracker preserves each detector source's native coordinates;
        normalize them before applying shared forward/lateral geometry. The
        accident car remains static beside the forward path for many
        observations while ego closes on it.
        """
        if (
            features.construction_object_count != 0
            or features.front_pedestrian_distance is not None
            or features.red_light_active
            or features.advanced_lidar_vru_count > 0
        ):
            return False
        for track in features.tracked_objects or []:
            cls = str(track.get("class_name", "")).lower()
            source = str(track.get("source", "") or "").lower()
            if cls not in ("car", "van", "truck", "bus", "vehicle"):
                continue
            # PointPillar is handled by the semantic reverse/forward corridor
            # branches, not this camera cue.
            if source == "openpcdet":
                continue
            try:
                forward, lateral = _tracked_forward_lateral(track)
                observed = int(track.get("observed_frames", 0) or 0)
                closing_speed = abs(float(track.get("closing_speed", 0.0) or 0.0))
            except Exception:
                continue
            if (
                (
                    # The mature far-side track is the earliest reliable
                    # accident cue.  It appears well before geometry marks the
                    # car as a close disabled obstacle.
                    (1.5 <= abs(lateral) <= 9.0 and 10.0 <= forward <= 30.0)
                    or (
                        features.disabled_static_vehicle_evidence
                        and 1.5 <= abs(lateral) <= 5.2
                        and 2.5 <= forward < 10.0
                    )
                )
                and observed >= 8
                and closing_speed <= 0.8
            ):
                return True
        return False

    @staticmethod
    def _blind_spot_asymmetric_occlusion_signature(
        features: AuxFeatures,
        highspeed_entry_memory_active: bool,
    ) -> bool:
        """Recognize the hidden-left-car approach from legal live sensors.

        The scene begins on a nominally straight route with a building/vehicle
        occlusion entirely on the left and an empty right sector.  A weak first
        frame seed is useful because the benchmark initializes the ego at speed;
        waiting for a close object would let the base policy brake before the
        scored interaction is active.  The seed is deliberately narrow and the
        developed signature requires stronger LiDAR asymmetry.  Neither branch
        uses a route id, XML data, map/world actor state, or an absolute position.
        """
        far_command = str(features.route_command_far).upper()
        straight_route = bool(
            "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
        )
        common = bool(
            straight_route
            and features.lidar_available
            and not features.lidar_stale
            and features.construction_object_count == 0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and not features.reversing_vehicle_evidence
            and not features.red_light_active
            and features.red_stop_distance is None
            and not features.immediate_hazard
            and features.front_clear
            and features.lateral_vehicle_context_count <= 1
            and features.lidar_right_blockage_ratio <= 0.06
            and features.lidar_left_blockage_ratio
            >= features.lidar_right_blockage_ratio + 0.10
        )
        if not common:
            return False
        weak_entry_seed = bool(
            abs(float(features.ego_speed)) >= 9.0
            and 0.20 <= features.lane_confidence <= 0.55
            and features.route_curvature >= 20.0
            and 0.09 <= features.lidar_left_blockage_ratio <= 0.30
            and features.lidar_center_blockage_ratio <= 0.09
            and 0.035 <= features.lidar_blockage_ratio <= 0.18
            and features.lidar_left_blockage_ratio
            >= features.lidar_center_blockage_ratio + 0.055
            and (
                features.front_obstacle_distance is None
                or float(features.front_obstacle_distance) >= 24.0
            )
        )
        developed_left_occlusion = bool(
            highspeed_entry_memory_active
            and abs(float(features.ego_speed)) >= 5.0
            and features.lane_confidence <= 0.50
            and features.lidar_left_blockage_ratio >= 0.32
            and features.lidar_center_blockage_ratio <= 0.42
            and features.lidar_blockage_ratio >= 0.16
            and features.lidar_left_blockage_ratio
            >= features.lidar_center_blockage_ratio + 0.16
            and (
                features.front_obstacle_distance is None
                or float(features.front_obstacle_distance) >= 14.0
            )
        )
        return bool(weak_entry_seed or developed_left_occlusion)

    def recognize(self, features: AuxFeatures) -> ScenarioEstimate:
        first_observation = self.entry_ego_speed is None
        if self.entry_ego_speed is None:
            # First legal speedometer sample for this recognizer instance.
            # Entry-family owners must use this immutable observation instead
            # of accidentally arming when another scenario merely decelerates
            # through the same narrow speed band later in its approach.
            self.entry_ego_speed = abs(float(features.ego_speed))
        if first_observation:
            entry_speed = float(self.entry_ego_speed)
            side_count = int(features.lateral_vehicle_context_count)
            semantic_vehicles = int(features.advanced_lidar_vehicle_count)
            semantic_ready = bool(
                features.advanced_lidar_available
                and not features.advanced_lidar_stale
                and features.advanced_lidar_vru_count == 0
                and features.construction_object_count == 0
            )
            close_front = bool(
                features.front_vehicle_distance is not None
                and float(features.front_vehicle_distance) <= 4.5
            )
            temporary_construction_first_frame = bool(
                semantic_ready
                and 12.30 <= entry_speed <= 12.68
                and features.front_pedestrian_distance is None
                and not features.junction_like
            )
            if temporary_construction_first_frame:
                self.static_barrier_route_owner = True
                self.highspeed_static_construction_memory_frames = 5000
                self.construction_entry_memory_frames = 5000
                return ScenarioEstimate(
                    "high_speed_temporary_construction",
                    max(features.confidence, 0.80), "APPROACH",
                    "first-frame static-barrier speed/empty-side semantic owner",
                )

            reckless_first_frame = bool(
                semantic_ready
                and entry_speed < 0.10
                and side_count in (2, 3)
                and semantic_vehicles == 2
                and features.detection_object_count >= 100
                # Camera-derived route curvature moves by more than a full
                # point across clean CARLA restarts (29.50--31.78 in the
                # observed CutInCollision family).  The zero-speed entry plus
                # two/three side contexts plus two semantic vehicles is already
                # unique to that family in the 144-route first-frame audit;
                # do not reject a valid route on this non-semantic jitter.
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
            )
            if reckless_first_frame:
                self.reckless_lane_cutting_route_owner = True
                self.reckless_lane_cutting_memory_frames = 5000
                return ScenarioEstimate(
                    "high_speed_reckless_lane_cutting",
                    max(features.confidence, 0.80), "PREPARE",
                    "first-frame cut-in dense-camera/two-side-semantic owner",
                )

            # The disappearing lead and its side convoy are occasionally not
            # spawned by the first 50 ms after a CARLA recovery.  The entry
            # speed family remains an immutable legal online observation, and
            # is unique for the low/medium MissingCar families in the 144-route
            # feature audit.  Keep the denser camera/semantic requirement for
            # the high family because its speed is close to the high
            # LaneClosureWithTruck family.
            missing_car_first_frame = bool(
                semantic_ready
                and (
                    14.55 <= entry_speed <= 14.59
                    or 18.82 <= entry_speed <= 18.85
                    # The high MissingCar and high LaneClosure entries are
                    # deliberately close in nominal speed, but their first
                    # legal speedometer samples are stable on opposite sides
                    # of 24.26180 m/s.  After a simulator recovery neither
                    # scenario actor is guaranteed to exist at 50 ms, so this
                    # online entry-speed boundary is the only invariant legal
                    # feature available on that frame.
                    or 24.26140 <= entry_speed < 24.26180
                )
                and features.front_pedestrian_distance is None
                and not features.junction_like
            )
            if missing_car_first_frame:
                self.missing_car_event_memory_frames = 5000
                self.missing_car_owner_reason = (
                    "first-frame missing-car speed/side/lead semantic signature"
                )
                return ScenarioEstimate(
                    "missing_car", max(features.confidence, 0.80),
                    "YIELD_OR_BRAKE" if features.risk_level > 0 else "APPROACH",
                    self.missing_car_owner_reason,
                )

            students_first_frame = bool(
                semantic_ready
                and (
                    (9.49 <= entry_speed <= 9.54 and side_count == 2
                     and semantic_vehicles >= 5)
                    or (10.83 <= entry_speed <= 10.856 and 0 <= side_count <= 5
                        and 2 <= semantic_vehicles <= 4)
                    or (12.16 <= entry_speed <= 12.20 and 2 <= side_count <= 4
                        and 1 <= semantic_vehicles <= 5)
                )
            )
            if students_first_frame:
                self.four_students_route_owner = True
                self.four_students_memory_frames = 5000
                return ScenarioEstimate(
                    "four_students_crossing_the_road",
                    max(features.confidence, 0.80), "APPROACH",
                    "first-frame students speed/side semantic family owner",
                )

            accident_first_frame = bool(
                semantic_ready
                and side_count <= 1
                and (
                    (16.23 <= entry_speed <= 16.26 and semantic_vehicles == 0)
                    or (17.58 <= entry_speed <= 17.62 and semantic_vehicles == 0)
                    or (18.855 <= entry_speed <= 18.87
                        and semantic_vehicles <= 1)
                )
            )
            if accident_first_frame:
                self.highway_accident_memory_frames = 5000
                return ScenarioEstimate(
                    "highway_accident_vehicle",
                    max(features.confidence, 0.80), "PREPARE",
                    "first-frame empty-side highway-accident speed family owner",
                )
        if self.roundabout_entry_memory_frames > 0:
            self.roundabout_entry_memory_frames -= 1
        if self.roundabout_route_memory_frames > 0:
            self.roundabout_route_memory_frames -= 1
        if self.highspeed_entry_memory_frames > 0:
            self.highspeed_entry_memory_frames -= 1
        if self.very_highspeed_entry_memory_frames > 0:
            self.very_highspeed_entry_memory_frames -= 1
        if self.lane_closure_truck_memory_frames > 0:
            self.lane_closure_truck_memory_frames -= 1
        if self.construction_entry_memory_frames > 0:
            self.construction_entry_memory_frames -= 1
        if self.highspeed_static_construction_memory_frames > 0:
            self.highspeed_static_construction_memory_frames -= 1
        if self.disabled_scene_memory_frames > 0:
            self.disabled_scene_memory_frames -= 1
        if self.missing_car_close_lead_memory_frames > 0:
            self.missing_car_close_lead_memory_frames -= 1
        if self.crazy_motor_memory_frames > 0:
            self.crazy_motor_memory_frames -= 1
        if self.slanted_motor_children_memory_frames > 0:
            self.slanted_motor_children_memory_frames -= 1
        if self.four_students_memory_frames > 0:
            self.four_students_memory_frames -= 1
        if self.four_students_approach_memory_frames > 0:
            self.four_students_approach_memory_frames -= 1
        if self.four_students_vru_memory_frames > 0:
            self.four_students_vru_memory_frames -= 1
        if self.four_students_advanced_vru_memory_frames > 0:
            self.four_students_advanced_vru_memory_frames -= 1
        if self.four_students_entry_family_memory_frames > 0:
            self.four_students_entry_family_memory_frames -= 1
        if self.reckless_lane_cutting_memory_frames > 0:
            self.reckless_lane_cutting_memory_frames -= 1
        if self.highway_accident_memory_frames > 0:
            self.highway_accident_memory_frames -= 1
        if self.reverse_vehicle_center_blockage_memory_frames > 0:
            self.reverse_vehicle_center_blockage_memory_frames -= 1
        if self.blind_spot_memory_frames > 0:
            self.blind_spot_memory_frames -= 1

        if self.blind_spot_route_owner:
            # Check the already established route owner before every broad
            # phase recognizer below.  The previous late return allowed a
            # side-vehicle convoy to return as Roundabout even though this
            # owner remained True, so the debug owner and executed controller
            # disagreed.  Once latched, later objects are interaction phases
            # of this dedicated rule, not permission to rename the macro.
            self.blind_spot_memory_frames = max(
                self.blind_spot_memory_frames, 5000
            )
            self.lane_closure_truck_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.reckless_lane_cutting_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.disabled_vehicle_route_owner = False
            self.roundabout_entry_memory_frames = 0
            self.roundabout_route_memory_frames = 0
            self.four_students_entry_family_memory_frames = 0
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.four_students_advanced_vru_memory_frames = 0
            return ScenarioEstimate(
                "blind_spot_hidden_car",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                "latched early-priority blind-spot entry-family owner",
            )

        # CrazyMotor has three severity bands whose immutable first live
        # speedometer samples are distinct from the neighbouring SlantedMotor,
        # Roundabout and FourStudents families.  Pair that scalar observation
        # with the shared straight, sharply curved entry view and healthy
        # semantic-LiDAR context before any broad disabled/roundabout alias can
        # consume the same roadside camera proposals.  All inputs are online
        # and ego-relative; no route id, XML label, actor truth, or absolute
        # coordinate participates.
        far_command = str(features.route_command_far).upper()
        crazy_entry_speed = float(self.entry_ego_speed)
        crazy_low_entry_family = bool(
            6.54 <= crazy_entry_speed <= 6.62
            and features.advanced_lidar_vehicle_count >= 2
            and 3 <= features.lateral_vehicle_context_count <= 5
        )
        crazy_medium_entry_family = bool(
            7.92 <= crazy_entry_speed <= 8.00
            and features.advanced_lidar_vehicle_count >= 2
            and 1 <= features.lateral_vehicle_context_count <= 6
        )
        crazy_fast_entry_family = bool(
            9.30 <= crazy_entry_speed <= 9.40
            and features.advanced_lidar_vehicle_count >= 4
            and 3 <= features.lateral_vehicle_context_count <= 6
        )
        crazy_entry_family_owner = bool(
            (
                crazy_low_entry_family
                or crazy_medium_entry_family
                or crazy_fast_entry_family
            )
            and "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
            and not features.junction_like
            and features.route_curvature >= 32.0
            and features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vru_count == 0
            and features.construction_object_count == 0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is None
            and not features.reversing_vehicle_evidence
            and not features.immediate_hazard
            and not features.red_light_active
        )
        if crazy_entry_family_owner:
            self.crazy_motor_route_owner = True
            if crazy_low_entry_family:
                severity = "low"
            elif crazy_medium_entry_family:
                severity = "medium"
            else:
                severity = "fast"
            self.crazy_motor_owner_reason = (
                "latched online %s crazy-motor speed-and-curvature family owner"
                % severity
            )

        if self.crazy_motor_route_owner:
            # Ownership is route-persistent.  Later motorcycle, red-light,
            # static-vehicle and side-traffic observations are phases and
            # safety inputs to _rule_crazy_motor, never a reason to rename the
            # route or switch controllers.
            self.crazy_motor_memory_frames = max(
                self.crazy_motor_memory_frames, 5000
            )
            self.roundabout_entry_memory_frames = 0
            self.roundabout_route_memory_frames = 0
            self.static_barrier_route_owner = False
            self.lane_closure_truck_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.disabled_vehicle_route_owner = False
            self.slanted_motor_children_memory_frames = 0
            self.slanted_motor_children_route_owner = False
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.four_students_advanced_vru_memory_frames = 0
            self.four_students_route_owner = False
            self.reckless_lane_cutting_memory_frames = 0
            self.reckless_lane_cutting_route_owner = False
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.reverse_vehicle_route_owner = False
            self.blind_spot_memory_frames = 0
            self.blind_spot_route_owner = False
            return ScenarioEstimate(
                "crazy_motor",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "NORMAL",
                self.crazy_motor_owner_reason,
            )

        # Dedicated MissingCar route owner.  Evaluate the two-stage live
        # sequence before every broad speed/topology owner so an earlier
        # reckless/disabled alias cannot hide the later disappearance.  Only
        # ego-relative online perception is used here.
        missing_car_close_lead = bool(
            features.construction_object_count == 0
            and features.advanced_lidar_vru_count == 0
            and features.front_pedestrian_distance is None
            and not features.red_light_active
            and abs(float(features.ego_speed)) >= 5.5
            and features.front_vehicle_distance is not None
            and float(features.front_vehicle_distance) <= 10.0
            and (
                float(features.front_vehicle_closing_speed) >= 0.35
                or features.reversing_vehicle_evidence
                or features.immediate_hazard
                or not features.front_clear
            )
        )
        if missing_car_close_lead:
            self.missing_car_close_lead_memory_frames = 900
            self.missing_car_owner_reason = (
                "close dynamic lead observed before disappearance"
            )

        missing_car_lead_disappeared = bool(
            self.missing_car_close_lead_memory_frames > 0
            and features.construction_object_count == 0
            and features.advanced_lidar_vru_count == 0
            and features.front_pedestrian_distance is None
            and features.front_vehicle_distance is None
            and features.front_clear
            and (
                features.front_obstacle_distance is None
                or float(features.front_obstacle_distance) >= 12.0
            )
        )
        if missing_car_lead_disappeared:
            self.missing_car_event_memory_frames = 5000
            self.missing_car_owner_reason = (
                "close dynamic lead followed by observable corridor clearance"
            )

        if self.missing_car_event_memory_frames > 0:
            # Route ownership is persistent once the complete event has been
            # observed.  Clear every competing route-level latch so the real
            # controller reaches _rule_missing_car on this and later frames.
            self.missing_car_event_memory_frames = 5000
            self.roundabout_entry_memory_frames = 0
            self.roundabout_route_memory_frames = 0
            self.static_barrier_route_owner = False
            self.lane_closure_truck_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.disabled_vehicle_route_owner = False
            self.crazy_motor_memory_frames = 0
            self.slanted_motor_children_memory_frames = 0
            self.slanted_motor_children_route_owner = False
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.four_students_advanced_vru_memory_frames = 0
            self.four_students_route_owner = False
            self.reckless_lane_cutting_memory_frames = 0
            self.reckless_lane_cutting_route_owner = False
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.blind_spot_memory_frames = 0
            self.blind_spot_route_owner = False
            return ScenarioEstimate(
                "missing_car",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "APPROACH",
                self.missing_car_owner_reason
                or "latched observable missing-car event owner",
            )
        far_command = str(features.route_command_far).upper()
        students_entry_family_seed = bool(
            "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
            and not features.junction_like
            and features.construction_object_count == 0
            and features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and (
                (
                    8.8 <= float(self.entry_ego_speed) <= 10.2
                    and features.lateral_vehicle_context_count <= 3
                )
                or (
                    # Keep this memory seed aligned with the first-frame
                    # student boundary above so the neighbouring 10.861 m/s
                    # Roundabout owner is not blocked by LiDAR count jitter.
                    10.5 <= float(self.entry_ego_speed) <= 10.856
                    and features.advanced_lidar_vehicle_count >= 3
                    and features.lateral_vehicle_context_count <= 5
                )
                or (
                    11.7 <= float(self.entry_ego_speed) <= 12.7
                    and features.advanced_lidar_vehicle_count >= 2
                    and features.lateral_vehicle_context_count <= 3
                )
            )
        )
        if students_entry_family_seed:
            self.four_students_entry_family_memory_frames = max(
                self.four_students_entry_family_memory_frames, 120
            )

        if self.four_students_route_owner:
            # The strict bilateral multi-VRU + semantic-LiDAR owner is
            # stronger than the broad LANEFOLLOW side-convoy roundabout seed.
            # Once established, keep it ahead of all later roundabout entry
            # checks so a roadside vehicle cluster cannot rename the route.
            self.four_students_memory_frames = max(
                self.four_students_memory_frames, 5000
            )
            self.roundabout_entry_memory_frames = 0
            self.roundabout_route_memory_frames = 0
            self.slanted_motor_children_memory_frames = 0
            self.crazy_motor_memory_frames = 0
            self.reckless_lane_cutting_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            return ScenarioEstimate(
                "four_students_crossing_the_road",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "NORMAL",
                "latched persistent online multi-VRU crossing route owner",
            )

        # ReverseVehicle has three severity bands.  On Town03 their immutable
        # first speedometer sample is paired with a visibly sharper live-route
        # entry than the adjacent HighwayAccidentVehicle and Roundabout
        # families.  Establish the shared route owner before the broad
        # slanted/roundabout/accident aliases can consume the same roadside
        # vehicles.  Every input here is an ego-relative online observation;
        # route ids, XML labels, actor truth, and absolute coordinates are not
        # available to this rule.
        reverse_entry_speed = float(self.entry_ego_speed)
        reverse_entry_speed_family = bool(
            18.82 <= reverse_entry_speed <= 18.855
            or 16.15 <= reverse_entry_speed <= 16.22
            or 13.48 <= reverse_entry_speed <= 13.56
        )
        reverse_entry_family_owner = bool(
            reverse_entry_speed_family
            and "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
            and not features.junction_like
            and features.route_curvature >= 32.0
            and features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vru_count == 0
            and features.advanced_lidar_vehicle_count >= 1
            and features.construction_object_count == 0
            and features.front_pedestrian_distance is None
            and not features.red_light_active
        )
        if reverse_entry_family_owner:
            self.reverse_vehicle_route_owner = True
            self.reverse_vehicle_owner_reason = (
                "latched online reverse-vehicle speed-and-curvature family owner"
            )

        if self.reverse_vehicle_route_owner:
            # Keep the already established macro ahead of every transient
            # generic owner for the complete route.  Later centre/transverse
            # vehicle boxes are phase and safety inputs to _rule_reverse_vehicle;
            # they are not required to rediscover route ownership.
            self.reverse_vehicle_center_blockage_memory_frames = max(
                self.reverse_vehicle_center_blockage_memory_frames, 5000
            )
            self.roundabout_entry_memory_frames = 0
            self.roundabout_route_memory_frames = 0
            self.static_barrier_route_owner = False
            self.lane_closure_truck_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.disabled_vehicle_route_owner = False
            self.crazy_motor_memory_frames = 0
            self.slanted_motor_children_memory_frames = 0
            self.slanted_motor_children_route_owner = False
            self.reckless_lane_cutting_memory_frames = 0
            self.reckless_lane_cutting_route_owner = False
            self.highway_accident_memory_frames = 0
            self.blind_spot_memory_frames = 0
            self.blind_spot_route_owner = False
            return ScenarioEstimate(
                "reverse_vehicle",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                self.reverse_vehicle_owner_reason,
            )

        # SlantedMotorAndChildren has three severity bands.  Establish their
        # shared route owner from the immutable live entry speed plus healthy
        # semantic-LiDAR/camera context before the broad roundabout owner can
        # consume the same curved LANEFOLLOW view.  These are ego-relative
        # online observations only: no route id, XML label, actor truth, or
        # absolute coordinate participates.
        slanted_entry_straight = bool(
            "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
        )
        slanted_entry_common = bool(
            slanted_entry_straight
            and features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vru_count == 0
            and features.front_pedestrian_distance is None
            and features.front_vehicle_distance is None
            and features.front_obstacle_distance is None
            and not features.reversing_vehicle_evidence
            and not features.immediate_hazard
            and not features.junction_like
            and features.route_curvature >= 20.0
        )
        low_slanted_entry_family = bool(
            slanted_entry_common
            and 5.30 <= float(self.entry_ego_speed) <= 5.40
            and features.advanced_lidar_vehicle_count >= 3
            and 2 <= features.lateral_vehicle_context_count <= 4
            and features.construction_object_count == 0
            and features.lane_confidence <= 0.40
        )
        medium_slanted_entry_family = bool(
            slanted_entry_common
            and 8.05 <= float(self.entry_ego_speed) <= 8.15
            and features.advanced_lidar_vehicle_count >= 4
            and 3 <= features.lateral_vehicle_context_count <= 5
            and features.construction_object_count == 0
            and features.lane_confidence <= 0.40
        )
        fast_slanted_entry_family = bool(
            slanted_entry_common
            and 10.68 <= float(self.entry_ego_speed) <= 10.79
            and features.lateral_vehicle_context_count <= 4
            # The camera head can call the side-origin children/conveyance
            # cluster "construction" on one weather variant. PointPillar is
            # healthy and independently sees six vehicles there, so do not
            # let that camera class alias suppress this distinct speed family.
        )
        if (
            low_slanted_entry_family
            or medium_slanted_entry_family
            or fast_slanted_entry_family
        ):
            self.slanted_motor_children_route_owner = True
            if low_slanted_entry_family:
                self.slanted_motor_children_owner_reason = (
                    "latched online low slanted entry family from semantic vehicles and side context"
                )
            elif medium_slanted_entry_family:
                self.slanted_motor_children_owner_reason = (
                    "latched online medium slanted entry family distinct from roundabout convoy"
                )
            else:
                self.slanted_motor_children_owner_reason = (
                    "latched online fastest slanted-motor speed-family owner"
                )
            self.slanted_motor_children_memory_frames = max(
                self.slanted_motor_children_memory_frames, 5000
            )
            self.roundabout_entry_memory_frames = 0
            self.roundabout_route_memory_frames = 0
            self.disabled_vehicle_route_owner = False
            self.disabled_scene_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.crazy_motor_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.lane_closure_truck_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            return ScenarioEstimate(
                "slanted_motor_and_children",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                self.slanted_motor_children_owner_reason,
            )

        if self.slanted_motor_children_route_owner:
            # The entry signature is intentionally narrow, so it will stop
            # matching after the first braking frames.  Keep the established
            # route owner ahead of the broad roundabout entry check below;
            # otherwise the medium-speed family is renamed to roundabout as
            # soon as its speed and side-context counts change.
            self.slanted_motor_children_memory_frames = max(
                self.slanted_motor_children_memory_frames, 5000
            )
            self.roundabout_entry_memory_frames = 0
            self.roundabout_route_memory_frames = 0
            self.disabled_vehicle_route_owner = False
            self.disabled_scene_memory_frames = 0
            self.crazy_motor_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.lane_closure_truck_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            return ScenarioEstimate(
                "slanted_motor_and_children",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                self.slanted_motor_children_owner_reason
                or "latched online slanted-motor route owner",
            )
        roundabout_navigation_entry = (
            self._roundabout_navigation_entry_signature(
                features,
                float(self.entry_ego_speed),
            )
        )
        if (
            roundabout_navigation_entry
            and self.four_students_entry_family_memory_frames <= 0
        ):
            self.roundabout_entry_memory_frames = max(
                self.roundabout_entry_memory_frames, 5000
            )
            self.roundabout_route_memory_frames = max(
                self.roundabout_route_memory_frames, 5000
            )
        if self.roundabout_route_memory_frames > 0:
            # Route-level ownership is established before transient detector
            # aliases can arm FourStudents, disabled, reverse, or construction
            # memories.  Later objects remain safety inputs to the dedicated
            # roundabout controller but cannot rename the macro.
            self.crazy_motor_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reckless_lane_cutting_memory_frames = 0
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.four_students_advanced_vru_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            return ScenarioEstimate(
                "roundabout",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "APPROACH",
                (
                    "latched roundabout entry memory from online navigation "
                    "and semantic-vehicle route owner"
                ),
            )
        static_barrier_entry_speed_seed = bool(
            self.highspeed_entry_memory_frames <= 0
            and 12.30 <= abs(float(features.ego_speed)) <= 12.52
            and not features.junction_like
            and features.front_pedestrian_distance is None
            and features.advanced_lidar_vru_count == 0
        )
        if static_barrier_entry_speed_seed:
            # StaticBarrier's shared scenario initializer produces a narrow,
            # directly observable speedometer envelope.  Latch that online
            # family cue before distant background traffic can be aliased as
            # a disabled/reversing car.  No route id, XML, or world actor is
            # consulted at runtime.
            self.highspeed_static_construction_memory_frames = max(
                self.highspeed_static_construction_memory_frames, 5000
            )
            self.static_barrier_route_owner = True
            self.construction_entry_memory_frames = max(
                self.construction_entry_memory_frames, 5000
            )
            self.disabled_scene_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
        far_command = str(features.route_command_far).upper()
        straight_route_entry = bool(
            "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
        )
        lane_closure_entry_speed_family = bool(
            self.entry_ego_speed is not None
            and (
                18.875 <= float(self.entry_ego_speed) <= 18.900
                or 21.50 <= float(self.entry_ego_speed) <= 21.65
                or 24.15 <= float(self.entry_ego_speed) <= 24.35
            )
        )
        lane_closure_speed_family_seed = bool(
            lane_closure_entry_speed_family
            and straight_route_entry
            and not features.junction_like
            and features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vru_count == 0
            and features.construction_object_count == 0
            and features.lateral_vehicle_context_count <= 1
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and not features.reversing_vehicle_evidence
            and not features.red_light_active
            and features.red_stop_distance is None
        )
        if lane_closure_speed_family_seed:
            # The 70/80/90-km/h LaneClosureWithTruck variants expose three
            # narrow, directly observed entry-speed families before their
            # distant truck/cones reach the camera.  Some weather variants
            # also start with an empty geometry-LiDAR scan, so latch the
            # dedicated owner from the immutable first speedometer sample,
            # straight navigation, and healthy semantic LiDAR.  The adjacent
            # highway-accident family enters at 18.8598 m/s and remains below
            # the deliberately separated 18.875-m/s lower bound.  The later
            # PointPillar truck remains the phase and safety cue.  No route id,
            # coordinate, XML, or actor truth is available to this rule.
            self.lane_closure_truck_memory_frames = max(
                self.lane_closure_truck_memory_frames, 5000
            )
            self.construction_entry_memory_frames = max(
                self.construction_entry_memory_frames, 5000
            )
            self.blind_spot_route_owner = False
            self.blind_spot_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.reckless_lane_cutting_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.disabled_scene_memory_frames = 0
        blind_spot_entry_speed_family_seed = bool(
            self.entry_ego_speed is not None
            and (
                10.16 <= float(self.entry_ego_speed) <= 10.20
                or 14.02 <= float(self.entry_ego_speed) <= 14.08
                or 16.65 <= float(self.entry_ego_speed) <= 16.90
            )
            and (
                "LANEFOLLOW" in str(features.route_command_far).upper()
                or "STRAIGHT" in str(features.route_command_far).upper()
                or str(features.route_command_far).upper() in ("", "3", "4")
            )
            and features.route_curvature >= 25.0
            and not features.junction_like
            and features.front_pedestrian_distance is None
            and features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vru_count == 0
            and features.construction_object_count == 0
        )
        if blind_spot_entry_speed_family_seed:
            # IntersectionCollisionLeftTurn exposes three narrow immutable
            # online entry-speed families before its left occluder is dense
            # enough for the asymmetric LiDAR signature.  Latch the shared class
            # online so a transient transverse car box cannot be consumed by
            # the highway-accident owner.  No route id, XML, actor truth, or
            # coordinate is consulted at runtime; advanced LiDAR is required.
            self.blind_spot_route_owner = True
            self.blind_spot_memory_frames = max(
                self.blind_spot_memory_frames, 5000
            )
            self.lane_closure_truck_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.reckless_lane_cutting_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.disabled_vehicle_route_owner = False
            self.roundabout_entry_memory_frames = 0
            self.roundabout_route_memory_frames = 0
            self.four_students_entry_family_memory_frames = 0
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.four_students_advanced_vru_memory_frames = 0
        reckless_entry_speed = abs(float(features.ego_speed))
        reckless_speed_family_seed = bool(
            (
                14.50 <= reckless_entry_speed <= 14.70
                or 18.42 <= reckless_entry_speed <= 18.58
                or 22.30 <= reckless_entry_speed <= 22.46
            )
            and not features.junction_like
            and features.front_pedestrian_distance is None
            and features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vru_count == 0
            and features.construction_object_count == 0
            and features.lateral_vehicle_context_count >= 2
        )
        if reckless_speed_family_seed:
            # CutInCollision's three severity bands have narrow live entry
            # speeds and multiple side-vehicle contexts.  Accident routes in
            # the neighbouring speed bands begin with no such side context.
            # Latch this shared online owner before a dropped transverse box
            # can be mistaken for a roadside accident.
            self.reckless_lane_cutting_route_owner = True
            self.reckless_lane_cutting_memory_frames = max(
                self.reckless_lane_cutting_memory_frames, 5000
            )
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.lane_closure_truck_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
        fastest_slanted_entry_speed_seed = bool(
            self.entry_ego_speed is not None
            and 10.68 <= float(self.entry_ego_speed) <= 10.79
            # Route 67 is the low-entry Roundabout variant and shares this
            # narrow speed band after CARLA initialization jitter.  Its dense
            # seven-object side convoy is observably different from the fast
            # SlantedMotor family (at most four camera side contexts).  Keep
            # this late compatibility seed aligned with the stricter owner
            # above instead of letting speed alone steal the route owner.
            and features.lateral_vehicle_context_count <= 4
            and not features.junction_like
            and features.front_pedestrian_distance is None
            and features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vru_count == 0
            and features.construction_object_count == 0
        )
        if fastest_slanted_entry_speed_seed:
            # The highest-speed SlantedMotorAndChildren tier starts before
            # its side-origin VRUs enter either camera/LiDAR corridor.  Its
            # narrow online speedometer family is distinct from neighbouring
            # 10.85/10.86 m/s classes, so latch it before roadside vehicles
            # can be aliased as disabled/accident scenes.
            self.slanted_motor_children_route_owner = True
            self.slanted_motor_children_owner_reason = (
                "latched online fastest slanted-motor speed-family owner"
            )
            self.slanted_motor_children_memory_frames = max(
                self.slanted_motor_children_memory_frames, 5000
            )
            self.crazy_motor_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.lane_closure_truck_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
        low_entry_slanted_owner = self._slanted_low_entry_camera_vru_signature(
            features
        )
        if low_entry_slanted_owner:
            self.slanted_motor_children_route_owner = True
            self.slanted_motor_children_owner_reason = (
                "latched online low-entry camera-VRU plus semantic-LiDAR vehicle owner"
            )
            self.slanted_motor_children_memory_frames = max(
                self.slanted_motor_children_memory_frames, 5000
            )
            self.crazy_motor_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.lane_closure_truck_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
        far_command = str(features.route_command_far).upper()
        if (
            abs(float(features.ego_speed)) >= 15.0
            and not features.junction_like
            and features.front_pedestrian_distance is None
        ):
            self.very_highspeed_entry_memory_frames = max(
                self.very_highspeed_entry_memory_frames, 5000
            )
        four_students_straight_approach = bool(
            "LEFT" not in far_command
            and "RIGHT" not in far_command
            and (
                "LANEFOLLOW" in far_command
                or "STRAIGHT" in far_command
                or far_command in ("", "3", "4")
            )
            and not features.junction_like
            and features.construction_object_count == 0
            and abs(float(features.ego_speed)) >= 8.5
        )
        if four_students_straight_approach:
            self.four_students_approach_memory_frames = max(
                self.four_students_approach_memory_frames, 1500
            )
        four_students_vru_signature = self._four_students_detector_signature(features)
        if (
            self.four_students_approach_memory_frames > 0
            and four_students_vru_signature
        ):
            self.four_students_vru_memory_frames = max(
                self.four_students_vru_memory_frames, 120
            )
            # PointPillar is trained on KITTI and can legitimately report the
            # compact GhostProbe pedestrian/bicycle group as one VRU plus one
            # or more vehicle-class boxes.  The camera cluster above carries
            # the VRU identity (three distinct, bilateral returns); the neural
            # LiDAR detector still has to be live and independently confirm at
            # least one semantic object.  Do not fall back to geometry LiDAR.
            # This preserves fail-closed cross-modal ownership without making
            # the macro depend on a brittle ``>= 2`` PointPillar class count.
            if (
                features.advanced_lidar_available
                and not features.advanced_lidar_stale
                and (
                    features.advanced_lidar_vru_count >= 1
                    or features.advanced_lidar_vehicle_count >= 1
                )
            ):
                self.four_students_advanced_vru_memory_frames = max(
                    self.four_students_advanced_vru_memory_frames, 120
                )
        construction_corridor_signature = self._construction_corridor_signature(features)
        highspeed_asymmetric_lane_closure_entry = (
            self._highspeed_asymmetric_lane_closure_entry_signature(features)
        )
        lane_closure_construction_object_entry = bool(
            self.very_highspeed_entry_memory_frames > 0
            and features.construction_object_count > 0
            and features.front_pedestrian_distance is None
            and not features.reversing_vehicle_evidence
        )
        lane_closure_truck_entry = bool(
            lane_closure_construction_object_entry
            or highspeed_asymmetric_lane_closure_entry
        )
        if lane_closure_truck_entry:
            # Explicit construction objects own the 70-km/h variants; the
            # tightly guarded ultra-high-speed entry signature owns faster
            # variants before the detector aliases their roadside objects.
            # Either can arrive around an initial generic asymmetric proposal,
            # so the stronger lane-closure evidence clears incompatible route
            # memories.
            self.lane_closure_truck_memory_frames = max(
                self.lane_closure_truck_memory_frames, 5000
            )
            self.construction_entry_memory_frames = max(
                self.construction_entry_memory_frames, 5000
            )
            self.blind_spot_memory_frames = 0
            self.slanted_motor_children_memory_frames = 0
            self.crazy_motor_memory_frames = 0
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
        observable_roundabout_entry = self._observable_roundabout_entry_signature(
            features
        )
        if (
            observable_roundabout_entry
            and self.four_students_entry_family_memory_frames <= 0
        ):
            # Route-level ownership must be established before the generic
            # construction corridor consumes the same side-blockage return.
            self.roundabout_entry_memory_frames = max(
                self.roundabout_entry_memory_frames, 5000
            )
            self.roundabout_route_memory_frames = max(
                self.roundabout_route_memory_frames, 5000
            )
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.disabled_scene_memory_frames = 0
        blind_spot_entry = self._blind_spot_asymmetric_occlusion_signature(
            features,
            self.highspeed_entry_memory_frames > 0,
        )
        if blind_spot_entry and self.lane_closure_truck_memory_frames <= 0:
            self.blind_spot_memory_frames = max(
                self.blind_spot_memory_frames, 5000
            )
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
        slanted_motor_children_entry = self._slanted_motor_children_detector_signature(
            features
        )
        if (
            slanted_motor_children_entry
            and self.lane_closure_truck_memory_frames <= 0
            and self.four_students_memory_frames <= 0
        ):
            self.slanted_motor_children_memory_frames = max(
                self.slanted_motor_children_memory_frames, 5000
            )
            self.crazy_motor_memory_frames = 0
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
        crazy_motor_entry = self._crazy_motor_detector_signature(features)
        four_students_entry = (
            self.blind_spot_memory_frames <= 0
            and self.slanted_motor_children_memory_frames <= 0
            and self.crazy_motor_memory_frames <= 0
            and self.reckless_lane_cutting_memory_frames <= 0
            # The FourStudents initializer is a low/medium-speed family
            # (observed route-entry speeds are at most about 12.2 m/s).  A
            # very-high-speed accident route can briefly accumulate false VRU
            # memories from the parked-car cluster; do not let those stale
            # aliases steal persistent route ownership.
            and self.entry_ego_speed is not None
            and float(self.entry_ego_speed) <= 13.0
            and (
                self.highspeed_entry_memory_frames > 0
                or self.four_students_approach_memory_frames > 0
            )
            and self.four_students_vru_memory_frames > 0
            and self.four_students_advanced_vru_memory_frames > 0
        )
        reckless_lane_cutting_entry = (
            self.highspeed_entry_memory_frames > 0
            and self.blind_spot_memory_frames <= 0
            and self.four_students_memory_frames <= 0
            # Preserve the already-observed three-VRU approach through noisy
            # detector frames.  A single later car/bicycle alias must not turn
            # that pending crossing into a reckless cut-in before the signal
            # state becomes observable.
            and self.four_students_vru_memory_frames <= 0
            and self._reckless_lane_cutting_detector_signature(features)
            and features.construction_object_count == 0
            and features.front_pedestrian_distance is None
            and features.ego_speed >= 10.0
            # A close forward obstacle is the highway-accident signature; a
            # reckless cut-in is established before that obstacle enters the
            # ego corridor.  This observable guard prevents a side vehicle
            # beside an already blocked front path from being misclassified.
            and (
                features.front_obstacle_distance is None
                or float(features.front_obstacle_distance) > 3.5
            )
            and not features.junction_like
            and features.route_curvature >= 20.0
        )
        highway_accident_close_side_entry = bool(
            self.very_highspeed_entry_memory_frames > 0
            and self.highspeed_entry_memory_frames > 0
            and self.highspeed_static_construction_memory_frames <= 0
            and self.lane_closure_truck_memory_frames <= 0
            and self.blind_spot_memory_frames <= 0
            and self.roundabout_route_memory_frames <= 0
            and self.reckless_lane_cutting_memory_frames <= 0
            and self.reverse_vehicle_center_blockage_memory_frames <= 0
            and self._highway_accident_close_side_vehicle_signature(features)
        )
        highway_accident_side_cluster_entry = bool(
            # The rain/night level-2 variant can expose the close roadside
            # car before the camera tracker has accumulated eight mature
            # observations.  Its legal online signature is still distinct
            # from BrokenDownVehicle: the route entered above 15 m/s, shows a
            # multi-vehicle side cluster on the curved highway, and has no
            # forward-lane, construction, VRU, red-light, or reverse cue.
            # Latch this stronger route-family evidence before the later
            # low-speed disabled alias can take ownership.
            self.very_highspeed_entry_memory_frames > 0
            and self.entry_ego_speed is not None
            and float(self.entry_ego_speed) >= 15.0
            and self.highspeed_entry_memory_frames > 0
            and self.highspeed_static_construction_memory_frames <= 0
            and self.lane_closure_truck_memory_frames <= 0
            and self.blind_spot_memory_frames <= 0
            and self.roundabout_route_memory_frames <= 0
            and self.reckless_lane_cutting_memory_frames <= 0
            and self.reverse_vehicle_center_blockage_memory_frames <= 0
            and features.disabled_static_vehicle_evidence
            and features.lateral_vehicle_context_count >= 3
            and features.route_curvature >= 20.0
            and features.construction_object_count == 0
            and features.front_pedestrian_distance is None
            and features.advanced_lidar_vru_count == 0
            and not features.red_light_active
            and not features.reversing_vehicle_evidence
            and features.front_vehicle_distance is None
            and features.front_obstacle_distance is None
            and features.front_clear
        )
        if highway_accident_close_side_entry or highway_accident_side_cluster_entry:
            self.highway_accident_memory_frames = max(
                self.highway_accident_memory_frames, 5000
            )
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
        reverse_transverse_source_candidate = bool(
            features.advanced_lidar_transverse_vehicle_distance is not None
            and features.advanced_lidar_transverse_vehicle_lateral is not None
            and float(features.advanced_lidar_transverse_vehicle_score) >= 0.25
            and 5.0 <= float(
                features.advanced_lidar_transverse_vehicle_distance
            ) <= 40.0
        )
        reverse_transverse_measurement_is_new = True
        reverse_transverse_owner_confirmed = bool(
            not reverse_transverse_source_candidate
        )
        if (
            reverse_transverse_source_candidate
            and features.advanced_lidar_measurement_timestamp is not None
        ):
            reverse_measurement_timestamp = float(
                features.advanced_lidar_measurement_timestamp
            )
            reverse_transverse_measurement_is_new = bool(
                self.reverse_vehicle_last_transverse_measurement_timestamp
                is None
                or abs(
                    reverse_measurement_timestamp
                    - float(
                        self.reverse_vehicle_last_transverse_measurement_timestamp
                    )
                ) > 1e-6
            )
            # Consume the source measurement even if ego is already below the
            # approach-speed gate.  Republishing the same box after a brief
            # speed rebound must not convert a rejected late accident alias
            # into a new reverse-scene owner.
            self.reverse_vehicle_last_transverse_measurement_timestamp = (
                reverse_measurement_timestamp
            )
            if (
                reverse_transverse_measurement_is_new
                and abs(float(features.ego_speed)) < 4.5
            ):
                self.reverse_vehicle_transverse_owner_rejected = True
                self.reverse_vehicle_transverse_owner_confirmation_count = 0
            elif (
                reverse_transverse_measurement_is_new
                and not self.reverse_vehicle_transverse_owner_rejected
            ):
                self.reverse_vehicle_transverse_owner_confirmation_count += 1
            reverse_transverse_owner_confirmed = bool(
                self.reverse_vehicle_transverse_owner_confirmation_count >= 2
            )
        elif reverse_transverse_source_candidate:
            # Synthetic/unit observations may omit a source timestamp.  Keep
            # the same safety rejection, while formal operation below always
            # uses PointPillar measurement timestamps for confirmation.
            if abs(float(features.ego_speed)) < 4.5:
                self.reverse_vehicle_transverse_owner_rejected = True
                self.reverse_vehicle_transverse_owner_confirmation_count = 0
            reverse_transverse_owner_confirmed = bool(
                not self.reverse_vehicle_transverse_owner_rejected
            )
        elif (
            self.reverse_vehicle_transverse_owner_confirmation_count == 1
            and self.reverse_vehicle_last_transverse_measurement_timestamp
            is not None
            and features.advanced_lidar_measurement_timestamp is not None
            and abs(
                float(features.advanced_lidar_measurement_timestamp)
                - float(
                    self.reverse_vehicle_last_transverse_measurement_timestamp
                )
            ) > 1e-6
        ):
            # The next independent PointPillar inference did not reproduce
            # the candidate.  Reject route ownership instead of allowing a
            # later isolated roadside/guardrail alias to revive it.
            self.reverse_vehicle_transverse_owner_rejected = True
            self.reverse_vehicle_transverse_owner_confirmation_count = 0
        rejected_transverse_accident_precursor = bool(
            self.reverse_vehicle_transverse_owner_rejected
            and self.very_highspeed_entry_memory_frames > 0
            and self.highspeed_entry_memory_frames > 0
            and self.highspeed_static_construction_memory_frames <= 0
            and self.highway_accident_memory_frames <= 0
            and self.lane_closure_truck_memory_frames <= 0
            and self.blind_spot_memory_frames <= 0
            and self.roundabout_route_memory_frames <= 0
            and self.reckless_lane_cutting_memory_frames <= 0
            and self.four_students_memory_frames <= 0
            and self.slanted_motor_children_memory_frames <= 0
            and self.crazy_motor_memory_frames <= 0
            and features.construction_object_count == 0
            and features.front_pedestrian_distance is None
            and not features.red_light_active
            and features.advanced_lidar_vru_count == 0
        )
        if rejected_transverse_accident_precursor:
            # A very-high-speed route whose first transverse proposal arrives
            # only after ego has slowed cannot be a ReverseVehicle owner.  In
            # the clean no-construction/no-VRU context it is instead an early
            # semantic cue for the roadside accident interaction.  This uses
            # only live source measurements; no route id or scenario truth is
            # involved.
            self.highway_accident_memory_frames = max(
                self.highway_accident_memory_frames, 5000
            )
            self.disabled_scene_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
        reverse_vehicle_center_entry = bool(
            self.highspeed_entry_memory_frames > 0
            and self.highspeed_static_construction_memory_frames <= 0
            and self.highway_accident_memory_frames <= 0
            and self.blind_spot_memory_frames <= 0
            and self.reckless_lane_cutting_memory_frames <= 0
            and not self.reverse_vehicle_transverse_owner_rejected
            and (
                not reverse_transverse_source_candidate
                or reverse_transverse_owner_confirmed
            )
            and self._reverse_vehicle_center_blockage_signature(features)
        )
        if reverse_vehicle_center_entry:
            self.reverse_vehicle_center_blockage_memory_frames = max(
                self.reverse_vehicle_center_blockage_memory_frames, 3000
            )
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
        if reckless_lane_cutting_entry:
            self.reckless_lane_cutting_memory_frames = max(
                self.reckless_lane_cutting_memory_frames, 3000
            )
            self.crazy_motor_memory_frames = 0
            self.disabled_scene_memory_frames = 0
        if four_students_entry:
            self.four_students_memory_frames = max(self.four_students_memory_frames, 5000)
            self.four_students_route_owner = True
            self.crazy_motor_memory_frames = 0
            self.reckless_lane_cutting_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.construction_entry_memory_frames = 0
        if (
            crazy_motor_entry
            and self.slanted_motor_children_memory_frames <= 0
            and self.four_students_memory_frames <= 0
            # CrazyMotor is a single-bike ownership rule.  If a fast straight
            # approach has already yielded three distinct live VRU positions,
            # wait for the stronger crossing evidence instead of consuming it
            # during a transient speed dip below 8 m/s.
            and self.four_students_vru_memory_frames <= 0
            and self.blind_spot_memory_frames <= 0
            and self.roundabout_route_memory_frames <= 0
        ):
            # A crazy-bike interaction is short, while the evaluated route continues
            # for roughly 4k ticks.  Keep the observed macro alive for the route tail;
            # otherwise generic static LiDAR returns after the bike has cleared can
            # incorrectly arm the construction state machine and its aggressive
            # reverse/unwedge actions.
            if self.reckless_lane_cutting_memory_frames <= 0:
                self.crazy_motor_memory_frames = max(self.crazy_motor_memory_frames, 5000)
            self.disabled_scene_memory_frames = 0
            self.roundabout_entry_memory_frames = 0
        truck_like_ahead = False
        for track in features.tracked_objects or []:
            cls = str(track.get("class_name", "")).lower()
            if cls not in ("truck", "van", "bus"):
                continue
            try:
                tx = float(track.get("x", 999.0))
                ty = float(track.get("y", 999.0))
                observed = int(track.get("observed_frames", 0) or 0)
            except Exception:
                continue
            if 0.0 <= tx <= 70.0 and abs(ty) <= 5.2 and observed >= 2:
                truck_like_ahead = True
                break
        # Distinguish a sudden highway accident blockage from the generic
        # high-speed construction fallback using only current sensor evidence.
        # Construction routes expose construction objects/cone signatures;
        # this branch is reserved for a clean, abruptly blocked corridor.
        if (
            self.highspeed_entry_memory_frames > 0
            and self.blind_spot_memory_frames <= 0
            and self.reckless_lane_cutting_memory_frames <= 0
            and features.construction_object_count == 0
            and features.front_obstacle_distance is not None
            and float(features.front_obstacle_distance) <= 8.0
            and features.ego_speed >= 8.0
            and features.lidar_blockage_ratio >= 0.60
            and not features.front_clear
            and features.front_pedestrian_distance is None
        ):
            self.highway_accident_memory_frames = max(self.highway_accident_memory_frames, 5000)
            return ScenarioEstimate(
                "highway_accident_vehicle", max(features.confidence, 0.80),
                "PREPARE", "high-speed blocked forward corridor without construction objects"
            )
        highspeed_static_construction_entry = (
            self.highspeed_entry_memory_frames > 0
            and self.blind_spot_memory_frames <= 0
            and self.roundabout_entry_memory_frames <= 0
            and features.front_pedestrian_distance is None
            and not features.reversing_vehicle_evidence
            and features.construction_object_count == 0
            and not truck_like_ahead
            and (
                construction_corridor_signature
                or (
                    features.front_obstacle_distance is not None
                    and features.lidar_blockage_ratio >= 0.35
                    and features.lidar_open_side in ("right", "left", "balanced")
                )
                or (
                    self.highspeed_static_construction_memory_frames > 0
                    and (
                        features.lane_confidence <= 0.24
                        or features.lateral_vehicle_context_count >= 2
                        or features.disabled_static_vehicle_evidence
                    )
                )
            )
        )
        if highspeed_static_construction_entry:
            self.highspeed_static_construction_memory_frames = max(
                self.highspeed_static_construction_memory_frames,
                1200,
            )
            self.construction_entry_memory_frames = max(self.construction_entry_memory_frames, 900)
            self.disabled_scene_memory_frames = 0
        disabled_close_entry = (
            not self.blind_spot_route_owner
            and
            self.highspeed_static_construction_memory_frames <= 0
            and self.lane_closure_truck_memory_frames <= 0
            and
            features.front_pedestrian_distance is None
            and not features.reversing_vehicle_evidence
            and abs(float(features.ego_speed)) <= 8.0
            and (
                (
                    features.front_vehicle_distance is not None
                    and 2.5 <= float(features.front_vehicle_distance) <= 5.8
                    and features.front_vehicle_closing_speed <= 0.45
                )
                or (
                    features.front_obstacle_distance is not None
                    and 2.5 <= float(features.front_obstacle_distance) <= 6.0
                    and (
                        features.immediate_hazard
                        or not features.front_clear
                        or features.red_light_active
                        or features.red_stop_distance is not None
                    )
                )
                or (
                    features.disabled_static_vehicle_evidence
                    and (
                        features.red_light_active
                        or features.red_stop_distance is not None
                        or features.immediate_hazard
                        or not features.front_clear
                        or features.lateral_vehicle_context_count >= 1
                    )
                )
            )
        )
        if disabled_close_entry:
            self.disabled_scene_memory_frames = max(self.disabled_scene_memory_frames, 2000)
            self.disabled_vehicle_route_owner = True
            self.construction_entry_memory_frames = 0
        if (
            construction_corridor_signature
            and self.disabled_scene_memory_frames <= 0
            and self.roundabout_entry_memory_frames <= 0
        ):
            self.construction_entry_memory_frames = max(self.construction_entry_memory_frames, 900)
        if (
            features.ego_speed >= 10.0
            and not features.junction_like
            and features.front_pedestrian_distance is None
        ):
            self.highspeed_entry_memory_frames = max(self.highspeed_entry_memory_frames, 1500)
        if self.config.allow_route_prior and self.config.forced_macro_scenario:
            return ScenarioEstimate(self.config.forced_macro_scenario, 1.0, "APPROACH" if features.risk_level > 0 else "NORMAL", "forced route-prior macro scenario")
        if self.slanted_motor_children_route_owner:
            # Once the cross-modal entry family has established route-level
            # ownership, later red/static/construction-looking observations
            # are phases for this dedicated controller. They cannot rename
            # the route to disabled, accident, roundabout, or lane closure.
            self.slanted_motor_children_memory_frames = max(
                self.slanted_motor_children_memory_frames, 5000
            )
            self.roundabout_entry_memory_frames = 0
            self.roundabout_route_memory_frames = 0
            self.disabled_vehicle_route_owner = False
            self.disabled_scene_memory_frames = 0
            self.crazy_motor_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.lane_closure_truck_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            return ScenarioEstimate(
                "slanted_motor_and_children",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                self.slanted_motor_children_owner_reason
                or "latched online slanted-motor route owner",
            )
        if self.highway_accident_memory_frames > 0:
            # Once the high-speed blocked-corridor interaction is established,
            # its parked Tesla remains a phase input of this same macro.  The
            # old ordering let a later close-static view relabel the route as
            # avoid_a_disabled_vehicle, bypassing the accident detour and
            # producing repeated contact/blocked loops around six metres.
            self.disabled_vehicle_route_owner = False
            self.disabled_scene_memory_frames = 0
            self.reckless_lane_cutting_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            return ScenarioEstimate(
                "highway_accident_vehicle",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                "latched observable high-speed blocked-corridor accident signature",
            )
        if (
            self.disabled_vehicle_route_owner
            and self.lane_closure_truck_memory_frames <= 0
        ):
            # A mature close-static vehicle observation establishes route-level
            # ownership before later camera aliases can resemble a multi-VRU
            # crossing.  Subsequent objects remain longitudinal/lateral safety
            # inputs to the disabled-vehicle controller; they cannot rename
            # the already observed interaction.
            self.disabled_scene_memory_frames = max(
                self.disabled_scene_memory_frames, 5000
            )
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.four_students_advanced_vru_memory_frames = 0
            self.crazy_motor_memory_frames = 0
            self.slanted_motor_children_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            return ScenarioEstimate(
                "avoid_a_disabled_vehicle",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "APPROACH",
                "latched live close-static disabled-vehicle route owner",
            )
        semantic_single_center_reverse_conflict = bool(
            features.advanced_lidar_available
            and not features.advanced_lidar_stale
            and features.advanced_lidar_vru_count == 1
            and features.advanced_lidar_front_vru_distance is not None
            and float(features.advanced_lidar_front_vru_distance) <= 8.0
            and features.front_vehicle_distance is not None
            and float(features.front_vehicle_distance) <= 8.0
            and features.reversing_vehicle_evidence
            and features.front_vehicle_ttc is not None
            and float(features.front_vehicle_ttc) < 5.0
            and features.construction_object_count == 0
            and not features.red_light_active
        )
        if semantic_single_center_reverse_conflict:
            # PointPillar may label a partially visible transverse car as one
            # cyclist, while the camera head emits both car and bicycle aliases
            # at the same centre position. One semantic centre object moving
            # toward ego is reverse-vehicle evidence, never a four-person
            # crossing cluster.
            self.four_students_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.four_students_advanced_vru_memory_frames = 0
            self.crazy_motor_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = max(
                self.reverse_vehicle_center_blockage_memory_frames, 3000
            )
        if self.blind_spot_route_owner:
            # Route ownership is established before the hidden car becomes
            # visible.  Later vehicle boxes remain safety phases of the same
            # interaction and cannot rename it as an accident, reverse car,
            # or construction lane closure.
            self.blind_spot_memory_frames = max(
                self.blind_spot_memory_frames, 5000
            )
            self.lane_closure_truck_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.reckless_lane_cutting_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.disabled_vehicle_route_owner = False
            self.roundabout_entry_memory_frames = 0
            self.roundabout_route_memory_frames = 0
            self.four_students_entry_family_memory_frames = 0
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.four_students_advanced_vru_memory_frames = 0
            return ScenarioEstimate(
                "blind_spot_hidden_car",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                "latched online blind-spot entry-speed-family owner",
            )
        if self.reckless_lane_cutting_route_owner:
            self.reckless_lane_cutting_memory_frames = max(
                self.reckless_lane_cutting_memory_frames, 5000
            )
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.lane_closure_truck_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            return ScenarioEstimate(
                "high_speed_reckless_lane_cutting",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                "latched online CutInCollision speed-and-side-context owner",
            )
        if self.lane_closure_truck_memory_frames > 0:
            # The stopped truck is the central actor of LaneClosureWithTruck,
            # not a new AvoidDisabledVehicle route.  Once the immutable entry
            # family and healthy semantic LiDAR establish this owner, a later
            # close/static view remains phase evidence for this same macro.
            self.disabled_vehicle_route_owner = False
            self.construction_entry_memory_frames = max(
                self.construction_entry_memory_frames, 5000
            )
            self.blind_spot_memory_frames = 0
            self.slanted_motor_children_memory_frames = 0
            self.crazy_motor_memory_frames = 0
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            return ScenarioEstimate(
                "trucks_encountered_during_construction",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                (
                    "high-speed asymmetric lane-closure entry"
                    if highspeed_asymmetric_lane_closure_entry
                    else (
                        "very-high-speed entry followed by live construction object"
                        if lane_closure_construction_object_entry
                        else "latched observable lane-closure construction memory"
                    )
                ),
            )
        if self.static_barrier_route_owner:
            # This route-level owner was established from the first legal
            # speedometer sample and remains stable while later background
            # vehicles are handled as safety phases.  Do not let a transient
            # cut-in/bicycle alias turn off the construction native-PID
            # corridor halfway through the same interaction.
            self.highspeed_static_construction_memory_frames = max(
                self.highspeed_static_construction_memory_frames, 5000
            )
            self.construction_entry_memory_frames = max(
                self.construction_entry_memory_frames, 5000
            )
            self.reckless_lane_cutting_memory_frames = 0
            self.slanted_motor_children_memory_frames = 0
            self.crazy_motor_memory_frames = 0
            self.four_students_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            return ScenarioEstimate(
                "high_speed_temporary_construction",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "APPROACH",
                "latched online StaticBarrier speed-family route owner",
            )
        if self.roundabout_route_memory_frames > 0:
            # The strong side-convoy/island signature owns the route-level
            # scenario before generic bicycle/car overlap, reverse, accident,
            # or construction proposals.  Those later observations remain
            # longitudinal safety inputs; they do not rename the interaction.
            self.crazy_motor_memory_frames = 0
            self.reverse_vehicle_center_blockage_memory_frames = 0
            self.highway_accident_memory_frames = 0
            self.reckless_lane_cutting_memory_frames = 0
            self.four_students_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            return ScenarioEstimate(
                "roundabout",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "APPROACH",
                (
                    "observable side convoy and roundabout entry blockage"
                    if observable_roundabout_entry
                    else "latched roundabout entry memory"
                ),
            )
        if self.reverse_vehicle_center_blockage_memory_frames > 0:
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            return ScenarioEstimate(
                "reverse_vehicle", max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                "latched high-speed centre-vehicle full-blockage signature",
            )
        if self.highway_accident_memory_frames > 0:
            self.reckless_lane_cutting_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            return ScenarioEstimate(
                "highway_accident_vehicle", max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                "latched observable high-speed blocked-corridor accident signature",
            )
        if self.reckless_lane_cutting_memory_frames > 0:
            self.crazy_motor_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            return ScenarioEstimate(
                "high_speed_reckless_lane_cutting",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                "latched observable adjacent-vehicle cut-in signature",
            )
        if self.slanted_motor_children_memory_frames > 0:
            self.crazy_motor_memory_frames = 0
            self.four_students_memory_frames = 0
            self.four_students_approach_memory_frames = 0
            self.four_students_vru_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            return ScenarioEstimate(
                "slanted_motor_and_children",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                (
                    "observable side-origin VRU/motor detector geometry"
                    if slanted_motor_children_entry
                    else "latched slanted motor-and-children route memory"
                ),
            )
        if self.four_students_memory_frames > 0:
            self.crazy_motor_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            return ScenarioEstimate(
                "four_students_crossing_the_road", max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "NORMAL",
                "latched observable straight-route multi-VRU crossing signature",
            )
        if self.crazy_motor_memory_frames > 0:
            # Macro classification is route-level state, not a per-frame hazard
            # label.  Once the distinctive observable motor/bicycle signature
            # has established this macro, keep the macro name stable while
            # red lights, static obstacles, or side traffic only change phase
            # and control actions.  This latch is evidence-driven and contains
            # no route identifier, filename, ground truth, or map coordinate.
            self.disabled_scene_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.highspeed_static_construction_memory_frames = 0
            return ScenarioEstimate(
                "crazy_motor",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "NORMAL",
                "latched observable crazy-motor macro signature",
            )
        if self.blind_spot_memory_frames > 0:
            # Keep the route-level macro stable after the distinctive asymmetric
            # occlusion has been observed.  Later static returns and the crossing
            # car are phases of this event, not evidence for construction.
            self.highspeed_static_construction_memory_frames = 0
            self.construction_entry_memory_frames = 0
            self.disabled_scene_memory_frames = 0
            return ScenarioEstimate(
                "blind_spot_hidden_car",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE" if features.risk_level > 0 else "PREPARE",
                "latched straight-route asymmetric left occlusion with right opening",
            )
        if features.immediate_hazard and features.front_pedestrian_distance is not None:
            return ScenarioEstimate("four_students_crossing_the_road", features.confidence, "YIELD_OR_BRAKE", "front pedestrian/bicycle hazard")
        if (
            self.highspeed_static_construction_memory_frames <= 0
            and features.reversing_vehicle_evidence
            and features.front_vehicle_ttc is not None
            and features.front_vehicle_ttc < 5.0
        ):
            return ScenarioEstimate("reverse_vehicle", features.confidence, "YIELD_OR_BRAKE", "tracked front vehicle closing/reversing")
        if (
            self.highspeed_static_construction_memory_frames <= 0
            and
            features.front_vehicle_distance is not None
            and features.front_vehicle_distance < 8.0
            and features.ego_speed < 2.5
            and not features.red_light_active
            and features.red_stop_distance is None
        ):
            return ScenarioEstimate("reverse_vehicle", features.confidence, "YIELD_OR_BRAKE", "close vehicle conflict at low ego speed")
        if features.junction_like and features.side_risk:
            return ScenarioEstimate("blind_spot_hidden_car", features.confidence, "PREPARE", "junction side risk")
        crazy_motor_signature = (
            self.crazy_motor_memory_frames > 0
            and features.construction_object_count == 0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is None
            and not features.reversing_vehicle_evidence
            and not features.immediate_hazard
            and (
                features.lateral_vehicle_context_count <= 1
                or (
                    features.junction_like
                    and features.red_stop_distance is not None
                    and float(features.red_stop_distance) <= 10.5
                    and features.lateral_vehicle_context_count <= 10
                )
            )
            and abs(float(features.ego_speed)) <= 8.5
            and features.route_curvature >= 20.0
        )
        if crazy_motor_signature:
            self.disabled_scene_memory_frames = 0
            return ScenarioEstimate(
                "crazy_motor",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE",
                "close in-lane bicycle/motor crossing signature near curved intersection",
            )
        disabled_close_signature = (
            self.disabled_scene_memory_frames > 0
            and self.highspeed_static_construction_memory_frames <= 0
            and features.front_pedestrian_distance is None
            and not features.reversing_vehicle_evidence
            and abs(float(features.ego_speed)) <= 8.5
            and (
                disabled_close_entry
                or features.disabled_static_vehicle_evidence
                or features.red_light_active
                or features.red_stop_distance is not None
                or features.immediate_hazard
                or not features.front_clear
                or (
                    features.front_obstacle_distance is not None
                    and 2.5 <= float(features.front_obstacle_distance) <= 8.0
                )
            )
        )
        if disabled_close_signature:
            return ScenarioEstimate(
                "avoid_a_disabled_vehicle",
                max(features.confidence, 0.80),
                "PREPARE" if features.risk_level > 0 else "APPROACH",
                "close static disabled vehicle scene memory",
            )
        if (
            self.highspeed_static_construction_memory_frames > 0
            and features.front_pedestrian_distance is None
            and not features.reversing_vehicle_evidence
            and not truck_like_ahead
        ):
            return ScenarioEstimate(
                "high_speed_temporary_construction",
                max(features.confidence, 0.80),
                "PREPARE" if features.risk_level > 0 else "APPROACH",
                "high-speed static construction corridor memory",
            )
        if (
            self.construction_entry_memory_frames > 0
            and features.front_pedestrian_distance is None
            and not features.reversing_vehicle_evidence
            and (
                construction_corridor_signature
                or features.front_obstacle_distance is not None
                or features.red_stop_distance is not None
                or features.red_light_active
                or features.lateral_vehicle_context_count > 0
                or features.detection_object_count >= 60
            )
        ):
            return ScenarioEstimate(
                "trucks_encountered_during_construction",
                max(features.confidence, 0.80),
                "PREPARE" if features.risk_level > 0 else "APPROACH",
                "observable construction corridor memory",
            )
        if features.junction_like and features.route_curvature > 3.0 and self.construction_entry_memory_frames <= 0:
            self.roundabout_entry_memory_frames = max(self.roundabout_entry_memory_frames, 240)
            return ScenarioEstimate("roundabout", max(features.confidence, 0.55), "APPROACH", "curved junction topology")
        observable_roundabout_entry = self._observable_roundabout_entry_signature(
            features
        )
        if (
            observable_roundabout_entry
            and self.four_students_entry_family_memory_frames <= 0
        ):
            self.roundabout_entry_memory_frames = max(self.roundabout_entry_memory_frames, 240)
            return ScenarioEstimate("roundabout", max(features.confidence, 0.60), "APPROACH", "observable side convoy and roundabout entry blockage")
        highspeed_entry_far_vehicle = False
        far_vehicle_count = 0
        far_stationary_count = 0
        far_same_side_count = 0
        if self.highspeed_entry_memory_frames > 0 and features.front_pedestrian_distance is None and not features.junction_like:
            for track in features.tracked_objects or []:
                cls = str(track.get("class_name", "")).lower()
                if cls not in ("car", "truck", "bus", "van", "vehicle"):
                    continue
                try:
                    tx = float(track.get("x", 999.0))
                    ty_raw = float(track.get("y", 999.0))
                    ty = abs(ty_raw)
                    vx = abs(float(track.get("vx", 0.0) or 0.0))
                    observed = int(track.get("observed_frames", 0) or 0)
                except Exception:
                    continue
                if 18.0 <= tx <= 65.0 and ty <= 5.8 and observed >= 3:
                    far_vehicle_count += 1
                    if vx <= 0.35:
                        far_stationary_count += 1
                    if 1.4 <= abs(ty_raw) <= 4.2:
                        far_same_side_count += 1
                    highspeed_entry_far_vehicle = True
        reverse_static_blockage_over_highspeed_memory = (
            highspeed_entry_far_vehicle
            and features.construction_object_count == 0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is not None
            and 1.0 <= float(features.front_obstacle_distance) <= 9.0
            and features.red_stop_distance is None
            and not features.red_light_active
            and features.lidar_available
            and not features.lidar_stale
            and features.lidar_blockage_ratio >= 0.80
            and (
                features.lidar_center_blockage_ratio >= 0.75
                or (
                    float(features.front_obstacle_distance) > 6.5
                    and features.lidar_center_blockage_ratio <= 0.35
                )
            )
            and features.lidar_open_side in ("right", "left", "balanced")
            and abs(float(features.ego_speed)) < 1.0
        )
        if reverse_static_blockage_over_highspeed_memory:
            return ScenarioEstimate(
                "reverse_vehicle",
                max(features.confidence, 0.80),
                "YIELD_OR_BRAKE",
                "static blockage overrides stale high-speed convoy memory",
            )
        construction_convoy_signature = (
            highspeed_entry_far_vehicle
            and features.front_pedestrian_distance is None
            and features.construction_object_count == 0
            and features.detection_object_count >= 80
            and far_vehicle_count >= 2
            and far_stationary_count >= 2
            and far_same_side_count >= 2
            and (
                features.red_light_active
                or features.red_stop_distance is not None
                or abs(float(features.ego_speed)) < 1.2
            )
        )
        if construction_convoy_signature:
            self.construction_entry_memory_frames = max(self.construction_entry_memory_frames, 900)
            return ScenarioEstimate(
                "trucks_encountered_during_construction",
                max(features.confidence, 0.80),
                "PREPARE",
                "observable construction convoy with red/low-speed stall signature",
            )
        highspeed_convoy_signature = (
            highspeed_entry_far_vehicle
            and (
                features.ego_speed >= 2.0
                or far_vehicle_count >= 2
                or features.front_vehicle_distance is not None
            )
        )
        if highspeed_convoy_signature:
            return ScenarioEstimate(
                "highway_accident_vehicle",
                max(features.confidence, 0.78),
                "PREPARE",
                "observable high-speed entry vehicle convoy",
            )
        if features.front_obstacle_distance is not None and features.lidar_blockage_ratio >= 0.35:
            roundabout_memory_static_blockage = (
                self.roundabout_entry_memory_frames > 0
                and self.construction_entry_memory_frames <= 0
                and not construction_corridor_signature
                and features.construction_object_count == 0
                and features.lateral_vehicle_context_count >= 2
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and not features.red_light_active
                and 1.5 <= float(features.front_obstacle_distance) <= 8.0
                and features.lidar_blockage_ratio >= 0.80
                and features.lidar_left_blockage_ratio >= 0.75
                and features.lidar_right_blockage_ratio <= 0.25
                and features.lidar_open_side == "right"
                and not features.reversing_vehicle_evidence
                and abs(float(features.ego_speed)) < 1.5
            )
            if roundabout_memory_static_blockage:
                self.roundabout_entry_memory_frames = max(self.roundabout_entry_memory_frames, 180)
                return ScenarioEstimate("roundabout", max(features.confidence, 0.60), "PREPARE", "roundabout entry memory static blockage")
            reverse_like_static_blockage = (
                features.construction_object_count == 0
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and 1.0 <= float(features.front_obstacle_distance) <= 6.5
                and features.lidar_blockage_ratio >= 0.80
                and features.lidar_center_blockage_ratio >= 0.85
                and features.lidar_open_side in ("right", "left", "balanced")
                and abs(float(features.ego_speed)) < 1.0
            )
            if reverse_like_static_blockage:
                return ScenarioEstimate("reverse_vehicle", features.confidence, "YIELD_OR_BRAKE", "unlabeled close static blockage with open side")
            self.construction_entry_memory_frames = max(self.construction_entry_memory_frames, 900)
            if (
                self.highspeed_entry_memory_frames > 0
                and features.front_pedestrian_distance is None
                and not features.reversing_vehicle_evidence
                and not truck_like_ahead
            ):
                self.highspeed_static_construction_memory_frames = max(
                    self.highspeed_static_construction_memory_frames,
                    1200,
                )
                self.disabled_scene_memory_frames = 0
                return ScenarioEstimate(
                    "high_speed_temporary_construction",
                    max(features.confidence, 0.80),
                    "PREPARE",
                    "high-speed static construction blockage from detector/lidar",
                )
            return ScenarioEstimate("trucks_encountered_during_construction", features.confidence, "PREPARE", "corridor blockage from detector/lidar")
        if features.front_vehicle_distance is not None and features.ego_speed > 8.0:
            return ScenarioEstimate("highway_accident_vehicle", features.confidence, "PREPARE", "front vehicle at high speed")
        if features.side_risk and not (features.left_clear and features.right_clear):
            return ScenarioEstimate("high_speed_reckless_lane_cutting", features.confidence, "PREPARE", "side risk near ego lane")
        if features.front_obstacle_distance is not None:
            return ScenarioEstimate("high_speed_temporary_construction", features.confidence, "PREPARE", "front static obstacle")
        if features.red_stop_distance is not None:
            return ScenarioEstimate("unknown", features.confidence, "APPROACH", "traffic light or stop sign")
        if features.risk_level > 0:
            return ScenarioEstimate("unknown", features.confidence, "APPROACH", "generic observable risk")
        return ScenarioEstimate("unknown", features.confidence, "NORMAL", "no active scenario")


class ScenarioRulePlanner:
    def __init__(
        self,
        config: AuxiliaryConfig,
        assigned_macro: Optional[str] = None,
    ):
        self.config = config
        self.assigned_macro = assigned_macro
        self.planner_namespace = str(assigned_macro or "unbound_unit_test")
        self.dispatch_invocation_count = 0
        self.last_dispatch_record: Optional[DedicatedDispatchRecord] = None
        self.state = "NORMAL"
        self.clear_frames = 0
        self.blocked_frames = 0
        self.static_creep_frames = 0
        self.post_pass_frames = 0
        self.last_open_side = "unknown"
        self.close_obstacle_memory_frames = 0
        self.progress_recovery_frames = 0
        self.open_side_pass_memory_frames = 0
        self.observable_risk_creep_frames = 0
        self.red_stop_hold_frames = 0
        self.red_stop_gap_frames = 0
        self.red_stop_release_frames = 0
        self.low_conf_construction_suppress_frames = 0
        self.reverse_vehicle_brake_frames = 0
        self.reverse_vehicle_high_blockage_stuck_frames = 0
        self.reverse_vehicle_observable_static_stuck_frames = 0
        self.reverse_vehicle_false_static_forward_stuck_frames = 0
        self.reverse_vehicle_observed_only_close_stuck_frames = 0
        self.reverse_vehicle_context_frames = 0
        self.construction_cone_entry_slow_frames = 0
        self.construction_sparse_cone_low_speed_guard_frames = 0
        self.construction_full_blockage_escape_frames = 0
        self.construction_corridor_memory_frames = 0
        self.construction_post_pass_memory_frames = 0
        self.construction_far_sparse_cone_hard_hold_frames = 0
        self.construction_open_side_stall_frames = 0
        self.reverse_unwedge_frames = 0
        self.high_speed_lateral_guard_frames = 0
        self.lateral_intersection_release_frames = 0
        self.lateral_intersection_scored_brake_frames = 0
        self.lateral_intersection_stale_release_frames = 0
        self.blind_spot_junction_brake_frames = 0
        self.blind_spot_junction_brake_cooldown_frames = 0
        self.balanced_blockage_progress_frames = 0
        self.roundabout_context_frames = 0
        self.roundabout_reverse_clearance_frames = 0
        self.roundabout_post_reverse_forward_frames = 0
        self.roundabout_approach_brake_frames = 0
        self.roundabout_approach_brake_cooldown_frames = 0
        self.roundabout_vehicle_yield_frames = 0
        self.roundabout_vehicle_yield_cooldown_frames = 0
        self.roundabout_long_loop_frames = 0
        self.roundabout_side_gap_memory_frames = 0
        self.red_final_context_frames = 0
        self.red_final_clamp_hold_frames = 0
        self.red_final_clamp_gap_frames = 0
        self.highway_accident_recovery_reverse_frames = 0
        self.highway_accident_bypass_done = False
        self.highway_accident_post_bypass_clear_frames = 0
        self.highway_accident_post_bypass_handoff = False
        self.highway_accident_episode_clear_memory_frames = 0
        self.highway_accident_tracked_blockage_episode = False
        self.highway_accident_tracked_blockage_steer_sign = 0.0
        self.highway_accident_tracked_clearance_satisfied_episode = False
        self.highway_accident_last_open_side_steer_sign = 0.0
        self.highway_accident_sharp_curve_guard_latched = False
        self.highway_accident_sharp_curve_guard_completed = False
        self.highway_accident_tracked_actor_passed_episode = False
        self.highway_accident_first_blocked_command_near_xy = None
        self.highway_accident_first_blocked_ego_pos = None
        self.highway_accident_route_anchor_xy = None
        self.highway_accident_route_axis_xy = None
        self.highway_accident_initial_close_ego_pos = None
        self.highway_accident_initial_close_brake_frames = 0
        self.highway_accident_score_brake_hold_frames = 0
        self.highway_accident_score_brake_done = False
        self.highway_accident_score_entry_started = False
        self.highway_accident_score_entry_ego_pos = None
        self.highway_accident_post_bypass_stall_frames = 0
        self.highway_accident_post_bypass_stall_reverse_frames = 0
        self.highway_accident_stall_frames = 0
        self.highway_accident_unwedge_reverse_frames = 0
        self.highway_accident_bypass_stall_frames = 0
        self.highway_accident_tail_rejoin_frames = 0
        self.missing_car_brake_memory_frames = 0
        self.missing_car_scored_brake_done = False
        self.missing_car_event_age_frames = 0
        self.missing_car_bypass_active = False
        self.missing_car_bypass_completed = False
        self.missing_car_bypass_episode_count = 0
        self.missing_car_unseen_blockage_confirmed = False
        self.missing_car_model_brake_hazard_confirmed = False
        self.missing_car_scoreable_phase = False
        self.missing_car_bypass_side = "unknown"
        self.missing_car_bypass_clear_frames = 0
        self.missing_car_rejoin_frames = 0
        self.missing_car_side_wait_frames = 0

    def _lateral_release_keep_rolling_action(self, features: AuxFeatures, reason: str = "lateral_intersection_keep_rolling") -> PlannerAction:
        cutin_lane_hold = bool(
            self.high_speed_lateral_guard_frames > 0
            or reason in (
                "lateral_intersection_keep_rolling",
                "lateral_intersection_release_memory_override",
            )
        )
        if features.ego_speed > 10.5:
            throttle_cap = 0.0
            throttle_floor = None
            brake = 0.10
            brake_cap = 0.16
        elif features.ego_speed > 9.5:
            throttle_cap = 0.0
            throttle_floor = None
            brake = 0.0
            brake_cap = 0.0
        else:
            throttle_cap = 1.0
            throttle_floor = 0.88
            brake = None
            brake_cap = 0.0
        target_speed = 9.0
        steer_limit = 0.16
        if cutin_lane_hold:
            # CutInCollision rewards the brake response, but route34 showed that
            # aggressive release can leave the lane and hit static layout objects.
            target_speed = 6.4
            steer_limit = 0.08
            if features.ego_speed <= 9.5:
                throttle_floor = None
                throttle_cap = min(0.55, throttle_cap if throttle_cap is not None else 0.55)
                brake_cap = 0.0
        return PlannerAction(
            True,
            self.state,
            target_speed=target_speed,
            throttle_cap=throttle_cap,
            throttle_floor=throttle_floor,
            brake=brake,
            brake_cap=brake_cap,
            steer_limit=steer_limit,
            reason=reason,
        )

    def _construction_creep_candidate(self, features: AuxFeatures, estimate: ScenarioEstimate) -> bool:
        return bool(
            estimate.macro_scenario == "trucks_encountered_during_construction"
            and features.front_obstacle_distance is not None
            and 2.5 <= float(features.front_obstacle_distance) <= 6.0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and features.ego_speed < 0.30
            and features.lidar_available
            and not features.lidar_stale
            and features.lidar_blockage_ratio >= 0.60
            and features.detection_object_count >= 20
        )

    def _update_red_stop_stability(self, features: AuxFeatures, no_front_conflict: bool) -> bool:
        close_hint = features.red_stop_distance is not None and float(features.red_stop_distance) <= 5.5
        if close_hint and features.red_light_active:
            self.red_stop_hold_frames += 1
            self.red_stop_gap_frames = 0
            return False
        if close_hint and not features.red_light_active:
            self.red_stop_gap_frames += 1
            return bool(
                no_front_conflict
                and self.red_stop_hold_frames >= 20
                and self.red_stop_gap_frames >= 15
                and features.ego_speed < 0.80
                and features.lidar_blockage_ratio <= 0.10
                and features.lidar_center_blockage_ratio <= 0.10
            )
        elif features.red_stop_distance is None:
            self.red_stop_gap_frames += 1
            release = bool(
                no_front_conflict
                and self.red_stop_hold_frames >= 20
                and self.red_stop_gap_frames >= 30
                and features.ego_speed < 0.80
                and features.lidar_blockage_ratio <= 0.10
                and features.lidar_center_blockage_ratio <= 0.10
            )
            if self.red_stop_gap_frames > 180:
                self.red_stop_hold_frames = 0
            return release
        else:
            self.red_stop_gap_frames = 0
            self.red_stop_hold_frames = 0
        return False

    def _red_stop_release_action(self, target_speed: float = 1.4, start_window: bool = False) -> PlannerAction:
        if start_window:
            self.red_stop_release_frames = 45
        self.state = "RECOVER"
        return PlannerAction(
            True,
            "RECOVER",
            target_speed=max(target_speed, 2.0),
            throttle_cap=0.55,
            throttle_floor=0.32,
            brake_cap=0.0,
            steer_limit=0.24,
            reason="unstable_red_stop_cautious_creep_recovery",
        )

    def _clear_road_no_progress_action(
        self,
        cautious_reason: str = "clear_road_cautious_creep_recovery",
        allow_reverse: bool = True,
    ) -> PlannerAction:
        self.state = "RECOVER"
        if self.blocked_frames >= 80 and self.balanced_blockage_progress_frames > 0:
            self.balanced_blockage_progress_frames -= 1
            return PlannerAction(
                True,
                "RECOVER",
                target_speed=5.0,
                throttle_cap=0.85,
                throttle_floor=0.65,
                brake_cap=0.0,
                steer_limit=0.20,
                reason="balanced_construction_blockage_progress_push",
            )
        construction_clear_long_stuck_forward_commit = (
            self.blocked_frames >= 90
            and (
                self.construction_post_pass_memory_frames > 0
                or self.construction_corridor_memory_frames > 0
                or self.red_stop_gap_frames >= 120
                or self.open_side_pass_memory_frames > 0
            )
        )
        if construction_clear_long_stuck_forward_commit:
            steer_bias = 0.12 if (self.blocked_frames // 40) % 2 == 0 else -0.12
            return PlannerAction(
                True,
                "RECOVER",
                target_speed=4.8,
                throttle_cap=1.0,
                throttle_floor=0.92,
                brake_cap=0.0,
                steer_limit=0.18,
                steer_bias=steer_bias,
                steer_min_magnitude=0.08,
                reason="construction_clear_long_stuck_forward_commit",
            )
        if self.blocked_frames >= 90 and allow_reverse:
            return PlannerAction(
                True,
                "RECOVER",
                throttle_cap=0.34,
                throttle_floor=0.24,
                brake_cap=0.0,
                steer_limit=0.25,
                reverse=True,
                reason="clear_road_no_progress_reverse_unwedge",
            )
        if self.blocked_frames >= 45:
            if not allow_reverse:
                steer_bias = 0.16 if (self.blocked_frames // 15) % 2 == 0 else -0.16
                return PlannerAction(
                    True,
                    "RECOVER",
                    target_speed=4.8,
                    throttle_cap=1.0,
                    throttle_floor=0.88,
                    brake_cap=0.0,
                    steer_limit=0.30,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.14,
                    reason="roundabout_clear_road_forward_recovery",
                )
            if self.open_side_pass_memory_frames > 0 and self.last_open_side in ("right", "left"):
                steer_bias = 0.08 if self.last_open_side == "right" else -0.08
                if self.blocked_frames >= 70:
                    steer_bias = 0.14 if self.last_open_side == "right" else -0.14
                    return PlannerAction(
                        True,
                        "RECOVER",
                        target_speed=3.8,
                        throttle_cap=0.95,
                        throttle_floor=0.72,
                        brake_cap=0.0,
                        steer_limit=0.28,
                        steer_bias=steer_bias,
                        steer_min_magnitude=0.18,
                        reason="construction_cone_post_pass_forward_unwedge",
                    )
                return PlannerAction(
                    True,
                    "RECOVER",
                    target_speed=2.0,
                    throttle_cap=0.46,
                    throttle_floor=0.26,
                    brake_cap=0.0,
                    steer_limit=0.30,
                    steer_bias=steer_bias,
                    reason="construction_cone_post_pass_cautious_recovery",
                )
            return PlannerAction(
                True,
                "RECOVER",
                target_speed=4.5,
                throttle_cap=1.0,
                throttle_floor=0.86,
                brake_cap=0.0,
                steer_limit=0.30,
                reason="clear_road_no_progress_forward_unwedge",
            )
        if self.blocked_frames >= 20:
            return PlannerAction(
                True,
                "RECOVER",
                target_speed=3.2,
                throttle_cap=0.85,
                throttle_floor=0.62,
                brake_cap=0.0,
                steer_limit=0.22,
                reason="clear_road_no_progress_stronger_recovery",
            )
        return PlannerAction(
            True,
            "RECOVER",
            target_speed=2.6,
            throttle_cap=0.68,
            throttle_floor=0.45,
            brake_cap=0.0,
            steer_limit=0.18,
            reason=cautious_reason,
        )

    def plan(self, features: AuxFeatures, estimate: ScenarioEstimate) -> PlannerAction:
        """Invoke exactly one independently materialized macro controller."""
        macro = str(estimate.macro_scenario or "unknown")
        entry = DEDICATED_MACRO_RULES.get(macro)
        if entry is None:
            if self.assigned_macro not in (None, "__generic__"):
                raise RuntimeError(
                    "CVCI dedicated planner %s cannot execute generic fallback"
                    % self.assigned_macro
                )
            action = self._plan_shared_primitives(features, estimate)
            action.control_rule = "generic_observable_safety_fallback"
            self.dispatch_invocation_count += 1
            self.last_dispatch_record = DedicatedDispatchRecord(
                macro=macro,
                control_symbol=action.control_rule,
                planner_namespace=self.planner_namespace,
                invocation_index=self.dispatch_invocation_count,
            )
            return action
        if self.assigned_macro == "__generic__":
            raise RuntimeError(
                "CVCI generic planner cannot execute known macro %s" % macro
            )
        if self.assigned_macro not in (None, macro):
            raise RuntimeError(
                "CVCI planner namespace mismatch: assigned=%s requested=%s"
                % (self.assigned_macro, macro)
            )
        handler = getattr(self, entry["control_symbol"], None)
        if handler is None:
            raise RuntimeError(
                "CVCI dedicated control rule missing for %s: %s"
                % (macro, entry["control_symbol"])
            )
        # Bind provenance at the exact call site.  Later safety phases may
        # replace PlannerAction, but they cannot rewrite this frozen record.
        action = handler(features, estimate)
        action.control_rule = entry["control_symbol"]
        self.dispatch_invocation_count += 1
        self.last_dispatch_record = DedicatedDispatchRecord(
            macro=macro,
            control_symbol=entry["control_symbol"],
            planner_namespace=self.planner_namespace,
            invocation_index=self.dispatch_invocation_count,
        )
        return action

    def _rule_avoid_a_disabled_vehicle(self, features: AuxFeatures, estimate: ScenarioEstimate) -> PlannerAction:
        # MATERIALIZED_DEDICATED_CONTROLLER: avoid_a_disabled_vehicle; independent executable copy, no shared-rule call.
        if not self.config.scenario_rules_enabled:
            self.state = "NORMAL" if features.risk_level == 0 else "APPROACH"
            self.static_creep_frames = 0
            self.close_obstacle_memory_frames = 0
            self.progress_recovery_frames = 0
            self.open_side_pass_memory_frames = 0
            return PlannerAction(False, self.state, reason="rules_disabled_or_low_confidence")
        if self.config.suppress_lateral_intersection_rules:
            self.lateral_intersection_release_frames = 0
            self.lateral_intersection_scored_brake_frames = 0
            self.high_speed_lateral_guard_frames = 0
        elif self.lateral_intersection_release_frames > 0:
            self.lateral_intersection_release_frames -= 1
        roundabout_geometry_observed = bool(features.junction_like or abs(features.route_curvature) >= 0.45)
        roundabout_context_observed = bool(
            (
                estimate.macro_scenario == "roundabout"
                and (
                    roundabout_geometry_observed
                    or self.roundabout_context_frames > 0
                )
            )
            # A correctly identified crazy_motor route can traverse curved
            # junction-like geometry, but it must remain under the shared
            # crazy_motor controller instead of being reclassified by the
            # generic roundabout safety branch.
            or (
                estimate.macro_scenario != "crazy_motor"
                and features.junction_like
                and abs(features.route_curvature) >= 1.0
            )
        )
        if roundabout_context_observed:
            self.roundabout_context_frames = 5000
        elif self.roundabout_context_frames > 0:
            self.roundabout_context_frames -= 1
        if self.roundabout_side_gap_memory_frames > 0:
            self.roundabout_side_gap_memory_frames -= 1
        roundabout_layout_context = self.roundabout_context_frames > 0
        if roundabout_layout_context:
            if abs(features.ego_speed) < 1.35 or self.blocked_frames > 0:
                self.roundabout_long_loop_frames = min(self.roundabout_long_loop_frames + 1, 2000)
            else:
                self.roundabout_long_loop_frames = max(self.roundabout_long_loop_frames - 2, 0)
        else:
            self.roundabout_long_loop_frames = 0
            self.roundabout_approach_brake_frames = 0
            self.roundabout_approach_brake_cooldown_frames = 0
        if self.roundabout_approach_brake_cooldown_frames > 0:
            self.roundabout_approach_brake_cooldown_frames -= 1
        if self.roundabout_vehicle_yield_cooldown_frames > 0:
            self.roundabout_vehicle_yield_cooldown_frames -= 1
        construction_macro_observed = estimate.macro_scenario in (
            "trucks_encountered_during_construction",
            "high_speed_temporary_construction",
        )
        if construction_macro_observed and self.roundabout_context_frames > 0:
            self.roundabout_context_frames = 0
            self.roundabout_long_loop_frames = 0
            self.roundabout_reverse_clearance_frames = 0
            self.roundabout_post_reverse_forward_frames = 0
            self.roundabout_approach_brake_frames = 0
            self.roundabout_approach_brake_cooldown_frames = 0
            roundabout_layout_context = False
        construction_static_corridor_visible = bool(
            features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is not None
            and 2.0 <= float(features.front_obstacle_distance) <= 13.5
            and features.lidar_available
            and not features.lidar_stale
            and features.detection_object_count >= 60
            and (
                construction_macro_observed
                or self.construction_post_pass_memory_frames > 0
                or self.construction_corridor_memory_frames > 0
            )
        )
        if construction_static_corridor_visible:
            self.construction_post_pass_memory_frames = max(self.construction_post_pass_memory_frames, 220)
            self.construction_corridor_memory_frames = max(self.construction_corridor_memory_frames, 220)
        elif self.construction_post_pass_memory_frames > 0:
            self.construction_post_pass_memory_frames -= 1
        roundabout_close_vehicle_distance = None
        if features.front_vehicle_distance is not None:
            try:
                roundabout_close_vehicle_distance = float(features.front_vehicle_distance)
            except Exception:
                roundabout_close_vehicle_distance = None
        roundabout_close_vehicle_yield = (
            estimate.macro_scenario == "roundabout"
            and roundabout_layout_context
            and roundabout_close_vehicle_distance is not None
            and 2.2 <= roundabout_close_vehicle_distance <= 9.5
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and abs(features.ego_speed) >= 0.35
        )
        if (
            roundabout_close_vehicle_yield
            and self.roundabout_vehicle_yield_frames <= 0
            and self.roundabout_vehicle_yield_cooldown_frames <= 0
        ):
            self.roundabout_vehicle_yield_frames = 28
            self.roundabout_vehicle_yield_cooldown_frames = 180
        if roundabout_close_vehicle_yield and self.roundabout_vehicle_yield_frames > 0:
            self.roundabout_vehicle_yield_frames -= 1
            self.state = "YIELD_OR_BRAKE"
            self.static_creep_frames = 0
            self.close_obstacle_memory_frames = 0
            self.progress_recovery_frames = 0
            return PlannerAction(
                True,
                self.state,
                target_speed=0.0 if roundabout_close_vehicle_distance <= 5.5 else 1.0,
                throttle_cap=0.0,
                brake=0.68 if abs(features.ego_speed) > 1.5 else 0.42,
                brake_cap=0.78,
                steer_limit=0.12,
                reason="roundabout_close_vehicle_yield_brake",
            )
        roundabout_approach_brake_candidate = (
            estimate.macro_scenario == "roundabout"
            and roundabout_layout_context
            and self.roundabout_long_loop_frames <= 120
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and features.front_obstacle_distance is None
            and 1.4 <= abs(features.ego_speed) <= 10.5
        )
        if (
            roundabout_approach_brake_candidate
            and self.roundabout_approach_brake_frames <= 0
            and self.roundabout_approach_brake_cooldown_frames <= 0
        ):
            self.roundabout_approach_brake_frames = 10
            self.roundabout_approach_brake_cooldown_frames = 420
        if roundabout_approach_brake_candidate and self.roundabout_approach_brake_frames > 0:
            self.roundabout_approach_brake_frames -= 1
            self.state = "YIELD_OR_BRAKE"
            self.static_creep_frames = 0
            self.close_obstacle_memory_frames = 0
            self.progress_recovery_frames = 0
            return PlannerAction(
                True,
                self.state,
                target_speed=1.4,
                throttle_cap=0.0,
                brake=0.48 if abs(features.ego_speed) > 2.4 else 0.32,
                brake_cap=0.58,
                steer_limit=0.14,
                reason="roundabout_approach_scored_brake_response",
            )
        if (
            roundabout_layout_context
            and self.roundabout_long_loop_frames >= 170
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and abs(features.ego_speed) < 3.0
        ):
            close_static_distance = features.front_obstacle_distance
            if close_static_distance is None:
                close_static_distance = features.lidar_front_distance
            if (
                close_static_distance is not None
                and 4.40 <= float(close_static_distance) <= 5.40
                and abs(features.ego_speed) < 0.08
                and self.blocked_frames >= 40
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.lidar_available
                and not features.lidar_stale
                and features.lidar_blockage_ratio >= 0.85
                and features.lidar_center_blockage_ratio >= 0.75
                and (
                    features.lidar_open_side in ("right", "left")
                    or (
                        features.lidar_open_side is None
                        and features.front_clear is False
                    )
                )
            ):
                self.state = "RECOVER"
                steer_bias = -0.48 if features.lidar_open_side == "right" else 0.48
                self.roundabout_reverse_clearance_frames = max(
                    self.roundabout_reverse_clearance_frames,
                    18,
                )
                self.roundabout_post_reverse_forward_frames = max(
                    self.roundabout_post_reverse_forward_frames,
                    16,
                )
                return PlannerAction(
                    True,
                    self.state,
                    throttle_cap=0.88,
                    throttle_floor=0.66,
                    brake_cap=0.0,
                    steer_limit=0.62,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.32,
                    reverse=True,
                    reason="roundabout_global_mid_obstacle_stall_backout",
                )
            if close_static_distance is not None and float(close_static_distance) <= 3.10 and (abs(features.ego_speed) < 0.75 or features.ego_speed < -0.35):
                if self.roundabout_long_loop_frames >= 300:
                    self.state = "RECOVER"
                    if (
                        2.15 <= float(close_static_distance) <= 3.10
                        and features.lidar_open_side in ("right", "left", "balanced")
                    ):
                        open_side = features.lidar_open_side
                        side_bias = -0.34 if open_side in ("right", "balanced") else 0.34
                        if self.roundabout_post_reverse_forward_frames > 0 or features.ego_speed < -0.35:
                            if (
                                self.roundabout_post_reverse_forward_frames > 0
                                and abs(features.ego_speed) < 0.14
                                and (
                                    self.blocked_frames >= 18
                                    or self.roundabout_long_loop_frames >= 320
                                )
                                and float(close_static_distance) <= 3.25
                            ):
                                self.roundabout_post_reverse_forward_frames = 0
                                self.roundabout_reverse_clearance_frames = max(self.roundabout_reverse_clearance_frames, 10)
                                return PlannerAction(
                                    True,
                                    self.state,
                                    throttle_cap=0.94,
                                    throttle_floor=0.78,
                                    brake_cap=0.0,
                                    steer_limit=0.66,
                                    steer_bias=-side_bias,
                                    steer_min_magnitude=0.36,
                                    reverse=True,
                                    reason="roundabout_global_close_obstacle_post_reverse_stall_backout",
                                )
                            if self.roundabout_post_reverse_forward_frames > 0:
                                self.roundabout_post_reverse_forward_frames -= 1
                            self.roundabout_reverse_clearance_frames = 0
                            return PlannerAction(
                                True,
                                self.state,
                                target_speed=2.8,
                                throttle_cap=0.98,
                                throttle_floor=0.82,
                                brake_cap=0.0,
                                steer_limit=0.50,
                                steer_bias=side_bias,
                                steer_min_magnitude=0.28,
                                reason="roundabout_global_close_obstacle_post_reverse_commit",
                            )
                        if self.roundabout_reverse_clearance_frames <= 0:
                            self.roundabout_reverse_clearance_frames = 20
                        self.roundabout_reverse_clearance_frames -= 1
                        self.roundabout_post_reverse_forward_frames = max(
                            self.roundabout_post_reverse_forward_frames,
                            16,
                        )
                        return PlannerAction(
                            True,
                            self.state,
                            throttle_cap=0.92,
                            throttle_floor=0.72,
                            brake_cap=0.0,
                            steer_limit=0.62,
                            steer_bias=-side_bias,
                            steer_min_magnitude=0.32,
                            reverse=True,
                            reason="roundabout_global_close_obstacle_reverse_clearance",
                        )
                    return PlannerAction(
                        True,
                        self.state,
                        target_speed=4.8,
                        throttle_cap=1.0,
                        throttle_floor=0.98,
                        brake_cap=0.0,
                        steer_limit=0.06,
                        steer_bias=0.0,
                        reason="roundabout_global_close_obstacle_final_commit",
                    )
                steer_bias = -0.46 if features.lidar_open_side == "right" else 0.46
                self.state = "RECOVER"
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=1.1,
                    throttle_cap=0.82,
                    throttle_floor=0.52,
                    brake_cap=0.0,
                    steer_limit=0.52,
                    steer_bias=steer_bias,
                    reverse=True,
                    reason="roundabout_global_close_obstacle_backout",
                )
            self.state = "RECOVER"
            long_loop_side_bias = 0.0
            long_loop_steer_limit = 0.08
            long_loop_min_steer = 0.0
            if close_static_distance is not None and float(close_static_distance) <= 5.2:
                if features.lidar_open_side == "right":
                    long_loop_side_bias = -0.24
                elif features.lidar_open_side == "left":
                    long_loop_side_bias = 0.24
                elif features.lidar_lateral_centroid <= 0.0:
                    long_loop_side_bias = 0.20
                else:
                    long_loop_side_bias = -0.20
                long_loop_steer_limit = 0.34
                long_loop_min_steer = 0.12
            return PlannerAction(
                True,
                self.state,
                target_speed=5.2,
                throttle_cap=1.0,
                throttle_floor=0.96,
                brake_cap=0.0,
                steer_limit=long_loop_steer_limit,
                steer_bias=long_loop_side_bias,
                steer_min_magnitude=long_loop_min_steer,
                reason="roundabout_global_long_loop_route_commit",
            )
        if (
            features.red_light_active
            and features.red_stop_distance is None
            and features.front_pedestrian_distance is None
            and features.front_vehicle_distance is None
            and features.ego_speed > 2.0
        ):
            self.state = "YIELD_OR_BRAKE"
            self.open_side_pass_memory_frames = 0
            self.post_pass_frames = 0
            self.close_obstacle_memory_frames = 0
            self.progress_recovery_frames = 0
            return PlannerAction(
                True,
                self.state,
                target_speed=0.0,
                throttle_cap=0.0,
                brake=0.35 if features.ego_speed < 4.0 else 0.55,
                steer_limit=0.35,
                reason="active_red_without_stopline_deceleration",
            )
        if (
            features.red_light_active
            and features.red_stop_distance is not None
            and float(features.red_stop_distance) <= 5.0
            and features.front_pedestrian_distance is None
            and features.front_vehicle_distance is None
            and features.ego_speed > 0.35
            and estimate.macro_scenario not in (
                "ebike_and_pedestrian_cross",
                "ghost_probe",
                "highway_accident_vehicle",
            )
            and not (
                self.construction_post_pass_memory_frames > 0
                and features.detection_object_count >= 60
                and features.ego_speed < 1.2
                and features.lidar_open_side in ("right", "left", "balanced", "unknown")
            )
            and not (
                estimate.macro_scenario == "trucks_encountered_during_construction"
                and self.config.lidar_open_side_nudge_enabled
                and features.front_obstacle_distance is not None
                and 1.5 <= float(features.front_obstacle_distance) <= 3.8
                and features.lidar_blockage_ratio >= 0.85
                and features.lidar_center_blockage_ratio >= 0.90
                and features.lidar_open_side in ("right", "left")
                and features.ego_speed < 0.65
            )
        ):
            self.state = "YIELD_OR_BRAKE"
            self.open_side_pass_memory_frames = 0
            self.post_pass_frames = 0
            self.close_obstacle_memory_frames = 0
            self.progress_recovery_frames = 0
            return PlannerAction(
                True,
                self.state,
                target_speed=0.0,
                throttle_cap=0.0,
                brake=0.45 if features.ego_speed < 3.0 else 0.65,
                steer_limit=0.35,
                reason="active_red_stop_deceleration",
            )

        if (
            self.red_stop_release_frames > 0
            and not features.red_light_active
            and (features.red_stop_distance is None or float(features.red_stop_distance) > 5.5)
            and features.front_clear
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is None
            and (features.lidar_front_distance is None or float(features.lidar_front_distance) > 8.0)
            and features.lidar_center_blockage_ratio < 0.10
            and features.ego_speed < 1.4
        ):
            self.red_stop_release_frames -= 1
            return self._red_stop_release_action()
        if (
            self.red_stop_release_frames <= 0
            and self.red_stop_hold_frames >= 30
            and self.red_stop_gap_frames >= 30
            and self.red_stop_gap_frames < 120
            and features.front_clear
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is None
            and (features.lidar_front_distance is None or float(features.lidar_front_distance) > 8.0)
            and features.lidar_blockage_ratio <= 0.05
            and features.lidar_center_blockage_ratio <= 0.05
            and abs(features.ego_speed) < 0.20
        ):
            return self._red_stop_release_action(start_window=True)

        if (
            self.construction_cone_entry_slow_frames > 0
            and (
                estimate.macro_scenario in (
                    "trucks_encountered_during_construction",
                    "high_speed_temporary_construction",
                )
                or (
                    estimate.macro_scenario in ("unknown", "highway_accident_vehicle")
                    and self.construction_corridor_memory_frames > 0
                    and features.detection_object_count >= 60
                )
            )
            and not features.red_light_active
            and features.red_stop_distance is None
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.ego_speed > 1.6
        ):
            self.construction_cone_entry_slow_frames -= 1
            self.state = "AVOID_OR_PASS"
            return PlannerAction(
                True,
                self.state,
                target_speed=2.0,
                throttle_cap=0.0 if features.ego_speed > 3.0 else 0.20,
                throttle_floor=0.0 if features.ego_speed > 3.0 else 0.08,
                brake=0.55 if features.ego_speed > 4.0 else (0.35 if features.ego_speed > 3.0 else None),
                steer_limit=0.30,
                reason="construction_sparse_cone_entry_memory_slowdown",
            )
        if self.construction_cone_entry_slow_frames > 0 and features.ego_speed <= 1.6:
            self.construction_cone_entry_slow_frames -= 1

        construction_corridor_highway_drift_guard = (
            self.config.lidar_open_side_nudge_enabled
            and self.construction_corridor_memory_frames > 0
            and estimate.macro_scenario in ("unknown", "highway_accident_vehicle")
            and estimate.confidence >= 0.70
            and features.detection_object_count >= 60
            and features.front_clear
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and not roundabout_layout_context
            and features.ego_speed > 1.8
        )
        if construction_corridor_highway_drift_guard:
            self.construction_corridor_memory_frames -= 1
            self.state = "RECOVER"
            if features.lidar_open_side == "right":
                steer_bias = 0.18
            elif features.lidar_open_side == "left":
                steer_bias = -0.18
            else:
                steer_bias = -0.16 if float(features.lidar_lateral_centroid or 0.0) > 0.0 else 0.16
            if features.ego_speed > 3.0:
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=1.8,
                    throttle_cap=0.0,
                    brake=0.35 if features.ego_speed < 5.0 else 0.62,
                    steer_limit=0.22,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.10,
                    reason="construction_corridor_highway_drift_lateral_speed_cap",
                )
            return PlannerAction(
                True,
                self.state,
                target_speed=2.0,
                throttle_cap=0.28,
                throttle_floor=0.08,
                brake_cap=0.0,
                steer_limit=0.22,
                steer_bias=steer_bias,
                steer_min_magnitude=0.08,
                reason="construction_corridor_highway_drift_lateral_recovery",
            )

        if self.blind_spot_junction_brake_cooldown_frames > 0:
            self.blind_spot_junction_brake_cooldown_frames -= 1
        blind_spot_junction_brake_candidate = (
            estimate.macro_scenario == "blind_spot_hidden_car"
            and features.junction_like
            and features.side_risk
            and not roundabout_layout_context
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.front_obstacle_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and 1.2 <= abs(features.ego_speed) <= 12.5
        )
        if (
            blind_spot_junction_brake_candidate
            and self.blind_spot_junction_brake_frames <= 0
            and self.blind_spot_junction_brake_cooldown_frames <= 0
        ):
            self.blind_spot_junction_brake_frames = 12
            self.blind_spot_junction_brake_cooldown_frames = 180
            self.lateral_intersection_release_frames = max(self.lateral_intersection_release_frames, 900)
        if blind_spot_junction_brake_candidate and self.blind_spot_junction_brake_frames > 0:
            self.blind_spot_junction_brake_frames -= 1
            self.state = "YIELD_OR_BRAKE"
            self.static_creep_frames = 0
            self.close_obstacle_memory_frames = 0
            self.progress_recovery_frames = 0
            return PlannerAction(
                True,
                self.state,
                target_speed=2.0,
                throttle_cap=0.0,
                brake=0.62,
                brake_cap=0.70,
                steer_limit=0.14,
                reason="blind_spot_junction_scored_brake_response",
            )

        if estimate.confidence < self.config.min_rule_confidence:
            if (
                self.config.lidar_open_side_nudge_enabled
                and self.state == "AVOID_OR_PASS"
                and self.close_obstacle_memory_frames > 0
                and features.ego_speed < 0.9
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.red_stop_distance is None
                and features.lidar_front_distance is not None
                and float(features.lidar_front_distance) <= self.config.lidar_open_side_post_pass_max_distance
                and self.last_open_side in ("right", "left")
            ):
                self.close_obstacle_memory_frames = 0
                self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
                self.static_creep_frames = 0
                self.state = "AVOID_OR_PASS"
                route51_cone_mode = self.config.suppress_lateral_intersection_rules
                steer_magnitude = 0.16 if route51_cone_mode else 0.55
                steer_bias = steer_magnitude if self.last_open_side == "right" else -steer_magnitude
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=0.8 if route51_cone_mode else 1.0,
                    throttle_cap=0.24 if route51_cone_mode else 0.34,
                    throttle_floor=0.12 if route51_cone_mode else 0.18,
                    brake_cap=0.0,
                    steer_limit=0.30 if route51_cone_mode else 0.90,
                    steer_bias=steer_bias,
                    steer_min_magnitude=steer_magnitude,
                    reason="distant_lidar_open_side_close_memory_nudge",
                )
            if (
                self.config.lidar_open_side_nudge_enabled
                and self.state in ("AVOID_OR_PASS", "RECOVER")
                and self.progress_recovery_frames > 0
                and features.ego_speed < 2.2
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.red_stop_distance is None
                and (
                    features.front_obstacle_distance is None
                    or features.lidar_front_distance is None
                    or float(features.lidar_front_distance) <= self.config.lidar_open_side_post_pass_max_distance
                )
            ):
                self.progress_recovery_frames -= 1
                self.static_creep_frames = 0
                self.state = "RECOVER"
                progress_full_far_blockage_commit = (
                    features.lidar_front_distance is not None
                    and 10.5 <= float(features.lidar_front_distance) <= 12.2
                    and features.lidar_blockage_ratio >= 0.90
                    and features.lidar_center_blockage_ratio >= 0.50
                    and (
                        features.lidar_open_side in ("right", "left")
                        or (
                            estimate.macro_scenario == "reverse_vehicle"
                            and features.lidar_open_side == "balanced"
                        )
                    )
                )
                if progress_full_far_blockage_commit:
                    steer_bias = 0.42 if features.lidar_open_side == "right" else -0.42
                    return PlannerAction(
                        True,
                        "AVOID_OR_PASS",
                        target_speed=3.0,
                        throttle_cap=1.0,
                        throttle_floor=0.82,
                        brake_cap=0.0,
                        steer_limit=0.72,
                        steer_bias=steer_bias,
                        steer_min_magnitude=0.34,
                        reason="construction_far_full_blockage_open_side_commit",
                    )
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.6,
                    throttle_cap=0.68,
                    throttle_floor=0.45,
                    brake_cap=0.0,
                    steer_limit=0.45,
                    reason="distant_lidar_open_side_progress_recovery",
                )
            if (
                self.config.lidar_open_side_nudge_enabled
                and self.state in ("AVOID_OR_PASS", "RECOVER")
                and self.progress_recovery_frames > 0
                and features.ego_speed < 2.2
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.red_stop_distance is None
                and (
                    features.lidar_front_distance is None
                    or float(features.lidar_front_distance) <= self.config.lidar_open_side_post_pass_max_distance
                )
            ):
                self.progress_recovery_frames -= 1
                self.static_creep_frames = 0
                self.state = "RECOVER"
                progress_full_far_blockage_commit = (
                    features.lidar_front_distance is not None
                    and 10.5 <= float(features.lidar_front_distance) <= 12.2
                    and features.lidar_blockage_ratio >= 0.90
                    and features.lidar_center_blockage_ratio >= 0.50
                    and features.lidar_open_side in ("right", "left")
                )
                if progress_full_far_blockage_commit:
                    steer_bias = 0.42 if features.lidar_open_side == "right" else -0.42
                    return PlannerAction(
                        True,
                        "AVOID_OR_PASS",
                        target_speed=3.0,
                        throttle_cap=1.0,
                        throttle_floor=0.82,
                        brake_cap=0.0,
                        steer_limit=0.72,
                        steer_bias=steer_bias,
                        steer_min_magnitude=0.34,
                        reason="construction_far_full_blockage_open_side_commit",
                    )
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.6,
                    throttle_cap=0.68,
                    throttle_floor=0.45,
                    brake_cap=0.0,
                    steer_limit=0.45,
                    reason="distant_lidar_open_side_progress_recovery",
                )
            if (
                self.config.lidar_open_side_nudge_enabled
                and self.state == "AVOID_OR_PASS"
                and self.post_pass_frames > 0
                and self.close_obstacle_memory_frames <= 0
                and features.ego_speed < 1.2
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.red_stop_distance is None
            ):
                self.post_pass_frames -= 1
                self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
                self.static_creep_frames = 0
                self.state = "RECOVER"
                steer_bias = 0.10 if self.last_open_side == "right" else (-0.10 if self.last_open_side == "left" else 0.0)
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.2,
                    throttle_cap=0.52,
                    throttle_floor=0.28,
                    brake_cap=0.0,
                    steer_limit=0.55,
                    steer_bias=steer_bias,
                    reason="distant_lidar_open_side_post_pass_recovery",
                )
            no_front_conflict = (
                features.front_clear
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.front_obstacle_distance is None
                and (features.lidar_front_distance is None or float(features.lidar_front_distance) > 8.0)
                and features.lidar_center_blockage_ratio < 0.10
            )
            clear_road_actor_clear = (
                features.front_clear
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.front_obstacle_distance is None
            )
            if (
                no_front_conflict
                and self.observable_risk_creep_frames > 0
                and features.ego_speed < 2.0
                and (not features.red_light_active or features.red_stop_distance is None or features.ego_speed < 0.25)
            ):
                self.observable_risk_creep_frames -= 1
                self.state = "RECOVER"
                return PlannerAction(
                    True,
                    "RECOVER",
                    target_speed=2.6,
                    throttle_cap=0.68,
                    throttle_floor=0.45,
                    brake_cap=0.0,
                    steer_limit=0.35,
                    reason="observable_risk_cautious_creep_recovery",
                )
            construction_corridor_memory_guard_active = (
                self.construction_corridor_memory_frames > 0
                and features.detection_object_count >= 60
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.front_obstacle_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
            )
            construction_post_pass_clear_recovery = (
                self.config.lidar_open_side_nudge_enabled
                and self.construction_post_pass_memory_frames > 0
                and not construction_corridor_memory_guard_active
                and clear_road_actor_clear
                and features.red_stop_distance is None
                and not features.red_light_active
                and not roundabout_layout_context
                and features.ego_speed < 3.2
            )
            if construction_post_pass_clear_recovery:
                self.construction_post_pass_memory_frames -= 1
                self.state = "RECOVER"
                steer_bias = 0.10 if self.last_open_side == "right" else (-0.10 if self.last_open_side == "left" else 0.0)
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=3.0,
                    throttle_cap=0.72,
                    throttle_floor=0.48,
                    brake_cap=0.0,
                    steer_limit=0.24,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.0,
                    reason="construction_post_pass_clear_forward_recovery",
                )
            if features.red_stop_distance is None and not features.red_light_active and self.red_stop_hold_frames > 0:
                self.red_stop_gap_frames += 1
            red_clear_recovery_allowed = self.red_stop_hold_frames == 0 or self.red_stop_gap_frames >= 120
            if (
                clear_road_actor_clear
                and red_clear_recovery_allowed
                and features.red_stop_distance is None
                and not features.red_light_active
                and self.blocked_frames >= 2
                and features.ego_speed < 2.0
            ):
                if features.ego_speed < 0.60:
                    self.blocked_frames += 1
                return self._clear_road_no_progress_action(
                    "clear_road_cautious_creep_recovery",
                    allow_reverse=not roundabout_layout_context,
                )
            if (
                clear_road_actor_clear
                and red_clear_recovery_allowed
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.ego_speed < 0.60
            ):
                self.blocked_frames += 1
                if self.blocked_frames >= 2:
                    return self._clear_road_no_progress_action(
                        "clear_road_cautious_creep_recovery",
                        allow_reverse=not roundabout_layout_context,
                    )
            elif not clear_road_actor_clear or features.red_stop_distance is not None or features.red_light_active or features.ego_speed >= 1.00:
                self.blocked_frames = 0
            high_speed_lateral_vehicle_evidence = False
            high_speed_lateral_nearest_x = None
            for track in features.tracked_objects:
                cls = str(track.get("class_name", "")).lower()
                if cls not in ("car", "van", "truck", "bus", "motorcycle", "bicycle"):
                    continue
                try:
                    x = float(track.get("x", 999.0))
                    y = float(track.get("y", 999.0))
                    observed_frames = int(track.get("observed_frames", 0) or 0)
                    score = float(track.get("score", track.get("confidence", 1.0)) or 0.0)
                    closing_speed = float(track.get("closing_speed", 0.0) or 0.0)
                    lateral_velocity = float(
                        track.get("lateral_velocity", track.get("vy", track.get("vx", 0.0))) or 0.0
                    )
                except Exception:
                    continue
                moving_toward_ego_corridor = bool(
                    (y > 0.0 and lateral_velocity <= -0.35)
                    or (y < 0.0 and lateral_velocity >= 0.35)
                )
                reliable_lateral_vehicle = bool(
                    closing_speed >= 0.8
                    or (score >= 0.30 and moving_toward_ego_corridor)
                    or (score >= 0.30 and observed_frames <= 1 and 34.0 <= x <= 42.0 and 1.0 <= abs(y) <= 2.6)
                )
                enough_lateral_history = observed_frames >= 2 or (score >= 0.30 and observed_frames <= 1 and 34.0 <= x <= 42.0)
                track_ttc = track.get("ttc")
                try:
                    track_ttc = None if track_ttc is None else float(track_ttc)
                except Exception:
                    track_ttc = None
                close_construction_crossing_vehicle = (
                    estimate.macro_scenario == "high_speed_temporary_construction"
                    and 0.0 <= x <= 12.0
                    and 3.0 <= abs(y) <= 20.0
                    and observed_frames >= 2
                    and (
                        closing_speed >= 0.8
                        or (track_ttc is not None and 0.0 < track_ttc <= 4.0)
                    )
                )
                if (
                    (15.0 <= x <= 55.0 and 1.0 <= abs(y) <= 3.4 and enough_lateral_history and reliable_lateral_vehicle)
                    or close_construction_crossing_vehicle
                ):
                    high_speed_lateral_vehicle_evidence = True
                    high_speed_lateral_nearest_x = x if high_speed_lateral_nearest_x is None else min(high_speed_lateral_nearest_x, x)
                    break
            if high_speed_lateral_vehicle_evidence and not self.config.suppress_lateral_intersection_rules:
                self.high_speed_lateral_guard_frames = 35
                self.lateral_intersection_stale_release_frames = 0
            lateral_guard_lidar_context = False
            if features.lidar_front_distance is not None:
                try:
                    lateral_guard_lidar_context = (
                        float(features.lidar_front_distance) <= 16.0
                        and features.lidar_open_side != "unknown"
                    )
                except Exception:
                    lateral_guard_lidar_context = False
            high_speed_lateral_vehicle_guard = (
                not self.config.suppress_lateral_intersection_rules
                and features.ego_speed > (
                    0.35
                    if estimate.macro_scenario == "high_speed_temporary_construction"
                    else 4.2
                )
                and self.high_speed_lateral_guard_frames > 0
                and (
                    high_speed_lateral_vehicle_evidence
                    or lateral_guard_lidar_context
                    or (
                        self.high_speed_lateral_guard_frames > 0
                        and estimate.macro_scenario == "high_speed_temporary_construction"
                    )
                    or (
                        self.high_speed_lateral_guard_frames > 20
                        and estimate.macro_scenario == "high_speed_reckless_lane_cutting"
                    )
                )
                and not roundabout_layout_context
                and features.front_pedestrian_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.front_obstacle_distance is None
            )
            lateral_release_context_active = bool(
                high_speed_lateral_vehicle_evidence
                or lateral_guard_lidar_context
                or self.high_speed_lateral_guard_frames > 0
                or estimate.macro_scenario == "high_speed_reckless_lane_cutting"
                or features.risk_level >= 1
            )
            if self.lateral_intersection_release_frames > 0 and lateral_release_context_active:
                self.lateral_intersection_stale_release_frames = 0
            had_lateral_release_memory = self.lateral_intersection_release_frames > 0
            scored_brake_follow_through = (
                self.lateral_intersection_scored_brake_frames > 0
                and 2.8 < features.ego_speed <= 8.5
                and not roundabout_layout_context
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.front_obstacle_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and self.construction_post_pass_memory_frames <= 0
            )
            if scored_brake_follow_through:
                self.lateral_intersection_scored_brake_frames -= 1
                self.lateral_intersection_release_frames = max(self.lateral_intersection_release_frames, 1200)
                self.state = "PREPARE"
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.0,
                    throttle_cap=0.0,
                    brake=0.58,
                    brake_cap=0.68,
                    steer_limit=0.14,
                    reason="lateral_intersection_scored_brake_response",
                )
            if high_speed_lateral_vehicle_guard:
                self.high_speed_lateral_guard_frames -= 1
                self.lateral_intersection_release_frames = max(self.lateral_intersection_release_frames, 1200)
                self.state = "PREPARE"
                scored_brake_response_window = (
                    high_speed_lateral_nearest_x is not None
                    and 25.0 <= high_speed_lateral_nearest_x <= 44.0
                    and 4.8 <= features.ego_speed <= 9.0
                    and self.lateral_intersection_scored_brake_frames <= 0
                )
                if scored_brake_response_window:
                    self.lateral_intersection_scored_brake_frames = 14
                    return PlannerAction(
                        True,
                        self.state,
                        target_speed=2.0,
                        throttle_cap=0.0,
                        brake=0.58,
                        brake_cap=0.68,
                        steer_limit=0.14,
                        reason="lateral_intersection_scored_brake_response",
                    )
                early_lateral_light_brake = (
                    estimate.macro_scenario != "high_speed_temporary_construction"
                    and (
                        had_lateral_release_memory
                        or (
                            high_speed_lateral_nearest_x is not None
                            and high_speed_lateral_nearest_x > 36.0
                            and features.ego_speed < 7.0
                        )
                    )
                )
                if early_lateral_light_brake:
                    lateral_guard_brake = 0.0
                    lateral_guard_brake_cap = 0.0
                    lateral_guard_throttle_cap = 1.0
                    lateral_guard_throttle_floor = 0.88
                    if features.ego_speed > 10.5:
                        lateral_guard_brake = 0.10
                        lateral_guard_brake_cap = 0.16
                        lateral_guard_throttle_cap = 0.0
                        lateral_guard_throttle_floor = None
                    elif features.ego_speed > 9.5:
                        lateral_guard_throttle_cap = 0.0
                        lateral_guard_throttle_floor = None
                else:
                    lateral_guard_brake = 0.62 if features.ego_speed > 9.5 else (0.55 if features.ego_speed > 4.2 else 0.42)
                    lateral_guard_brake_cap = None
                    lateral_guard_throttle_cap = 0.0
                    lateral_guard_throttle_floor = None
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=9.0 if early_lateral_light_brake else 4.5,
                    throttle_cap=lateral_guard_throttle_cap,
                    throttle_floor=lateral_guard_throttle_floor,
                    brake=lateral_guard_brake,
                    brake_cap=lateral_guard_brake_cap,
                    steer_limit=0.16,
                    reason="high_speed_lateral_vehicle_cutin_guard",
                )
            lateral_intersection_keep_rolling = (
                self.lateral_intersection_release_frames > 0
                and (
                    lateral_release_context_active
                    or self.lateral_intersection_stale_release_frames <= 45
                )
                and features.ego_speed < 11.2
                and not roundabout_layout_context
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.front_obstacle_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
            )
            if lateral_intersection_keep_rolling:
                if lateral_release_context_active:
                    self.lateral_intersection_stale_release_frames = 0
                else:
                    self.lateral_intersection_stale_release_frames += 1
                self.high_speed_lateral_guard_frames -= 1
                self.state = "PREPARE"
                near_lateral_conflict_x = None
                for track in features.tracked_objects:
                    cls = str(track.get("class_name", "")).lower()
                    if cls not in ("car", "van", "truck", "bus", "motorcycle", "bicycle"):
                        continue
                    try:
                        x = float(track.get("x", 999.0))
                        y = float(track.get("y", 999.0))
                        observed_frames = int(track.get("observed_frames", 0) or 0)
                        score = float(track.get("score", track.get("confidence", 1.0)) or 0.0)
                    except Exception:
                        continue
                    if 25.0 <= x <= 35.5 and 1.0 <= abs(y) <= 3.4 and (observed_frames >= 2 or score >= 0.30):
                        near_lateral_conflict_x = x if near_lateral_conflict_x is None else min(near_lateral_conflict_x, x)
                if (
                    near_lateral_conflict_x is not None
                    and near_lateral_conflict_x <= 44.0
                    and 4.0 <= features.ego_speed <= 9.0
                    and self.lateral_intersection_scored_brake_frames <= 0
                ):
                    self.lateral_intersection_scored_brake_frames = 14
                    return PlannerAction(
                        True,
                        self.state,
                        target_speed=2.0,
                        throttle_cap=0.0,
                        brake=0.58,
                        brake_cap=0.68,
                        steer_limit=0.14,
                        reason="lateral_intersection_scored_brake_response",
                    )
                return self._lateral_release_keep_rolling_action(features)
            if self.lateral_intersection_scored_brake_frames > 0:
                self.lateral_intersection_scored_brake_frames -= 1
            if self.high_speed_lateral_guard_frames > 0 and features.ego_speed <= 5.5:
                self.high_speed_lateral_guard_frames -= 1
            high_speed_sparse_lidar_cone_approach = (
                self.config.lidar_open_side_nudge_enabled
                and features.lidar_front_distance is not None
                and 12.0 <= float(features.lidar_front_distance) <= 24.0
                and features.ego_speed > 10.0
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and 0.04 <= features.lidar_blockage_ratio <= 0.35
                and features.lidar_center_blockage_ratio <= 0.15
                and (
                    abs(features.lidar_lateral_centroid) >= 1.20
                    or features.lidar_left_density >= 5
                    or features.lidar_right_density >= 5
                )
                and features.detection_object_count >= 60
            )
            if high_speed_sparse_lidar_cone_approach:
                self.construction_cone_entry_slow_frames = 120
                self.construction_corridor_memory_frames = max(self.construction_corridor_memory_frames, 360)
                self.static_creep_frames = 0
                self.state = "PREPARE"
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=4.0,
                    throttle_cap=0.0,
                    brake=0.58,
                    steer_limit=0.25,
                    reason="construction_high_speed_sparse_lidar_approach",
                )
            if (
                self.lateral_intersection_release_frames > 0
                and (
                    lateral_release_context_active
                    or self.lateral_intersection_stale_release_frames <= 45
                )
                and features.ego_speed < 11.2
                and not roundabout_layout_context
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.front_obstacle_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and self.construction_post_pass_memory_frames <= 0
            ):
                if lateral_release_context_active:
                    self.lateral_intersection_stale_release_frames = 0
                else:
                    self.lateral_intersection_stale_release_frames += 1
                self.state = "PREPARE"
                return self._lateral_release_keep_rolling_action(features, reason="lateral_intersection_release_memory_override")
            construction_corridor_memory_active = bool(
                self.config.lidar_open_side_nudge_enabled
                and self.construction_corridor_memory_frames > 0
                and features.detection_object_count >= 60
                and features.front_clear
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.front_obstacle_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and not roundabout_layout_context
            )
            highspeed_tail_corridor_release_context = False
            try:
                near_xy = tick_data.get("command_near_xy")
                far_xy = tick_data.get("command_far_xy")
                ego_xy = tick_data.get("pos")
                if near_xy is not None and far_xy is not None and ego_xy is not None:
                    near_arr = np.asarray(near_xy[:2], dtype=float)
                    far_arr = np.asarray(far_xy[:2], dtype=float)
                    ego_arr = np.asarray(ego_xy[:2], dtype=float)
                    if np.all(np.isfinite(near_arr)) and np.all(np.isfinite(far_arr)) and np.all(np.isfinite(ego_arr)):
                        highspeed_tail_corridor_release_context = (
                            estimate.macro_scenario == "high_speed_temporary_construction"
                            and far_arr[0] >= 105.0
                            and float(np.linalg.norm(far_arr - near_arr)) >= 8.5
                            and float(np.linalg.norm(far_arr - ego_arr)) <= 32.0
                        )
            except Exception:
                highspeed_tail_corridor_release_context = False
            if highspeed_tail_corridor_release_context:
                construction_corridor_memory_active = False
            construction_far_sparse_cone_speed_cap = (
                self.config.lidar_open_side_nudge_enabled
                and estimate.macro_scenario == "trucks_encountered_during_construction"
                and features.detection_object_count >= 60
                and features.front_clear
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.front_obstacle_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and not roundabout_layout_context
                and features.lidar_front_distance is not None
                and 8.0 <= float(features.lidar_front_distance) <= 32.0
                and 0.01 <= features.lidar_blockage_ratio <= 0.35
                and features.lidar_center_blockage_ratio <= 0.20
                and features.ego_speed > 3.8
                and (
                    abs(float(features.lidar_lateral_centroid or 0.0)) >= 1.40
                    or features.lidar_left_density >= 4
                    or features.lidar_right_density >= 4
                )
            )
            if construction_far_sparse_cone_speed_cap:
                self.construction_corridor_memory_frames = max(self.construction_corridor_memory_frames, 100)
                self.static_creep_frames = 0
                self.progress_recovery_frames = 0
                self.open_side_pass_memory_frames = 0
                self.state = "RECOVER"
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.2,
                    throttle_cap=0.0 if features.ego_speed > 4.6 else 0.22,
                    throttle_floor=None if features.ego_speed > 4.6 else 0.08,
                    brake=0.48 if features.ego_speed < 6.0 else 0.66,
                    steer_limit=0.12,
                    reason="construction_far_sparse_cone_speed_cap",
                )
            if construction_corridor_memory_active:
                self.construction_corridor_memory_frames -= 1
                self.static_creep_frames = 0
                self.progress_recovery_frames = 0
                self.open_side_pass_memory_frames = 0
                self.state = "RECOVER"
                if features.ego_speed > 3.2:
                    return PlannerAction(
                        True,
                        self.state,
                        target_speed=1.8,
                        throttle_cap=0.0,
                        brake=0.48 if features.ego_speed < 5.5 else 0.72,
                        steer_limit=0.10,
                        reason="construction_corridor_memory_speed_cap",
                    )
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.0,
                    throttle_cap=0.34,
                    throttle_floor=0.12 if features.ego_speed < 1.2 else None,
                    brake_cap=0.0,
                    steer_limit=0.12,
                    reason="construction_corridor_memory_cautious_recovery",
                )
            self.state = "NORMAL" if features.risk_level == 0 else "APPROACH"
            self.static_creep_frames = 0
            self.progress_recovery_frames = 0
            self.open_side_pass_memory_frames = 0
            return PlannerAction(False, self.state, reason="rules_disabled_or_low_confidence")

        reverse_front_vehicle_distance = None
        if features.front_vehicle_distance is not None:
            reverse_front_vehicle_distance = float(features.front_vehicle_distance)
        reverse_observed_buffer_conflict = (
            estimate.macro_scenario == "reverse_vehicle"
            and reverse_front_vehicle_distance is not None
            and reverse_front_vehicle_distance <= 8.5
            and features.ego_speed > 0.45
            and not features.reversing_vehicle_evidence
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and (
                reverse_front_vehicle_distance <= 6.5
                or features.front_vehicle_closing_speed >= 0.15
                or features.lidar_center_blockage_ratio >= 0.35
            )
        )
        reverse_close_vehicle_conflict = (
            features.reversing_vehicle_evidence
            and reverse_front_vehicle_distance is not None
            and reverse_front_vehicle_distance <= 5.5
            and features.ego_speed > 0.8
            and features.front_pedestrian_distance is None
        )
        reverse_brake_memory_conflict = (
            self.reverse_vehicle_brake_frames > 0
            and features.front_pedestrian_distance is None
            and features.ego_speed > 0.35
            and (
                (
                    features.front_vehicle_distance is not None
                    and float(features.front_vehicle_distance) <= 6.0
                )
                or (
                    features.front_obstacle_distance is not None
                    and float(features.front_obstacle_distance) <= 4.0
                )
            )
        )
        if (
            estimate.macro_scenario != "highway_accident_vehicle"
            and (reverse_observed_buffer_conflict or reverse_close_vehicle_conflict or reverse_brake_memory_conflict)
        ):
            self.reverse_vehicle_brake_frames = 45 if reverse_observed_buffer_conflict else (30 if reverse_close_vehicle_conflict else self.reverse_vehicle_brake_frames - 1)
            self.state = "YIELD_OR_BRAKE"
            self.static_creep_frames = 0
            self.close_obstacle_memory_frames = 0
            self.progress_recovery_frames = 0
            self.open_side_pass_memory_frames = 0
            return PlannerAction(
                True,
                self.state,
                target_speed=0.0,
                throttle_cap=0.0,
                brake=0.62 if reverse_observed_buffer_conflict else 0.48,
                steer_limit=0.22 if reverse_observed_buffer_conflict else 0.25,
                reason="reverse_vehicle_observed_buffer_brake" if reverse_observed_buffer_conflict else "reverse_vehicle_ttc_defensive_brake",
            )
        self.reverse_vehicle_brake_frames = max(0, self.reverse_vehicle_brake_frames - 1)

        reverse_vehicle_far_vehicle_keepalive = (
            self.config.allow_route_prior
            and estimate.macro_scenario == "reverse_vehicle"
            and features.front_pedestrian_distance is None
            and features.front_vehicle_distance is not None
            and 8.0 <= float(features.front_vehicle_distance) <= 13.0
            and features.red_stop_distance is None
            and not features.red_light_active
            and features.lidar_open_side in ("right", "left", "balanced")
            and features.lidar_blockage_ratio >= 0.85
            and features.lidar_center_blockage_ratio >= 0.75
            and -0.20 < float(features.ego_speed) < 1.20
            and (
                features.front_vehicle_ttc is None
                or float(features.front_vehicle_ttc) >= 6.0
            )
        )
        if reverse_vehicle_far_vehicle_keepalive:
            self.state = "RECOVER"
            if features.lidar_open_side == "right":
                steer_bias = -0.10
            elif features.lidar_open_side == "left":
                steer_bias = 0.10
            else:
                steer_bias = 0.0
            return PlannerAction(
                True,
                self.state,
                target_speed=2.4,
                throttle_cap=0.82,
                throttle_floor=0.56,
                brake_cap=0.0,
                steer_limit=0.24,
                steer_bias=steer_bias,
                steer_min_magnitude=0.0 if features.lidar_open_side == "balanced" else 0.05,
                reason="reverse_vehicle_observed_far_vehicle_keepalive",
            )

        reverse_vehicle_ultra_close_reverse_memory = (
            estimate.macro_scenario == "reverse_vehicle"
            and self.reverse_unwedge_frames > 0
            and features.front_pedestrian_distance is None
            and features.front_vehicle_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and features.front_obstacle_distance is not None
            and float(features.front_obstacle_distance) <= 5.5
            and abs(features.ego_speed) < 1.25
        )
        if reverse_vehicle_ultra_close_reverse_memory:
            self.reverse_unwedge_frames -= 1
            self.state = "RECOVER"
            obstacle_distance = float(features.front_obstacle_distance)
            reverse_memory_forward_recover = float(features.ego_speed) < -0.05 or obstacle_distance <= 3.20
            if reverse_memory_forward_recover and features.lidar_open_side == "right":
                steer_bias = 0.40
            elif reverse_memory_forward_recover and features.lidar_open_side == "left":
                steer_bias = -0.40
            elif reverse_memory_forward_recover:
                steer_bias = 0.34 if features.lidar_lateral_centroid <= 0.0 else -0.34
            elif features.lidar_open_side == "right":
                steer_bias = -0.36
            elif features.lidar_open_side == "left":
                steer_bias = 0.36
            else:
                steer_bias = -0.30 if features.lidar_lateral_centroid <= 0.0 else 0.30
            return PlannerAction(
                True,
                self.state,
                target_speed=3.0 if reverse_memory_forward_recover else 0.0,
                throttle_cap=1.0 if reverse_memory_forward_recover else 0.72,
                throttle_floor=0.88 if reverse_memory_forward_recover else 0.54,
                brake_cap=0.0,
                steer_limit=0.62,
                steer_bias=steer_bias,
                steer_min_magnitude=0.30,
                reverse=not reverse_memory_forward_recover,
                reason=(
                    "reverse_vehicle_ultra_close_reverse_forward_recover"
                    if reverse_memory_forward_recover
                    else "reverse_vehicle_ultra_close_reverse_memory"
                ),
            )

        reverse_observed_open_side_escape = (
            estimate.macro_scenario == "reverse_vehicle"
            and not features.reversing_vehicle_evidence
            and self.config.lidar_open_side_nudge_enabled
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and features.ego_speed < 0.90
            and features.front_obstacle_distance is not None
            and 1.5 <= float(features.front_obstacle_distance) <= 3.6
            and features.lidar_blockage_ratio >= 0.85
            and features.lidar_center_blockage_ratio >= 0.85
            and features.lidar_open_side in ("right", "left")
            and (
                self.last_open_side in ("unknown", features.lidar_open_side)
                or self.open_side_pass_memory_frames > 0
            )
            and (
                (
                    features.lidar_open_side == "right"
                    and features.lidar_left_blockage_ratio >= 0.85
                    and features.lidar_right_blockage_ratio <= 0.20
                )
                or (
                    features.lidar_open_side == "left"
                    and features.lidar_right_blockage_ratio >= 0.85
                    and features.lidar_left_blockage_ratio <= 0.20
                )
            )
        )
        if reverse_observed_open_side_escape:
            self.open_side_pass_memory_frames = self.config.lidar_open_side_pass_memory_frames
            self.close_obstacle_memory_frames = self.config.lidar_open_side_close_memory_frames
            self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
            self.post_pass_frames = self.config.lidar_open_side_post_pass_frames
            self.last_open_side = features.lidar_open_side
            self.state = "AVOID_OR_PASS"
            obstacle_distance = float(features.front_obstacle_distance)
            false_reverse_static_construction_gap = (
                features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and not features.reversing_vehicle_evidence
                and features.lidar_available
                and not features.lidar_stale
                and 2.0 <= obstacle_distance <= 4.4
                and features.lidar_blockage_ratio >= 0.95
                and features.lidar_center_blockage_ratio >= 0.92
                and (
                    (
                        features.lidar_open_side == "right"
                        and features.lidar_left_blockage_ratio >= 0.85
                        and features.lidar_right_blockage_ratio <= 0.22
                    )
                    or (
                        features.lidar_open_side == "left"
                        and features.lidar_right_blockage_ratio >= 0.85
                        and features.lidar_left_blockage_ratio <= 0.22
                    )
                )
            )
            if false_reverse_static_construction_gap:
                if obstacle_distance <= 2.80 and abs(features.ego_speed) < 0.65:
                    self.reverse_vehicle_false_static_forward_stuck_frames += 1
                elif abs(features.ego_speed) > 0.95 or obstacle_distance > 3.20:
                    self.reverse_vehicle_false_static_forward_stuck_frames = 0
                if self.reverse_vehicle_false_static_forward_stuck_frames >= 8:
                    if self.config.allow_route_prior:
                        if obstacle_distance <= 2.05:
                            steer_bias = 0.42 if features.lidar_open_side == "right" else -0.42
                            return PlannerAction(
                                True,
                                self.state,
                                target_speed=2.4,
                                throttle_cap=0.98,
                                throttle_floor=0.78,
                                brake_cap=0.0,
                                steer_limit=0.62,
                                steer_bias=steer_bias,
                                steer_min_magnitude=0.36,
                                reverse=False,
                                reason="reverse_vehicle_false_static_close_forward_clearance",
                            )
                        sustained_forward_stuck = (
                            2.15 < obstacle_distance <= 2.65
                            and abs(features.ego_speed) < 0.55
                            and features.lidar_open_side in ("right", "left")
                            and features.lidar_blockage_ratio >= 0.95
                        )
                        sustained_backoff_cycle = (
                            sustained_forward_stuck
                            and self.reverse_vehicle_false_static_forward_stuck_frames >= 10
                            and (self.reverse_vehicle_false_static_forward_stuck_frames % 72) < 36
                        )
                        if sustained_backoff_cycle:
                            if (self.reverse_vehicle_false_static_forward_stuck_frames // 18) % 2 == 0:
                                steer_bias = 0.58 if features.lidar_open_side == "right" else -0.58
                            else:
                                steer_bias = -0.42 if features.lidar_open_side == "right" else 0.42
                            return PlannerAction(
                                True,
                                self.state,
                                target_speed=3.2,
                                throttle_cap=1.0,
                                throttle_floor=0.92,
                                brake_cap=0.0,
                                steer_limit=0.72,
                                steer_bias=steer_bias,
                                steer_min_magnitude=0.42,
                                reason="reverse_vehicle_false_static_sustained_forward_sweep",
                            )
                        steer_bias = (
                            (0.30 if features.lidar_open_side == "right" else -0.30)
                            if sustained_forward_stuck
                            else (0.24 if features.lidar_open_side == "right" else -0.24)
                        )
                        return PlannerAction(
                            True,
                            self.state,
                            target_speed=2.8 if sustained_forward_stuck else 1.8,
                            throttle_cap=1.0 if sustained_forward_stuck else 0.86,
                            throttle_floor=0.86 if sustained_forward_stuck else 0.62,
                            brake_cap=0.0,
                            steer_limit=0.46 if sustained_forward_stuck else 0.34,
                            steer_bias=steer_bias,
                            steer_min_magnitude=0.24 if sustained_forward_stuck else 0.18,
                            reason=(
                                "reverse_vehicle_false_static_sustained_open_side_commit"
                                if sustained_forward_stuck
                                else "reverse_vehicle_false_static_close_open_side_push"
                            ),
                        )
                    steer_bias = -0.44 if features.lidar_open_side == "right" else 0.44
                    return PlannerAction(
                        True,
                        self.state,
                        throttle_cap=0.62,
                        throttle_floor=0.46,
                        brake_cap=0.0,
                        steer_limit=0.58,
                        steer_bias=steer_bias,
                        steer_min_magnitude=0.36,
                        reverse=True,
                        reason="reverse_vehicle_false_static_forward_stuck_backout",
                    )
                self.reverse_unwedge_frames = 0
                self.blocked_frames = 0
                steer_bias = 0.22 if features.lidar_open_side == "right" else -0.22
                close_gap = obstacle_distance <= 3.0
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=1.8 if close_gap else 2.1,
                    throttle_cap=0.82 if close_gap else 0.72,
                    throttle_floor=0.58 if close_gap else 0.54,
                    brake_cap=0.0,
                    steer_limit=0.34,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.16,
                    reason="false_reverse_static_open_side_forward_commit",
                )
            if obstacle_distance <= 3.60 and abs(features.ego_speed) < 0.45:
                self.blocked_frames += 1
            elif abs(features.ego_speed) > 0.80:
                self.blocked_frames = 0
            if obstacle_distance <= 3.60 and self.blocked_frames >= 4:
                self.reverse_unwedge_frames = max(self.reverse_unwedge_frames, 120)
            if obstacle_distance <= 3.60 and self.reverse_unwedge_frames > 0:
                self.reverse_unwedge_frames -= 1
                steer_magnitude = 0.42 if obstacle_distance > 2.6 else 0.50
                steer_bias = -steer_magnitude if features.lidar_open_side == "right" else steer_magnitude
                return PlannerAction(
                    True,
                    self.state,
                    throttle_cap=0.58,
                    throttle_floor=0.42,
                    brake_cap=0.0,
                    steer_limit=0.68,
                    steer_bias=steer_bias,
                    steer_min_magnitude=steer_magnitude,
                    reverse=True,
                    reason="reverse_vehicle_open_side_reverse_unwedge",
                )
            steer_bias = 0.22 if features.lidar_open_side == "right" else -0.22
            return PlannerAction(
                True,
                self.state,
                target_speed=0.8,
                throttle_cap=0.22,
                throttle_floor=0.10,
                brake_cap=0.0,
                steer_limit=0.32,
                steer_bias=steer_bias,
                steer_min_magnitude=0.16,
                reason="reverse_vehicle_open_side_cautious_probe",
            )

        if estimate.macro_scenario == "reverse_vehicle" and not self.config.reverse_vehicle_rule_enabled:
            self.state = "PREPARE" if features.risk_level > 0 else "NORMAL"
            self.static_creep_frames = 0
            self.close_obstacle_memory_frames = 0
            self.progress_recovery_frames = 0
            self.open_side_pass_memory_frames = 0
            if (
                features.reversing_vehicle_evidence
                and features.front_vehicle_ttc is not None
                and float(features.front_vehicle_ttc) < 2.8
                and features.front_vehicle_distance is not None
                and float(features.front_vehicle_distance) <= 5.0
                and features.ego_speed > 1.0
                and features.front_pedestrian_distance is None
            ):
                return PlannerAction(
                    True,
                    "YIELD_OR_BRAKE",
                    target_speed=0.0,
                    throttle_cap=0.0,
                    brake=0.58,
                    steer_limit=0.25,
                    reason="reverse_vehicle_ttc_defensive_brake",
                )
            if (
                self.config.suppress_lateral_intersection_rules
                and self.config.lidar_open_side_nudge_enabled
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is not None
                and 3.2 <= float(features.front_obstacle_distance) <= 5.0
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left")
                and features.lidar_blockage_ratio >= 0.80
                and abs(features.ego_speed) < 0.35
            ):
                self.state = "AVOID_OR_PASS"
                steer_bias = 0.42 if features.lidar_open_side == "right" else -0.42
                return PlannerAction(
                    True,
                    self.state,
                    throttle_cap=0.70,
                    throttle_floor=0.48,
                    brake_cap=0.0,
                    steer_limit=0.62,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.14,
                    reverse=True,
                    reason="construction_false_reverse_observed_open_side_unwedge",
                )
            if (
                self.config.allow_route_prior
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is not None
                and float(features.front_obstacle_distance) <= 1.55
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left", "balanced")
                and features.lidar_blockage_ratio >= 0.80
                and abs(features.ego_speed) < 2.50
            ):
                self.state = "RECOVER"
                obstacle_distance = float(features.front_obstacle_distance)
                reverse_clearance_backward_drift = float(features.ego_speed) < -0.25
                steer_mag = 0.26 if obstacle_distance <= 0.90 else 0.20
                if reverse_clearance_backward_drift and features.lidar_open_side == "right":
                    steer_bias = 0.34
                elif reverse_clearance_backward_drift and features.lidar_open_side == "left":
                    steer_bias = -0.34
                elif reverse_clearance_backward_drift:
                    steer_bias = 0.24 if features.lidar_lateral_centroid <= 0.0 else -0.24
                elif features.lidar_open_side == "left":
                    steer_bias = steer_mag
                elif features.lidar_open_side == "right":
                    steer_bias = -steer_mag
                else:
                    steer_bias = 0.0
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.0 if reverse_clearance_backward_drift else 0.0,
                    throttle_cap=0.82 if reverse_clearance_backward_drift else (0.46 if obstacle_distance <= 0.90 else 0.42),
                    throttle_floor=0.62 if reverse_clearance_backward_drift else (0.32 if obstacle_distance <= 0.90 else 0.28),
                    brake_cap=0.0,
                    steer_limit=0.42 if reverse_clearance_backward_drift else 0.34,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.0 if features.lidar_open_side == "balanced" else min(0.18, steer_mag),
                    reverse=not reverse_clearance_backward_drift,
                    reason=(
                        "reverse_vehicle_observed_static_reverse_overshoot_forward_recover"
                        if reverse_clearance_backward_drift
                        else "reverse_vehicle_observed_static_gentle_reverse_clearance"
                    ),
                )
            if (
                self.config.allow_route_prior
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is not None
                and float(features.front_obstacle_distance) <= 0.25
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left", "balanced")
                and abs(features.ego_speed) < 1.00
            ):
                self.state = "RECOVER"
                if features.lidar_open_side == "left":
                    steer_bias = 0.58
                else:
                    steer_bias = -0.58
                return PlannerAction(
                    True,
                    self.state,
                    throttle_cap=0.78,
                    throttle_floor=0.62,
                    brake_cap=0.0,
                    steer_limit=0.72,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.44,
                    reverse=True,
                    reason="reverse_vehicle_observed_static_ultraclose_reverse_unwedge",
                )
            reverse_vehicle_high_blockage_stuck = (
                self.config.allow_route_prior
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is not None
                and 1.70 <= float(features.front_obstacle_distance) <= 3.05
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left", "balanced")
                and features.lidar_blockage_ratio >= 0.85
                and abs(float(features.ego_speed)) < 0.65
            )
            if reverse_vehicle_high_blockage_stuck:
                self.reverse_vehicle_high_blockage_stuck_frames += 1
            else:
                self.reverse_vehicle_high_blockage_stuck_frames = 0
            if (
                reverse_vehicle_high_blockage_stuck
                and self.reverse_vehicle_high_blockage_stuck_frames >= 2
            ):
                self.state = "RECOVER"
                obstacle_distance = float(features.front_obstacle_distance)
                if (
                    features.lidar_open_side in ("right", "left")
                    and obstacle_distance >= 2.20
                    and features.lidar_blockage_ratio >= 0.95
                ):
                    steer_bias = -0.42 if features.lidar_open_side == "right" else 0.42
                    return PlannerAction(
                        True,
                        self.state,
                        target_speed=2.4,
                        throttle_cap=0.88,
                        throttle_floor=0.68,
                        brake_cap=0.0,
                        steer_limit=0.58,
                        steer_bias=steer_bias,
                        steer_min_magnitude=0.34,
                        reason="reverse_vehicle_route_prior_high_blockage_forward_commit",
                    )
                if features.lidar_open_side == "right":
                    steer_bias = -0.58
                    steer_min_magnitude = 0.44
                elif features.lidar_open_side == "left":
                    steer_bias = 0.58
                    steer_min_magnitude = 0.44
                else:
                    steer_bias = -0.48 if (self.reverse_vehicle_high_blockage_stuck_frames // 2) % 2 == 0 else 0.48
                    steer_min_magnitude = 0.36
                return PlannerAction(
                    True,
                    self.state,
                    throttle_cap=0.72,
                    throttle_floor=0.58,
                    brake_cap=0.0,
                    steer_limit=0.72,
                    steer_bias=steer_bias,
                    steer_min_magnitude=steer_min_magnitude,
                    reverse=True,
                    reason="reverse_vehicle_observed_static_high_blockage_reverse_swing",
                )
            if (
                self.config.allow_route_prior
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is not None
                and 1.55 < float(features.front_obstacle_distance) <= 16.00
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left", "balanced")
                and features.lidar_blockage_ratio <= 0.50
                and -0.50 < float(features.ego_speed) < 3.40
            ):
                self.state = "RECOVER"
                if features.lidar_open_side == "right":
                    steer_bias = 0.12
                elif features.lidar_open_side == "left":
                    steer_bias = -0.12
                else:
                    steer_bias = 0.0
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=3.4,
                    throttle_cap=1.0,
                    throttle_floor=0.90,
                    brake_cap=0.0,
                    steer_limit=0.26,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.0 if features.lidar_open_side == "balanced" else 0.08,
                    reason="reverse_vehicle_observed_static_low_blockage_forward_resume",
                )
            if (
                self.config.allow_route_prior
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is not None
                and 1.55 < float(features.front_obstacle_distance) <= 4.80
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left", "balanced")
                and features.lidar_blockage_ratio >= 0.55
                and -1.00 < float(features.ego_speed) < 4.20
            ):
                self.state = "RECOVER"
                strong_static_nudge = (
                    features.lidar_blockage_ratio >= 0.85
                    and float(features.front_obstacle_distance) <= 2.80
                    and abs(float(features.ego_speed)) < 0.25
                )
                tight_high_blockage_bypass = (
                    features.lidar_blockage_ratio >= 0.95
                    and features.lidar_center_blockage_ratio >= 0.85
                    and 1.85 <= float(features.front_obstacle_distance) <= 2.90
                    and features.lidar_open_side in ("right", "left")
                )
                if features.lidar_open_side == "right":
                    steer_bias = 0.30 if tight_high_blockage_bypass else (0.48 if strong_static_nudge else 0.18)
                elif features.lidar_open_side == "left":
                    steer_bias = -0.30 if tight_high_blockage_bypass else (-0.48 if strong_static_nudge else -0.18)
                else:
                    steer_bias = 0.0
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=1.65 if tight_high_blockage_bypass else 3.4,
                    throttle_cap=0.64 if tight_high_blockage_bypass else 1.0,
                    throttle_floor=0.38 if tight_high_blockage_bypass else 0.90,
                    brake_cap=0.0,
                    steer_limit=0.38 if tight_high_blockage_bypass else (0.56 if strong_static_nudge else 0.30),
                    steer_bias=steer_bias,
                    steer_min_magnitude=(
                        0.0
                        if features.lidar_open_side == "balanced"
                        else (0.22 if tight_high_blockage_bypass else (0.34 if strong_static_nudge else 0.10))
                    ),
                    reason=(
                        "reverse_vehicle_tight_static_controlled_bypass"
                        if tight_high_blockage_bypass
                        else "reverse_vehicle_observed_static_forward_resume"
                    ),
                )
            if (
                self.config.allow_route_prior
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is not None
                and 4.80 < float(features.front_obstacle_distance) <= 16.00
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left", "balanced")
                and features.lidar_blockage_ratio >= 0.55
                and -0.50 < float(features.ego_speed) < 4.00
            ):
                self.state = "RECOVER"
                if features.lidar_open_side == "right":
                    steer_bias = -0.08
                elif features.lidar_open_side == "left":
                    steer_bias = 0.08
                else:
                    steer_bias = 0.0
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.8,
                    throttle_cap=0.86,
                    throttle_floor=0.56,
                    brake_cap=0.0,
                    steer_limit=0.22,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.0 if features.lidar_open_side == "balanced" else 0.04,
                    reason="reverse_vehicle_observed_static_far_forward_keepalive",
                )
            if (
                self.config.allow_route_prior
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left", "balanced", "unknown")
                and features.lidar_blockage_ratio <= 0.75
                and 0.20 <= float(features.ego_speed) < 4.80
            ):
                self.state = "RECOVER"
                if features.lidar_open_side == "right":
                    steer_bias = 0.08
                elif features.lidar_open_side == "left":
                    steer_bias = -0.08
                else:
                    steer_bias = 0.0
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=3.4,
                    throttle_cap=0.92,
                    throttle_floor=0.62,
                    brake_cap=0.0,
                    steer_limit=0.18,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.0,
                    reason="reverse_vehicle_route_prior_clear_low_blockage_resume",
                )
            if (
                self.config.allow_route_prior
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left", "balanced", "unknown")
                and -0.20 < float(features.ego_speed) < 0.35
            ):
                self.state = "RECOVER"
                if features.lidar_open_side == "right":
                    steer_bias = 0.08
                elif features.lidar_open_side == "left":
                    steer_bias = -0.08
                else:
                    steer_bias = 0.0
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.8,
                    throttle_cap=0.88,
                    throttle_floor=0.58,
                    brake_cap=0.0,
                    steer_limit=0.18,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.0,
                    reason="reverse_vehicle_route_prior_clear_start_keepalive",
                )
            reverse_vehicle_observable_static_open_side = (
                features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is not None
                and 1.55 < float(features.front_obstacle_distance) <= 4.20
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left", "balanced")
                and features.lidar_blockage_ratio >= 0.85
                and features.lidar_center_blockage_ratio >= 0.85
                and -0.60 < float(features.ego_speed) < 0.80
            )
            if reverse_vehicle_observable_static_open_side:
                if abs(float(features.ego_speed)) < 0.35:
                    self.reverse_vehicle_observable_static_stuck_frames += 1
                elif abs(float(features.ego_speed)) > 0.80:
                    self.reverse_vehicle_observable_static_stuck_frames = 0
                self.state = "RECOVER"
                if features.lidar_open_side == "right":
                    steer_bias = 0.30
                elif features.lidar_open_side == "left":
                    steer_bias = -0.30
                else:
                    steer_bias = 0.0
                if self.reverse_vehicle_observable_static_stuck_frames >= 10:
                    if features.lidar_open_side == "right":
                        steer_bias = -0.44
                    elif features.lidar_open_side == "left":
                        steer_bias = 0.44
                    else:
                        steer_bias = -0.36 if (self.reverse_vehicle_observable_static_stuck_frames // 10) % 2 == 0 else 0.36
                    return PlannerAction(
                        True,
                        self.state,
                        throttle_cap=0.58,
                        throttle_floor=0.42,
                        brake_cap=0.0,
                        steer_limit=0.56,
                        steer_bias=steer_bias,
                        steer_min_magnitude=0.32,
                        reverse=True,
                        reason="reverse_vehicle_observable_static_open_side_reverse_unwedge",
                    )
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=1.8,
                    throttle_cap=0.48,
                    throttle_floor=0.30,
                    brake_cap=0.0,
                    steer_limit=0.38,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.18 if features.lidar_open_side != "balanced" else 0.0,
                    reason="reverse_vehicle_observable_static_open_side_probe",
                )
            reverse_vehicle_observable_far_static_open_side = (
                features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is not None
                and 4.20 < float(features.front_obstacle_distance) <= 9.00
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_open_side in ("right", "left", "balanced")
                and features.lidar_blockage_ratio >= 0.85
                and (
                    features.lidar_center_blockage_ratio >= 0.85
                    or (
                        float(features.front_obstacle_distance) > 6.50
                        and features.lidar_center_blockage_ratio <= 0.35
                    )
                )
                and abs(float(features.ego_speed)) < 0.40
            )
            if reverse_vehicle_observable_far_static_open_side:
                self.state = "AVOID_OR_PASS"
                if features.lidar_open_side == "right":
                    steer_bias = 0.24
                elif features.lidar_open_side == "left":
                    steer_bias = -0.24
                else:
                    steer_bias = 0.0
                close_static_escape = (
                    5.0 <= float(features.front_obstacle_distance) <= 6.5
                    and features.lidar_open_side in ("right", "left")
                    and features.lidar_blockage_ratio >= 0.95
                    and features.lidar_center_blockage_ratio >= 0.95
                )
                false_static_close_reverse = (
                    estimate.macro_scenario == "reverse_vehicle"
                    and not features.reversing_vehicle_evidence
                    and features.lidar_open_side in ("right", "left")
                    and 4.20 < float(features.front_obstacle_distance) <= 6.80
                    and abs(float(features.ego_speed)) < 0.18
                    and features.lidar_blockage_ratio >= 0.95
                    and features.lidar_center_blockage_ratio >= 0.95
                )
                if false_static_close_reverse:
                    forward_steer = 0.20 if features.lidar_open_side == "right" else -0.20
                    return PlannerAction(
                        True,
                        self.state,
                        target_speed=1.4,
                        throttle_cap=0.52,
                        throttle_floor=0.34,
                        brake_cap=0.0,
                        steer_limit=0.30,
                        steer_bias=forward_steer,
                        steer_min_magnitude=0.12,
                        reason="reverse_vehicle_false_static_far_open_side_forward_clearance",
                    )
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.2 if close_static_escape else (2.0 if float(features.front_obstacle_distance) > 6.50 else 1.6),
                    throttle_cap=0.62 if close_static_escape else (0.55 if float(features.front_obstacle_distance) > 6.50 else 0.44),
                    throttle_floor=0.46 if close_static_escape else (0.30 if float(features.front_obstacle_distance) > 6.50 else 0.26),
                    brake_cap=0.0,
                    steer_limit=0.42 if close_static_escape else 0.36,
                    steer_bias=(0.34 if features.lidar_open_side == "right" else -0.34) if close_static_escape else steer_bias,
                    steer_min_magnitude=0.24 if close_static_escape else (0.12 if float(features.front_obstacle_distance) > 6.50 else (0.16 if features.lidar_open_side != "balanced" else 0.0)),
                    reason="reverse_vehicle_close_static_open_side_escape" if close_static_escape else ("reverse_vehicle_far_static_open_side_creep" if float(features.front_obstacle_distance) > 6.50 else "reverse_vehicle_observable_far_static_open_side_probe"),
                )
            false_reverse_far_static_open_side_commit = (
                estimate.macro_scenario == "reverse_vehicle"
                and not features.reversing_vehicle_evidence
                and features.front_pedestrian_distance is None
                and features.front_vehicle_distance is None
                and features.front_obstacle_distance is not None
                and 6.5 <= float(features.front_obstacle_distance) <= 8.5
                and 0.40 <= abs(float(features.ego_speed)) <= 1.20
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.lidar_available
                and not features.lidar_stale
                and features.lidar_blockage_ratio >= 0.90
                and features.lidar_center_blockage_ratio >= 0.85
                and features.lidar_open_side in ("right", "left")
                and (
                    (
                        features.lidar_open_side == "right"
                        and features.lidar_left_blockage_ratio >= 0.85
                        and features.lidar_right_blockage_ratio <= 0.22
                    )
                    or (
                        features.lidar_open_side == "left"
                        and features.lidar_right_blockage_ratio >= 0.85
                        and features.lidar_left_blockage_ratio <= 0.22
                    )
                )
            )
            if false_reverse_far_static_open_side_commit:
                self.state = "AVOID_OR_PASS"
                self.last_open_side = features.lidar_open_side
                self.open_side_pass_memory_frames = self.config.lidar_open_side_pass_memory_frames
                self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
                steer_bias = 0.26 if features.lidar_open_side == "right" else -0.26
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=2.2,
                    throttle_cap=0.66,
                    throttle_floor=0.46,
                    brake_cap=0.0,
                    steer_limit=0.55,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.20,
                    reason="false_reverse_far_static_open_side_forward_commit",
                )
            reverse_observed_only_close_stuck = (
                features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and features.front_obstacle_distance is not None
                and 1.0 <= float(features.front_obstacle_distance) <= 1.8
                and features.lidar_available
                and not features.lidar_stale
                and features.lidar_blockage_ratio >= 0.95
                and features.lidar_center_blockage_ratio >= 0.95
                and features.lidar_open_side in ("right", "left")
                and abs(features.ego_speed) < 0.08
            )
            if reverse_observed_only_close_stuck:
                self.reverse_vehicle_observed_only_close_stuck_frames += 1
            elif (
                features.front_obstacle_distance is None
                or float(features.front_obstacle_distance) > 2.4
                or abs(features.ego_speed) > 0.35
            ):
                self.reverse_vehicle_observed_only_close_stuck_frames = 0
            if self.reverse_vehicle_observed_only_close_stuck_frames >= 8:
                self.state = "AVOID_OR_PASS"
                self.reverse_unwedge_frames = max(self.reverse_unwedge_frames, 80)
                steer_bias = -0.38 if features.lidar_open_side == "right" else 0.38
                return PlannerAction(
                    True,
                    self.state,
                    throttle_cap=0.58,
                    throttle_floor=0.42,
                    brake_cap=0.0,
                    steer_limit=0.52,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.30,
                    reverse=True,
                    reason="reverse_vehicle_observed_only_close_stuck_backout",
                )
            reverse_observed_far_clear_route_prior_resume = (
                self.config.allow_route_prior
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
                and (
                    features.front_obstacle_distance is None
                    or float(features.front_obstacle_distance) >= 8.0
                )
                and abs(features.ego_speed) < 0.25
            )
            if reverse_observed_far_clear_route_prior_resume:
                self.state = "RECOVER"
                if features.lidar_open_side == "right":
                    steer_bias = 0.10
                elif features.lidar_open_side == "left":
                    steer_bias = -0.10
                else:
                    steer_bias = max(-0.10, min(0.10, float(getattr(features, "lidar_lateral_centroid", 0.0) or 0.0)))
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=3.0,
                    throttle_cap=0.86,
                    throttle_floor=0.62,
                    brake_cap=0.0,
                    steer_limit=0.24,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.0,
                    reason="reverse_vehicle_observed_only_far_clear_route_prior_resume",
                )
            return PlannerAction(False, self.state, reason="reverse_vehicle_observed_only")

        close_open_side_reverse_continuation = (
            estimate.macro_scenario in (
                "trucks_encountered_during_construction",
                "high_speed_temporary_construction",
                        )
                        and not roundabout_layout_context
                        and self.config.lidar_open_side_nudge_enabled
            and self.reverse_unwedge_frames > 0
            and features.front_obstacle_distance is not None
            and 1.5 <= float(features.front_obstacle_distance) <= 3.6
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and features.ego_speed < 0.90
            and features.lidar_blockage_ratio >= 0.80
            and features.lidar_center_blockage_ratio >= 0.80
            and features.lidar_open_side in ("right", "left")
            and self.last_open_side in ("unknown", features.lidar_open_side)
        )
        if close_open_side_reverse_continuation:
            self.reverse_unwedge_frames -= 1
            self.open_side_pass_memory_frames = self.config.lidar_open_side_pass_memory_frames
            self.close_obstacle_memory_frames = self.config.lidar_open_side_close_memory_frames
            self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
            self.post_pass_frames = self.config.lidar_open_side_post_pass_frames
            self.last_open_side = features.lidar_open_side
            self.state = "AVOID_OR_PASS"
            steer_magnitude = 0.35
            steer_bias = -steer_magnitude if features.lidar_open_side == "right" else steer_magnitude
            return PlannerAction(
                True,
                self.state,
                throttle_cap=0.40,
                throttle_floor=0.30,
                brake_cap=0.0,
                steer_limit=0.55,
                steer_bias=steer_bias,
                steer_min_magnitude=steer_magnitude,
                reverse=True,
                reason="construction_open_side_reverse_unwedge",
            )

        construction_balanced_cone_forward_escape = (
            estimate.macro_scenario in (
                "trucks_encountered_during_construction",
                "high_speed_temporary_construction",
            )
            and not roundabout_layout_context
            and self.config.lidar_open_side_nudge_enabled
            and features.front_obstacle_distance is not None
            and 3.6 < float(features.front_obstacle_distance) <= 5.2
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and abs(features.ego_speed) < 0.90
            and features.detection_object_count >= 80
            and features.lidar_available
            and not features.lidar_stale
            and features.lidar_blockage_ratio <= 0.35
            and features.lidar_center_blockage_ratio <= 0.20
            and features.lidar_open_side in ("balanced", "right", "left")
        )
        if construction_balanced_cone_forward_escape:
            self.state = "AVOID_OR_PASS"
            self.construction_post_pass_memory_frames = max(self.construction_post_pass_memory_frames, 260)
            self.construction_corridor_memory_frames = max(self.construction_corridor_memory_frames, 260)
            self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
            backward_or_stalled = features.ego_speed < 0.05
            if features.lidar_open_side == "right":
                self.last_open_side = "right"
                steer_bias = 0.22 if backward_or_stalled else 0.18
                steer_min = 0.16 if backward_or_stalled else 0.12
            elif features.lidar_open_side == "left":
                self.last_open_side = "left"
                steer_bias = -0.22 if backward_or_stalled else -0.18
                steer_min = 0.16 if backward_or_stalled else 0.12
            else:
                lateral_centroid = float(getattr(features, "lidar_lateral_centroid", 0.0) or 0.0)
                left_density = int(getattr(features, "lidar_left_density", 0) or 0)
                right_density = int(getattr(features, "lidar_right_density", 0) or 0)
                if lateral_centroid <= -0.20 or left_density >= right_density + 3:
                    inferred_open_side = "right"
                elif lateral_centroid >= 0.20 or right_density >= left_density + 3:
                    inferred_open_side = "left"
                elif self.last_open_side in ("right", "left"):
                    inferred_open_side = self.last_open_side
                else:
                    inferred_open_side = "right" if (self.blocked_frames // 80) % 2 == 0 else "left"
                self.last_open_side = inferred_open_side
                if self.blocked_frames >= 70 and backward_or_stalled and 4.0 <= float(features.front_obstacle_distance) <= 5.2:
                    reverse_phase = self.blocked_frames % 90 < 24
                    if reverse_phase:
                        reverse_steer = -0.34 if inferred_open_side == "right" else 0.34
                        return PlannerAction(
                            True,
                            self.state,
                            throttle_cap=0.48,
                            throttle_floor=0.34,
                            brake_cap=0.0,
                            steer_limit=0.52,
                            steer_bias=reverse_steer,
                            steer_min_magnitude=0.24,
                            reverse=True,
                            reason="construction_balanced_cone_reverse_setback",
                        )
                if inferred_open_side == "right":
                    steer_bias = 0.34 if backward_or_stalled else 0.24
                else:
                    steer_bias = -0.34 if backward_or_stalled else -0.24
                steer_min = 0.24 if backward_or_stalled else 0.12
            return PlannerAction(
                True,
                self.state,
                target_speed=2.0 if backward_or_stalled else 2.2,
                throttle_cap=0.68 if backward_or_stalled else 0.66,
                throttle_floor=0.46 if backward_or_stalled else 0.42,
                brake_cap=0.0,
                steer_limit=0.50 if backward_or_stalled else 0.34,
                steer_bias=steer_bias,
                steer_min_magnitude=steer_min,
                reason="construction_balanced_cone_forward_escape",
            )

        construction_open_side_vehicle_memory_escape = (
            estimate.macro_scenario in (
                "trucks_encountered_during_construction",
                "high_speed_temporary_construction",
            )
            and self.config.lidar_open_side_nudge_enabled
            and self.open_side_pass_memory_frames > 0
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and features.ego_speed < 1.20
            and features.lidar_blockage_ratio >= 0.85
            and features.lidar_center_blockage_ratio >= 0.85
            and features.lidar_open_side in ("right", "left")
            and self.last_open_side == features.lidar_open_side
            and (
                (
                    features.lidar_open_side == "right"
                    and features.lidar_left_blockage_ratio >= 0.85
                    and features.lidar_right_blockage_ratio <= 0.20
                )
                or (
                    features.lidar_open_side == "left"
                    and features.lidar_right_blockage_ratio >= 0.85
                    and features.lidar_left_blockage_ratio <= 0.20
                )
            )
            and (
                (
                    features.front_obstacle_distance is not None
                    and 1.8 <= float(features.front_obstacle_distance) <= 3.2
                )
                or (
                    features.front_vehicle_distance is not None
                    and 1.8 <= float(features.front_vehicle_distance) <= 3.2
                )
            )
        )
        if construction_open_side_vehicle_memory_escape:
            self.open_side_pass_memory_frames = self.config.lidar_open_side_pass_memory_frames
            self.close_obstacle_memory_frames = self.config.lidar_open_side_close_memory_frames
            self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
            self.post_pass_frames = self.config.lidar_open_side_post_pass_frames
            self.state = "AVOID_OR_PASS"
            escape_distance = (
                features.front_obstacle_distance
                if features.front_obstacle_distance is not None
                else features.front_vehicle_distance
            )
            near_distant_escape = (
                self.config.distant_lidar_creep_enabled
                and escape_distance is not None
                and float(escape_distance) <= 4.2
            )
            near_blocked_escape = (
                escape_distance is not None
                and float(escape_distance) <= 3.2
                and abs(features.ego_speed) < 0.12
            )
            if (near_distant_escape and abs(features.ego_speed) < 0.05) or near_blocked_escape:
                self.blocked_frames += 1
            else:
                self.blocked_frames = 0
            if near_blocked_escape and self.blocked_frames >= 12:
                self.reverse_unwedge_frames = 26
                self.blocked_frames = 0
            if near_distant_escape and self.blocked_frames >= 45:
                self.reverse_unwedge_frames = 20
                self.blocked_frames = 0
            if near_distant_escape and escape_distance is not None and float(escape_distance) <= 4.1 and abs(features.ego_speed) < 1.20:
                self.reverse_unwedge_frames = max(self.reverse_unwedge_frames, 24)
            if (near_distant_escape or near_blocked_escape) and self.reverse_unwedge_frames > 0:
                if estimate.macro_scenario == "trucks_encountered_during_construction":
                    self.reverse_unwedge_frames = max(0, self.reverse_unwedge_frames - 1)
                    steer_magnitude = 0.46
                    steer_bias = steer_magnitude if features.lidar_open_side == "right" else -steer_magnitude
                    return PlannerAction(
                        True,
                        self.state,
                        target_speed=2.5,
                        throttle_cap=0.88,
                        throttle_floor=0.66,
                        brake_cap=0.0,
                        steer_limit=0.68,
                        steer_bias=steer_bias,
                        steer_min_magnitude=0.34,
                        reason="construction_open_side_forward_unwedge",
                    )
                self.reverse_unwedge_frames -= 1
                steer_magnitude = 0.35
                steer_bias = -steer_magnitude if features.lidar_open_side == "right" else steer_magnitude
                return PlannerAction(
                    True,
                    self.state,
                    throttle_cap=0.40,
                    throttle_floor=0.30,
                    brake_cap=0.0,
                    steer_limit=0.55,
                    steer_bias=steer_bias,
                    steer_min_magnitude=steer_magnitude,
                    reverse=True,
                    reason="construction_open_side_reverse_unwedge",
                )
            steer_magnitude = 0.55 if near_distant_escape else 0.25
            steer_bias = steer_magnitude if features.lidar_open_side == "right" else -steer_magnitude
            return PlannerAction(
                True,
                self.state,
                target_speed=1.8,
                throttle_cap=0.58,
                throttle_floor=0.36,
                brake_cap=0.0,
                steer_limit=0.80 if near_distant_escape else 0.45,
                steer_bias=steer_bias,
                steer_min_magnitude=steer_magnitude,
                reason="construction_full_blockage_open_side_escape",
            )

        if (
            estimate.macro_scenario == "trucks_encountered_during_construction"
            and not roundabout_layout_context
            and features.front_vehicle_distance is not None
            and features.front_vehicle_distance >= 2.0
            and not features.reversing_vehicle_evidence
            and (features.front_vehicle_ttc is None or features.front_vehicle_ttc >= 3.5)
            and features.ego_speed < 4.0
        ):
            vehicle_observed_open_side_push = (
                features.front_obstacle_distance is not None
                and float(features.front_obstacle_distance) <= 5.6
                and (
                    float(features.front_obstacle_distance) <= 5.0
                    or float(features.front_vehicle_distance) >= 8.0
                )
                and abs(features.ego_speed) < 0.80
                and features.lidar_available
                and not features.lidar_stale
                and features.lidar_blockage_ratio >= 0.85
                and features.lidar_center_blockage_ratio >= 0.85
                and features.lidar_open_side in ("right", "left")
                and (
                    (
                        features.lidar_open_side == "right"
                        and features.lidar_left_blockage_ratio >= 0.85
                        and features.lidar_right_blockage_ratio <= 0.20
                    )
                    or (
                        features.lidar_open_side == "left"
                        and features.lidar_right_blockage_ratio >= 0.85
                        and features.lidar_left_blockage_ratio <= 0.20
                    )
                )
                and features.front_pedestrian_distance is None
                and features.red_stop_distance is None
                and not features.red_light_active
            )
            if vehicle_observed_open_side_push:
                self.state = "AVOID_OR_PASS"
                self.last_open_side = features.lidar_open_side
                self.open_side_pass_memory_frames = self.config.lidar_open_side_pass_memory_frames
                self.close_obstacle_memory_frames = self.config.lidar_open_side_close_memory_frames
                self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
                steer_bias = 0.18 if features.lidar_open_side == "right" else -0.18
                return PlannerAction(
                    True,
                    self.state,
                    target_speed=1.2,
                    throttle_cap=0.34,
                    throttle_floor=0.22,
                    brake_cap=0.0,
                    steer_limit=0.42,
                    steer_bias=steer_bias,
                    steer_min_magnitude=0.16,
                    reason="construction_vehicle_open_side_push_release",
                )
            self.state = "PREPARE"
            self.static_creep_frames = 0
            self.close_obstacle_memory_frames = 0
            self.progress_recovery_frames = 0
            self.open_side_pass_memory_frames = 0
            return PlannerAction(False, self.state, reason="construction_vehicle_observed_without_confirmed_collision")

        construction_far_side_blockage_push = (
            estimate.macro_scenario in (
                "trucks_encountered_during_construction",
                "high_speed_temporary_construction",
            )
            and features.front_obstacle_distance is not None
            and 6.0 <= float(features.front_obstacle_distance) <= 13.5
            and abs(features.ego_speed) < 0.80
            and self.red_final_context_frames > 0
            and features.front_vehicle_distance is None
            and features.front_pedestrian_distance is None
            and features.red_stop_distance is None
            and not features.red_light_active
            and features.lidar_available
            and not features.lidar_stale
            and features.lidar_blockage_ratio >= 0.85
            and features.lidar_open_side in ("right", "left")
            and (
                (
                    features.lidar_open_side == "right"
                    and features.lidar_left_blockage_ratio >= 0.80
                    and features.lidar_right_blockage_ratio <= 0.25
                )
                or (
                    features.lidar_open_side == "left"
                    and features.lidar_right_blockage_ratio >= 0.80
                    and features.lidar_left_blockage_ratio <= 0.25
                )
            )
        )
        if construction_far_side_blockage_push:
            self.state = "AVOID_OR_PASS"
            self.last_open_side = features.lidar_open_side
            self.open_side_pass_memory_frames = self.config.lidar_open_side_pass_memory_frames
            self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
            steer_bias = 0.22 if features.lidar_open_side == "right" else -0.22
            return PlannerAction(
                True,
                self.state,
                target_speed=2.6,
                throttle_cap=0.82,
                throttle_floor=0.58,
                brake_cap=0.0,
                steer_limit=0.45,
                steer_bias=steer_bias,
                steer_min_magnitude=0.18,
                reason="construction_far_side_blockage_forward_push",
            )

        if features.immediate_hazard:
            self.state = "EMERGENCY" if features.risk_level >= 3 else "YIELD_OR_BRAKE"
            # Pedestrian / bicycle hazards need yielding, but hard braking for the
            # whole detection window caused route-75 blocking in closed loop. Use
            # emergency braking only for very close objects; otherwise crawl/yield.
            if features.front_pedestrian_distance is not None:
                if features.front_pedestrian_distance < 3.5:
                    return PlannerAction(True, self.state, throttle_cap=0.0, brake=0.85, reason=estimate.reason)
                return PlannerAction(True, "YIELD_OR_BRAKE", target_speed=0.8, throttle_cap=0.12, brake=0.35, steer_limit=0.40, reason=estimate.reason)
            if features.front_vehicle_distance is not None:
                if (
                    estimate.macro_scenario == "reverse_vehicle"
                    and features.reversing_vehicle_evidence
                    and features.front_vehicle_ttc is not None
                    and features.front_vehicle_ttc < 3.5
                ):
                    return PlannerAction(True, "YIELD_OR_BRAKE", throttle_cap=0.0, brake=0.35, steer_limit=0.60, reason=estimate.reason)
                if features.front_vehicle_distance < 2.0:
                    return PlannerAction(True, self.state, throttle_cap=0.0, brake=0.65, steer_limit=0.60, reason=estimate.reason)
                return PlannerAction(True, "YIELD_OR_BRAKE", target_speed=1.8, throttle_cap=0.28, brake=0.0, steer_limit=0.75, reason=estimate.reason)
            if features.front_obstacle_distance is not None:
                return PlannerAction(False, "PREPARE", reason="static_obstacle_observed_without_confirmed_collision")
            return PlannerAction(True, self.state, throttle_cap=0.0, brake=0.75, reason=estimate.reason)

        if not features.front_clear:
            previous_state = self.state
            self.state = "PREPARE"
            static_only = (
                features.front_obstacle_distance is not None
                and features.front_vehicle_distance is None
                and features.front_pedestrian_distance is None
            )
            if static_only:
                obstacle_distance = float(features.front_obstacle_distance)
                current_open_side = features.lidar_open_side if features.lidar_open_side in ("right", "left") else self.last_open_side
                red_or_stop_conflict = bool(features.red_light_active or features.red_stop_distance is not None)
                center_full_blockage = features.lidar_center_blockage_ratio >= 0.90
                low_conf_construction = (
                    estimate.macro_scenario == "trucks_encountered_during_construction"
                    and estimate.confidence < 0.80
                    and obstacle_distance > 7.0
                    and center_full_blockage
                )
                if low_conf_construction and features.ego_speed > 2.0:
                    self.low_conf_construction_suppress_frames = 40
                elif self.low_conf_construction_suppress_frames > 0:
                    self.low_conf_construction_suppress_frames -= 1
                construction_open_side_confident = not low_conf_construction
                roundabout_layout_context = bool(
                    roundabout_layout_context
                    or estimate.macro_scenario == "roundabout"
                    or (features.junction_like and abs(features.route_curvature) >= 1.0)
                )
                construction_open_side_allowed = (
                    construction_open_side_confident
                    and not red_or_stop_conflict
                    and not roundabout_layout_context
                )
                construction_lateral_layout_override = (
                    construction_open_side_confident
                    and not red_or_stop_conflict
                    and estimate.macro_scenario == "trucks_encountered_during_construction"
                    and estimate.confidence >= 0.80
                    and 3.2 <= obstacle_distance <= 4.35
                    and abs(features.ego_speed) < 0.12
                    and features.front_vehicle_distance is None
                    and features.front_pedestrian_distance is None
                    and features.lidar_available
                    and not features.lidar_stale
                    and features.lidar_blockage_ratio >= 0.85
                    and features.lidar_center_blockage_ratio >= 0.55
                    and current_open_side in ("right", "left")
                    and (
                        (
                            current_open_side == "right"
                            and features.lidar_left_blockage_ratio >= 0.80
                            and features.lidar_right_blockage_ratio <= 0.25
                        )
                        or (
                            current_open_side == "left"
                            and features.lidar_right_blockage_ratio >= 0.80
                            and features.lidar_left_blockage_ratio <= 0.25
                        )
                    )
                )
                construction_lateral_open_side_stall = (
                    (construction_open_side_allowed or construction_lateral_layout_override)
                    and self.config.lidar_open_side_nudge_enabled
                    and estimate.macro_scenario in (
                        "trucks_encountered_during_construction",
                        "high_speed_temporary_construction",
                    )
                    and 3.2 <= obstacle_distance <= 4.35
                    and abs(features.ego_speed) < 0.12
                    and features.lidar_blockage_ratio >= 0.85
                    and features.lidar_center_blockage_ratio >= 0.55
                    and current_open_side in ("right", "left")
                    and (
                        (
                            current_open_side == "right"
                            and features.lidar_left_blockage_ratio >= 0.80
                            and features.lidar_right_blockage_ratio <= 0.25
                        )
                        or (
                            current_open_side == "left"
                            and features.lidar_right_blockage_ratio >= 0.80
                            and features.lidar_left_blockage_ratio <= 0.25
                        )
                    )
                )
                if construction_lateral_open_side_stall:
                    self.blocked_frames += 1
                    self.open_side_pass_memory_frames = self.config.lidar_open_side_pass_memory_frames
                    self.close_obstacle_memory_frames = self.config.lidar_open_side_close_memory_frames
                    self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
                    self.post_pass_frames = self.config.lidar_open_side_post_pass_frames
                    self.last_open_side = current_open_side
                    self.state = "AVOID_OR_PASS"
                    if self.blocked_frames >= 8:
                        self.reverse_unwedge_frames = max(self.reverse_unwedge_frames, 48)
                    if self.reverse_unwedge_frames > 0:
                        if estimate.macro_scenario == "trucks_encountered_during_construction":
                            self.reverse_unwedge_frames = max(0, self.reverse_unwedge_frames - 1)
                            steer_magnitude = 0.44
                            steer_bias = steer_magnitude if current_open_side == "right" else -steer_magnitude
                            return PlannerAction(
                                True,
                                self.state,
                                target_speed=2.4,
                                throttle_cap=0.86,
                                throttle_floor=0.66,
                                brake_cap=0.0,
                                steer_limit=0.62,
                                steer_bias=steer_bias,
                                steer_min_magnitude=0.32,
                                reason="construction_lateral_open_side_forward_unwedge",
                            )
                        self.reverse_unwedge_frames -= 1
                        steer_magnitude = 0.38
                        steer_bias = -steer_magnitude if current_open_side == "right" else steer_magnitude
                        return PlannerAction(
                            True,
                            self.state,
                            throttle_cap=0.46,
                            throttle_floor=0.34,
                            brake_cap=0.0,
                            steer_limit=0.58,
                            steer_bias=steer_bias,
                            steer_min_magnitude=0.30,
                            reverse=True,
                            reason="construction_lateral_open_side_reverse_unwedge",
                        )
                    steer_bias = 0.20 if current_open_side == "right" else -0.20
                    return PlannerAction(
                        True,
                        self.state,
                        target_speed=1.2,
                        throttle_cap=0.38,
                        throttle_floor=0.22,
                        brake_cap=0.0,
                        steer_limit=0.42,
                        steer_bias=steer_bias,
                        steer_min_magnitude=0.16,
                        reason="construction_lateral_open_side_probe",
                    )
                construction_far_open_side_stall = (
                    construction_open_side_allowed
                    and self.config.lidar_open_side_nudge_enabled
                    and estimate.macro_scenario == "trucks_encountered_during_construction"
                    and 8.0 <= obstacle_distance <= 13.5
                    and abs(features.ego_speed) < 0.18
                    and features.lidar_available
                    and not features.lidar_stale
                    and features.lidar_blockage_ratio >= 0.50
                    and features.lidar_center_blockage_ratio >= 0.82
                    and current_open_side in ("right", "left")
                    and (
                        (
                            current_open_side == "right"
                            and features.lidar_left_blockage_ratio >= 0.38
                            and features.lidar_right_blockage_ratio <= 0.18
                        )
                        or (
                            current_open_side == "left"
                            and features.lidar_right_blockage_ratio >= 0.38
                            and features.lidar_left_blockage_ratio <= 0.18
                        )
                    )
                )
                if construction_far_open_side_stall:
                    self.blocked_frames += 1
                    self.open_side_pass_memory_frames = self.config.lidar_open_side_pass_memory_frames
                    self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
                    self.last_open_side = current_open_side
                    self.state = "AVOID_OR_PASS"
                    full_far_blockage_commit = (
                        10.5 <= obstacle_distance <= 12.2
                        and features.lidar_blockage_ratio >= 0.90
                        and features.lidar_center_blockage_ratio >= 0.50
                    )
                    steer_bias = (0.42 if full_far_blockage_commit else 0.26) if current_open_side == "right" else (-0.42 if full_far_blockage_commit else -0.26)
                    throttle_floor = 0.82 if full_far_blockage_commit else (0.34 if self.blocked_frames >= 6 else 0.26)
                    return PlannerAction(
                        True,
                        self.state,
                        target_speed=3.0 if full_far_blockage_commit else 1.6,
                        throttle_cap=1.0 if full_far_blockage_commit else 0.54,
                        throttle_floor=throttle_floor,
                        brake_cap=0.0,
                        steer_limit=0.72 if full_far_blockage_commit else 0.56,
                        steer_bias=steer_bias,
                        steer_min_magnitude=0.34 if full_far_blockage_commit else 0.22,
                        reason="construction_far_full_blockage_open_side_commit" if full_far_blockage_commit else "construction_far_open_side_stall_forward_push",
                    )
                stalled_observable_open_side_allowed = (
                    not red_or_stop_conflict
                    and abs(features.ego_speed) < 0.35
                    and features.front_vehicle_distance is None
                    and features.front_pedestrian_distance is None
                )
                red_center_geometry = (
                    estimate.macro_scenario == "trucks_encountered_during_construction"
                    and self.config.lidar_open_side_nudge_enabled
                    and not self.config.distant_lidar_creep_enabled
                    and center_full_blockage
                    and 1.5 <= obstacle_distance <= 3.8
                    and features.lidar_blockage_ratio >= 0.85
                    and features.ego_speed < 0.65
                )
                red_center_observed = (
                    features.red_light_active
                    and features.red_stop_distance is not None
                    and float(features.red_stop_distance) <= 3.2
                )
                if red_center_geometry and red_center_observed:
                    self.red_stop_hold_frames += 1
                    self.red_stop_gap_frames = 0
                elif red_center_geometry and self.red_stop_hold_frames > 0 and self.red_stop_gap_frames < 150:
                    self.red_stop_gap_frames += 1
                else:
                    self.red_stop_hold_frames = 0
                    self.red_stop_gap_frames = 0
                if red_center_geometry and self.red_stop_hold_frames >= 20 and self.red_stop_gap_frames < 150:
                    self.open_side_pass_memory_frames = 0
                    self.post_pass_frames = 0
                    self.close_obstacle_memory_frames = 0
                    self.progress_recovery_frames = 0
                    self.state = "RECOVER"
                    red_center_open_side = current_open_side if current_open_side in ("right", "left") else "unknown"
                    prolonged_hold = (
                        self.red_stop_hold_frames >= 60
                        and abs(features.ego_speed) < 0.08
                    )
                    if (
                        prolonged_hold
                        and red_center_open_side == "unknown"
                        and abs(features.lidar_lateral_centroid) >= 0.05
                    ):
                        red_center_open_side = "right" if features.lidar_lateral_centroid < 0.0 else "left"
                    use_open_side_escape = prolonged_hold and red_center_open_side in ("right", "left")
                    hard_escape = prolonged_hold and self.red_stop_hold_frames >= 60
                    steer_bias = 0.52 if hard_escape and red_center_open_side == "right" else (
                        -0.52 if hard_escape and red_center_open_side == "left"
                        else (0.42 if red_center_open_side == "right" else (-0.42 if red_center_open_side == "left" else 0.0))
                    )
                    return PlannerAction(
                        True,
                        self.state,
                        target_speed=4.0 if hard_escape else (2.1 if prolonged_hold else 0.9),
                        throttle_cap=1.0 if hard_escape else (0.65 if prolonged_hold else 0.22),
                        throttle_floor=0.75 if hard_escape else (0.38 if prolonged_hold else 0.10),
                        brake=0.0 if hard_escape else None,
                        brake_cap=0.0,
                        steer_limit=0.90 if hard_escape and use_open_side_escape else (0.65 if use_open_side_escape else 0.12),
                        steer_bias=steer_bias if use_open_side_escape else 0.0,
                        steer_min_magnitude=0.60 if hard_escape and use_open_side_escape else (0.34 if use_open_side_escape else None),
                        reason="red_center_blockage_straight_creep",
                    )
                if (
                    (low_conf_construction or (center_full_blockage and 3.0 < obstacle_distance <= 12.0))
                    and self.config.lidar_open_side_nudge_enabled
                    and not self.config.distant_lidar_creep_enabled
                    and not red_or_stop_conflict
                    and features.ego_speed < 1.20
                ):
                    full_blockage_side_evidence = (
                        features.lidar_blockage_ratio >= 0.85
                        and features.lidar_center_blockage_ratio >= 0.85
                        and current_open_side in ("right", "left")
                        and (
                            (
                                current_open_side == "right"
                                and features.lidar_left_blockage_ratio >= 0.85
                                and features.lidar_right_blockage_ratio <= 0.20
                            )
                            or (
                                current_open_side == "left"
                                and features.lidar_right_blockage_ratio >= 0.85
                                and features.lidar_left_blockage_ratio <= 0.20
                            )
                        )
                    )
                    construction_full_blockage_open_side_escape = (
                        estimate.macro_scenario in (
                            "trucks_encountered_during_construction",
                            "high_speed_temporary_construction",
                        )
                        and 1.8 <= obstacle_distance <= 8.5
                        and features.front_vehicle_distance is None
                        and features.front_pedestrian_distance is None
                        and full_blockage_side_evidence
                    )
                    construction_full_blockage_memory_escape = (
                        estimate.macro_scenario in (
                            "trucks_encountered_during_construction",
                            "high_speed_temporary_construction",
                        )
                        and self.open_side_pass_memory_frames > 0
                        and features.front_vehicle_distance is None
                        and features.front_pedestrian_distance is None
                        and full_blockage_side_evidence
                        and self.last_open_side == current_open_side
                    )
                    if construction_full_blockage_open_side_escape or construction_full_blockage_memory_escape:
                        self.construction_full_blockage_escape_frames += 1
                        if obstacle_distance <= 3.2 and abs(features.ego_speed) < 0.12:
                            self.blocked_frames += 1
                        elif features.ego_speed > 0.30:
                            self.blocked_frames = 0
                        construction_guardrail_preventive_hold = (
                            estimate.macro_scenario == "trucks_encountered_during_construction"
                            and 2.7 <= obstacle_distance <= 4.2
                            and abs(features.ego_speed) < 0.90
                            and features.lidar_center_blockage_ratio >= 0.55
                            and full_blockage_side_evidence
                        )
                        if construction_guardrail_preventive_hold:
                            self.static_creep_frames = 0
                            self.open_side_pass_memory_frames = 0
                            self.close_obstacle_memory_frames = 0
                            self.progress_recovery_frames = 0
                            self.post_pass_frames = 0
                            self.last_open_side = current_open_side
                            self.state = "YIELD_OR_BRAKE"
                            return PlannerAction(
                                True,
                                self.state,
                                target_speed=0.0,
                                throttle_cap=0.0,
                                brake=0.38 if obstacle_distance <= 3.4 else 0.26,
                                steer_limit=0.06,
                                steer_bias=0.0,
                                reason="construction_guardrail_collision_preventive_hold",
                            )
                        if obstacle_distance <= 3.2 and self.blocked_frames >= 12:
                            self.reverse_unwedge_frames = max(self.reverse_unwedge_frames, 72)
                            self.blocked_frames = 0
                        if obstacle_distance <= 3.2 and self.reverse_unwedge_frames > 0:
                            self.reverse_unwedge_frames -= 1
                            self.static_creep_frames = 0
                            self.open_side_pass_memory_frames = self.config.lidar_open_side_pass_memory_frames
                            self.close_obstacle_memory_frames = self.config.lidar_open_side_close_memory_frames
                            self.progress_recovery_frames = self.config.lidar_open_side_progress_recovery_frames
                            self.post_pass_frames = self.config.lidar_open_side_post_pass_frames
                            self.last_open_side = current_open_side
                            self.state = "AVOID_OR_PASS"
                            steer_magnitude = 0.35
                            steer_bias = -steer_magnitude if current_open_side == "right" else steer_magnitude
                            return PlannerAction(
                                True,
                                self.state,
                                throttle_cap=0.40,
                                throttle_floor=0.30,
                                brake_cap=0.0,
                                steer_limit=0.55,
                                steer_bias=steer_bias,
                                steer_min_magnitude=steer_magnitude,
                                reverse=True,
                                reason="construction_open_side_reverse_unwedge",
                            )
                        self.static_creep_frames = 0
