    def _crazy_motor_event_corridor_pid_inputs(
        self, tick_data: Dict[str, Any]
    ) -> Optional[Any]:
        """Build a moving PID waypoint pair on the remembered event line."""
        anchor = self.crazy_motor_event_corridor_anchor_xy
        axis = self.crazy_motor_event_corridor_axis_xy
        if anchor is None or axis is None:
            return None
        try:
            ego_xy = np.asarray(tick_data.get("pos")[:2], dtype=float)
            if not np.all(np.isfinite(ego_xy)):
                return None
            anchor_arr = np.asarray(anchor, dtype=float)
            axis_arr = np.asarray(axis, dtype=float)
            rel = ego_xy - anchor_arr
            along = float(np.dot(rel, axis_arr))
            projection = anchor_arr + along * axis_arr
            synthetic_tick = dict(tick_data)
            synthetic_tick["command_near_xy"] = projection.tolist()
            synthetic_tick["command_far_xy"] = (
                projection + 20.0 * axis_arr
            ).tolist()
            lateral_error = float(
                axis_arr[0] * rel[1] - axis_arr[1] * rel[0]
            )
            return synthetic_tick, lateral_error
        except Exception:
            return None

    def _reverse_vehicle_remembered_route_pid_inputs(
        self, tick_data: Dict[str, Any]
    ) -> Optional[Any]:
        """Rebuild legal local PID inputs when terminal waypoints collapse.

        The anchor and axis were captured from live navigation at the start of
        the sensor-recognised interaction.  They are relative route memory,
        not an absolute coordinate or route identifier.
        """
        anchor = self.reverse_vehicle_bypass_start_pos
        axis = self.reverse_vehicle_bypass_start_axis
        if anchor is None or axis is None:
            return None
        try:
            ego_xy = np.asarray(tick_data.get("pos")[:2], dtype=float)
            anchor_arr = np.asarray(anchor, dtype=float)
            axis_arr = np.asarray(axis, dtype=float)
            axis_norm = float(np.linalg.norm(axis_arr))
            if (
                axis_norm <= 1e-6
                or not np.all(np.isfinite(ego_xy))
                or not np.all(np.isfinite(anchor_arr))
                or not np.all(np.isfinite(axis_arr))
            ):
                return None
            axis_arr = axis_arr / axis_norm
            rel = ego_xy - anchor_arr
            along = float(np.dot(rel, axis_arr))
            projection = anchor_arr + along * axis_arr
            synthetic_tick = dict(tick_data)
            synthetic_tick["command_near_xy"] = projection.tolist()
            synthetic_tick["command_far_xy"] = (
                projection + 20.0 * axis_arr
            ).tolist()
            lateral_error = float(
                axis_arr[0] * rel[1] - axis_arr[1] * rel[0]
            )
            return synthetic_tick, lateral_error
        except Exception:
            return None

    def _latch_highway_accident_route_corridor(
        self, tick_data: Dict[str, Any]
    ) -> None:
        """Remember a legal live route tangent for the post-accident tail."""
        if (
            self.highway_accident_route_anchor_xy is not None
            and self.highway_accident_route_axis_xy is not None
        ):
            return
        try:
            near_xy = np.asarray(tick_data.get("command_near_xy")[:2], dtype=float)
            far_xy = np.asarray(tick_data.get("command_far_xy")[:2], dtype=float)
            route_axis = self._forward_observable_route_axis(
                near_xy, far_xy, float(tick_data.get("compass"))
            )
            route_norm = float(np.linalg.norm(route_axis))
            if (
                route_norm <= 1.0
                or not np.all(np.isfinite(near_xy))
                or not np.all(np.isfinite(route_axis))
            ):
                return
            self.highway_accident_route_anchor_xy = near_xy.copy()
            self.highway_accident_route_axis_xy = route_axis / route_norm
        except Exception:
            return

