    def _update_highspeed_construction_route_corridor(
        self, tick_data: Dict[str, Any]
    ) -> None:
        """Keep the latest usable live route tangent for terminal PID use."""
        try:
            near_xy = np.asarray(
                tick_data.get("command_near_xy")[:2], dtype=float
            )
            far_xy = np.asarray(
                tick_data.get("command_far_xy")[:2], dtype=float
            )
            route_axis = self._forward_observable_route_axis(
                near_xy, far_xy, float(tick_data.get("compass"))
            )
            route_norm = float(np.linalg.norm(route_axis))
            if (
                route_norm <= 1.0
                or not np.all(np.isfinite(near_xy))
                or not np.all(np.isfinite(route_axis))
            ):
                return
            # Unlike the highway-accident memory, StaticBarrier follows a
            # long curve.  Refresh with every legal navigation tangent so the
            # remembered terminal direction is the last locally observed one.
            self.highspeed_construction_route_anchor_xy = near_xy.copy()
            self.highspeed_construction_route_axis_xy = (
                route_axis / route_norm
            )
        except Exception:
            return

